{"command": "cd /tmp/ty && python3 - <<'PY'
import pty, os, time, sys
def run(cmds):
    pid, fd = pty.fork()
    for c in cmds:
        os.write(fd, (c+"\n").encode())
        time.sleep(0.2)
    time.sleep(0.3)
    out = b""
    try:
        while True:
            d = os.read(fd, 4096)
            if not d: break
            out += d
    except OSError:
        pass
