    InRedirect(bool),
    // block openers
    Block, CaptureBlock, AsyncBlock,
    At,
    AmpBlock, DollarBlock,
    // command block tokens
    Word(Vec<u8>),
    // literals
    Int(i64), Float(f64), Char(u8), Str(Vec<u8>),
    Id(Vec<u8>),
    Kw(&'static str),
    // end
    Eof,
}

impl Tok {
    pub fn is_kw(&self, k: &str) -> bool {
        match self { Tok::Kw(s) => *s == k, _ => false }
    }
}

#[derive(Debug, Clone)]
pub struct Token {
    pub tok: Tok,
    pub line: usize,
    pub col: usize,
}

pub struct LexErr {
    pub line: usize,
    pub col: usize,
    pub msg: String,
}

pub struct Lexer<'a> {
    pub src: &'a [u8],
    pub pos: usize,
    pub line: usize,
    pub col: usize,
    pub depth: usize,      // command block nesting
    pub errors: Vec<LexErr>,
}

fn is_digit(b: u8) -> bool { b.is_ascii_digit() }
fn is_id_start(b: u8) -> bool { b.is_ascii_alphabetic() || b == b'_' }
fn is_id(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }
fn is_ws(b: u8) -> bool { b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' }

