    pub fn new(src: &'a [u8]) -> Self {
        Lexer { src, pos: 0, line: 0, col: 0, depth: 0, errors: Vec::new() }
    }

    fn peek(&self) -> u8 { if self.pos < self.src.len() { self.src[self.pos] } else { 0 } }
    fn peek_at(&self, n: usize) -> u8 { if self.pos + n < self.src.len() { self.src[self.pos + n] } else { 0 } }
