            if self.pos >= self.src.len() {
                out.push(Token { tok: Tok::Eof, line, col });
                break;
            }
            let b = self.peek();
            let t = if self.depth == 0 { self.next_out(b, line, col) } else { self.next_in(b, line, col) };
