            if !self.eof() { self.bump(); }
            self.pos = st; self.line = l; self.col = c;
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
            return match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            };
        }
        if isf {
            Tok::Float(txt.parse::<f64>().unwrap_or(f64::INFINITY))
        } else {
            match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            }
        }
    }

    fn unescape(&mut self, l: usize, c: usize, allow: &[u8]) -> u8 {
        let sc = self.col;
        self.bump(); // backslash
        let ch = self.cur();
        let v = match ch {
            b'n' => { self.bump(); 0x0a }
            b't' => { self.bump(); 0x09 }
            b'r' => { self.bump(); 0x0d }
            b'0' => { self.bump(); 0x00 }
            b'\'' if allow.contains(&b'\'') => { self.bump(); b'\'' }
            b'"' if allow.contains(&b'"') => { self.bump(); b'"' }
            b'\\' => { self.bump(); b'\\' }
            _ => { self.esc_err(l, sc, ch); self.bump(); 0 }
