            b'|' => { self.bump(); Some(Tok::Pipe) }
            b'?' => { self.bump(); Some(Tok::Question) }
            b'#' => { while !self.eof() && self.cur() != b'\n' { self.bump(); } None }
            b'"' => { let s = self.str_lit(l, c, false); Some(Tok::Str(s)) }
            b'\'' => { let s = self.str_lit_sq(l, c); Some(Tok::Word(vec![Part::Lit(s)])) }
            b'\\' => {
                self.bump();
                if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); return None; }
                let ch = self.bump();
                if ch == b'\n' { Some(Tok::Word(vec![Part::Lit(vec![b'\n'])])) }
                else { Some(Tok::Word(vec![Part::Lit(vec![ch])])) }
            }
            b'\n' => None,
            b'\'' => None,
            b'_' | b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'.' | b',' | b':' | b'=' | b'+'
                 | b'-' | b'_' | b'!' | b'^' | b'/' | b'%' | b'*' | b')' | b']' => self.word(),
            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn todo(&mut self, _l: usize, _c: usize) {
        self.aborted = true;
    }

    fn str_lit_sq(&mut self, l: usize, c: usize) -> Vec<u8> {
        let allow: &[u8] = &[b'\''];
        let mut out = Vec::new();
        self.bump();
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            let ch = self.cur();
            if ch == b'\'' { self.bump(); break; }
            if ch == b'\\' { out.push(self.unescape(l, c, allow)); continue; }
            out.push(self.bump());
        }
        out
    }

    fn word(&mut self) -> Option<Tok> {
        let mut parts: Vec<Part> = Vec::new();
        // opening char is not a special char
        let st = self.pos;
        let l = self.line; let c = self.col;
        // check for $ / & / ~ / @ prefixes handled by caller dispatch
        loop {
            if self.eof() { break; }
            let ch = self.cur();
            match ch {
                b' ' | b'\t' | b'\n' | b'\r' | b';' | b'#' | b'?' | b'>' | b'<' | b'"' | b'\''
                | b'\\' | b'$' | b'}' | b'|' | b'&' | b'@' | b'~' | b'{' | b'[' => break,
                _ => { let n = self.bump(); parts.push(Part::Lit(vec![n])); }
            }
        }
        if parts.is_empty() {
            self.err(l, c, format!("unexpected '{}'.", byte_disp(self.cur())));
            self.bump();
            return None;
        }
        // integer word?
        if let Ok(txt) = std::str::from_utf8(&self.src[st..self.pos]) {
            if !txt.is_empty() && txt.bytes().all(|b| b.is_ascii_digit()) {
                if let Ok(v) = txt.parse::<i64>() { return Some(Tok::Int(v)); }
                return Some(Tok::Word(parts));
            }
        }
        Some(Tok::Word(parts))
    }
}

pub fn byte_disp(b: u8) -> String {
    match b {
        b'\n' => "'\\n'".into(),
        b'\t' => "'\\t'".into(),
        b'\r' => "'\\r'".into(),
        _ => format!("'{}'", b as char),
    }
}
