            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn todo(&mut self, _l: usize, _c: usize) {
        self.aborted = true;
    }

    fn str_lit_sq(&mut self, l: usize, c: usize) -> Vec<u8> {
        let allow: &[u8] = &[b'\''];
        let mut out = Vec::new();
        self.bump();
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            let ch = self.cur();
            if ch == b'\'' { self.bump(); break; }
            if ch == b'\\' { out.push(self.unescape(l, c, allow)); continue; }
            out.push(self.bump());
        }
        out
    }

    fn word(&mut self) -> Option<Tok> {
        let mut parts: Vec<Part> = Vec::new();
        // opening char is not a special char
        let st = self.pos;
        let l = self.line; let c = self.col;
        // check for $ / & / ~ / @ prefixes handled by caller dispatch
        loop {
            if self.eof() { break; }
            let ch = self.cur();
            match ch {
                b' ' | b'\t' | b'\n' | b'\r' | b';' | b'#' | b'?' | b'>' | b'<' | b'"' | b'\''
                | b'\\' | b'$' | b'}' | b'|' | b'&' | b'@' | b'~' | b'{' | b'[' => break,
                _ => { let n = self.bump(); parts.push(Part::Lit(vec![n])); }
