use std::fmt::Write as _;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Kw {
    Let, Function, End, If, Then, ElseIf, Else, While, Do, For, In, Return, Break,
    And, Or, Not, True, False, Nil, Self_,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Part {
    Lit(Vec<u8>),
    Exp(Vec<u8>),
}

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Id(Vec<u8>),
    Int(i64),
    Float(f64),
    Char(u8),
    Str(Vec<u8>),
    Kw(Kw),
    LParen, RParen, LBracket, RBracket, Colon, Comma, Dot, Assign,
    Plus, Minus, Star, Slash, Percent,
    PlusPlus, EqEq, NotEq, Lt, Gt, Le, Ge,
    At,                 // @ (used in @[ )
    // command block tokens
    LBrace, RBrace, AmpBrace, DollarBrace,
    Pipe, Semi, Question,
    Word(Vec<Part>),    // word made of literal parts / $ expansions
    Dollar(Vec<u8>),    // $ident
    Redirect(Option<u8>, bool),   // (fd, append)
    InRedirect(bool),             // << is append-ish (here-string) -- bool = <<
    Amp, Eof,
}

pub struct Token {
    pub tok: Tok,
    pub line: usize,
    pub col: usize,
}

pub struct LexErr { pub line: usize, pub col: usize, pub msg: String }

const KEYWORDS: &[(&str, Kw)] = &[
    ("let", Kw::Let), ("function", Kw::Function), ("end", Kw::End), ("if", Kw::If),
    ("then", Kw::Then), ("elseif", Kw::ElseIf), ("else", Kw::Else), ("while", Kw::While),
    ("do", Kw::Do), ("for", Kw::For), ("in", Kw::In), ("return", Kw::Return),
    ("break", Kw::Break), ("and", Kw::And), ("or", Kw::Or), ("not", Kw::Not),
    ("true", Kw::True), ("false", Kw::False), ("nil", Kw::Nil), ("self", Kw::Self_),
];

fn is_idc(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }
fn is_ws(b: u8) -> bool { b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' }

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub line: usize,
    pub col: usize,
    depth: usize,
    pub errors: Vec<LexErr>,
    pub aborted: bool,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        Lexer { src, pos: 0, line: 0, col: 0, depth: 0, errors: Vec::new(), aborted: false }
    }
    fn cur(&self) -> u8 { if self.pos < self.src.len() { self.src[self.pos] } else { 0 } }
    fn at(&self, n: usize) -> u8 { if self.pos + n < self.src.len() { self.src[self.pos + n] } else { 0 } }
    fn eof(&self) -> bool { self.pos >= self.src.len() }
    fn bump(&mut self) -> u8 {
        let b = self.cur();
        if self.pos < self.src.len() {
            self.pos += 1;
            if b == b'\n' { self.line += 1; self.col = 0; } else { self.col += 1; }
        }
        b
    }
    fn err(&mut self, line: usize, col: usize, msg: String) { self.errors.push(LexErr { line, col, msg }); }
    fn esc_err(&mut self, line: usize, col: usize, c: u8) {
        let name = if c == 0 && self.eof() { "\\'".to_string() } else { format!("'\\{}'", c as char) };
        self.err(line, col, format!("invalid escape sequence {}.", name));
    }

    pub fn lex(&mut self) -> Vec<Token> {
        let mut out = Vec::new();
        loop {
            self.ws();
            let (l, c) = (self.line, self.col);
            if self.eof() { out.push(Token { tok: Tok::Eof, line: l, col: c }); break; }
            let b = self.cur();
            let t = if self.depth == 0 { self.out_tok(b, l, c) } else { self.in_tok(b, l, c) };
            match t { Some(t) => out.push(Token { tok: t, line: l, col: c }), None => {} }
        }
        out
    }

    fn ws(&mut self) {
        loop {
            while !self.eof() && is_ws(self.cur()) { self.bump(); }
            if self.cur() == b'#' { while !self.eof() && self.cur() != b'\n' { self.bump(); } continue; }
            break;
        }
    }

    // ================= outside command blocks =================
    fn out_tok(&mut self, b: u8, l: usize, c: usize) -> Option<Tok> {
        match b {
            b'(' => { self.bump(); Some(Tok::LParen) }
            b')' => { self.bump(); Some(Tok::RParen) }
            b'[' => { self.bump(); Some(Tok::LBracket) }
            b']' => { self.bump(); Some(Tok::RBracket) }
            b':' => { self.bump(); Some(Tok::Colon) }
            b',' => { self.bump(); Some(Tok::Comma) }
            b'=' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::EqEq) } else { Some(Tok::Assign) } }
            b'+' => { self.bump(); if self.cur() == b'+' { self.bump(); Some(Tok::PlusPlus) } else { Some(Tok::Plus) } }
            b'-' => { self.bump(); Some(Tok::Minus) }
            b'*' => { self.bump(); Some(Tok::Star) }
            b'/' => { self.bump(); Some(Tok::Slash) }
            b'%' => { self.bump(); Some(Tok::Percent) }
            b'<' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::Le) } else { Some(Tok::Lt) } }
            b'>' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::Ge) } else { Some(Tok::Gt) } }
            b'.' => { self.bump(); Some(Tok::Dot) }
            b'"' => { let s = self.str_lit(l, c, true); Some(Tok::Str(s)) }
            b'\'' => { let v = self.char_lit(l, c, true); Some(Tok::Char(v)) }
            b'|' => { self.bump(); self.err(l, c, "unexpected '|'.".into()); None }
            b'$' => { self.bump(); self.err(l, c, "unexpected '$'.".into()); None }
            b'&' => { self.bump(); self.err(l, c, "unexpected '&'.".into()); None }
            b';' => { self.bump(); self.err(l, c, "unexpected ';'.".into()); None }
            b'@' => { self.bump(); self.err(l, c, "unexpected '@'.".into()); None }
            b'~' => { self.bump(); self.err(l, c, "unexpected '~'.".into()); None }
            b'\\' => { self.bump(); self.err(l, c, "unexpected '\\'.".into()); None }
            b'}' => { self.bump(); self.err(l, c, "unexpected '}'.".into()); None }
            b'?' => { self.bump(); Some(Tok::Question) }
            b'_' | b'a'..=b'z' | b'A'..=b'Z' => self.ident(),
            b'0'..=b'9' => self.num(l, c),
            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn ident(&mut self) -> Tok {
        let st = self.pos;
        while !self.eof() && is_idc(self.cur()) { self.bump(); }
        let s = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("");
        for (k, kk) in KEYWORDS { if *k == s { return Tok::Kw(*kk); } }
        Tok::Id(self.src[st..self.pos].to_vec())
    }

    fn num(&mut self, l: usize, c: usize) -> Tok {
        let st = self.pos;
        while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
        let mut isf = false;
        if self.cur() == b'.' && self.at(1).is_ascii_digit() {
            self.bump();
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            isf = true;
        }
        if (self.cur() == b'e' || self.cur() == b'E') && self.at(1).is_ascii_digit() {
            self.bump();
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            isf = true;
        }
        let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
        if self.cur() == b'.' || self.cur() == b'e' || self.cur() == b'E' {
            // malformed: report at token start, skip one char, rescan the int part
            let bad = if self.eof() { "end of file".to_string() } else { format!("'{}'.", self.cur() as char) };
            self.err(l, c, format!("unexpected {}.", bad));
            if !self.eof() { self.bump(); }
            self.pos = st; self.line = l; self.col = c;
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
            return match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            };
        }
        if isf {
            Tok::Float(txt.parse::<f64>().unwrap_or(f64::INFINITY))
        } else {
            match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            }
        }
    }

    fn unescape(&mut self, l: usize, c: usize, allow: &[u8]) -> u8 {
        let sc = self.col;
        self.bump(); // backslash
        let ch = self.cur();
        let v = match ch {
            b'n' => { self.bump(); 0x0a }
            b't' => { self.bump(); 0x09 }
            b'r' => { self.bump(); 0x0d }
            b'0' => { self.bump(); 0x00 }
            b'\'' if allow.contains(&b'\'') => { self.bump(); b'\'' }
            b'"' if allow.contains(&b'"') => { self.bump(); b'"' }
            b'\\' => { self.bump(); b'\\' }
            _ => { self.esc_err(l, sc, ch); self.bump(); 0 }
        };
        v
    }

    fn str_lit(&mut self, l: usize, c: usize, normal: bool) -> Vec<u8> {
        let allow: &[u8] = if normal { &[b'\'', b'"'] } else { &[b'"'] };
        let mut out = Vec::new();
        self.bump();
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            let ch = self.cur();
            if ch == b'"' { self.bump(); break; }
            if ch == b'\\' { out.push(self.unescape(l, c, allow)); continue; }
            out.push(self.bump());
        }
        out
    }

    fn char_lit(&mut self, l: usize, c: usize, normal: bool) -> u8 {
        let allow: &[u8] = if normal { &[b'\'', b'"'] } else { &[b'\''] };
        self.bump();
        let mut v = 0u8;
        if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); return v; }
        if self.cur() == b'\\' { v = self.unescape(l, c, allow); }
        else { v = self.bump(); }
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            if self.cur() == b'\'' { self.bump(); break; }
            self.err(self.line, self.col, format!("unexpected '{}'.", self.cur() as char));
            self.bump();
        }
        v
    }

    // ================= inside command blocks =================
    fn in_tok(&mut self, b: u8, l: usize, c: usize) -> Option<Tok> {
        match b {
            b'{' => { self.bump(); self.depth += 1; Some(Tok::LBrace) }
            b'}' => { self.bump(); if self.depth > 0 { self.depth -= 1; } Some(Tok::RBrace) }
            b'(' => { self.bump(); Some(Tok::LParen) }
            b')' => { self.bump(); Some(Tok::RParen) }
            b'[' => { self.todo(l, c); None }
            b'>' => { self.bump(); let app = self.cur() == b'>'; if app { self.bump(); } Some(Tok::Redirect(None, app)) }
            b'<' => { self.bump(); let hr = self.cur() == b'<'; if hr { self.bump(); } Some(Tok::InRedirect(hr)) }
            b';' => { self.bump(); Some(Tok::Semi) }
            b'|' => { self.bump(); Some(Tok::Pipe) }
            b'?' => { self.bump(); Some(Tok::Question) }
            b'#' => { while !self.eof() && self.cur() != b'\n' { self.bump(); } None }
            b'"' => { let s = self.str_lit(l, c, false); Some(Tok::Str(s)) }
            b'\'' => { let s = self.str_lit_sq(l, c); Some(Tok::Word(vec![Part::Lit(s)])) }
            b'\\' => {
                self.bump();
                if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); return None; }
                let ch = self.bump();
                if ch == b'\n' { Some(Tok::Word(vec![Part::Lit(vec![b'\n'])])) }
                else { Some(Tok::Word(vec![Part::Lit(vec![ch])])) }
            }
            b'\n' => None,
            b'\'' => None,
            b'_' | b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'.' | b',' | b':' | b'=' | b'+'
                 | b'-' | b'_' | b'!' | b'^' | b'/' | b'%' | b'*' | b')' | b']' => self.word(),
            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn todo(&mut self, _l: usize, _c: usize) {
        self.aborted = true;
    }

    fn str_lit_sq(&mut self, l: usize, c: usize) -> Vec<u8> {
        let allow: &[u8] = &[b'\''];
        let mut out = Vec::new();
        self.bump();
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            let ch = self.cur();
            if ch == b'\'' { self.bump(); break; }
            if ch == b'\\' { out.push(self.unescape(l, c, allow)); continue; }
            out.push(self.bump());
        }
        out
    }

    fn word(&mut self) -> Option<Tok> {
        let mut parts: Vec<Part> = Vec::new();
        // opening char is not a special char
        let st = self.pos;
        let l = self.line; let c = self.col;
        // check for $ / & / ~ / @ prefixes handled by caller dispatch
        loop {
            if self.eof() { break; }
            let ch = self.cur();
            match ch {
                b' ' | b'\t' | b'\n' | b'\r' | b';' | b'#' | b'?' | b'>' | b'<' | b'"' | b'\''
                | b'\\' | b'$' | b'}' | b'|' | b'&' | b'@' | b'~' | b'{' | b'[' => break,
                _ => { let n = self.bump(); parts.push(Part::Lit(vec![n])); }
            }
        }
        if parts.is_empty() {
            self.err(l, c, format!("unexpected '{}'.", byte_disp(self.cur())));
            self.bump();
            return None;
        }
        // integer word?
        if let Ok(txt) = std::str::from_utf8(&self.src[st..self.pos]) {
            if !txt.is_empty() && txt.bytes().all(|b| b.is_ascii_digit()) {
                if let Ok(v) = txt.parse::<i64>() { return Some(Tok::Int(v)); }
                return Some(Tok::Word(parts));
            }
        }
        Some(Tok::Word(parts))
    }
}

pub fn byte_disp(b: u8) -> String {
    match b {
        b'\n' => "'\\n'".into(),
        b'\t' => "'\\t'".into(),
        b'\r' => "'\\r'".into(),
        _ => format!("'{}'", b as char),
    }
}
