                    loop {
                        let k = match self.peek().clone() { Tok::Id(n) => { let kp = self.cur_pos(); self.bump(); Expr::Var(n, kp) }, _ => { self.err_here("unexpected token, expected identifier"); self.parse_expr(0) } };
