{"command": "cat >> src/parser.rs <<'RSEOF'

impl<'a> Parser<'a> {
    // ---- command blocks ----
    pub fn parse_cmd_block(&mut self, open: Pos) -> CmdBlock {
        let mut cmds: Vec<Command> = Vec::new();
        let mut ill = false;
        if matches!(self.peek(), Tok::RBrace) {
            let p = self.cur_pos();
            self.errors.push(PErr { line: p.line, col: p.col, msg: "empty command block".to_string() });
            self.bump();
            return CmdBlock { kind: BlockKind::Plain, cmds, pos: open };
        }
        loop {
            let mut cmd = self.parse_command();
            // separator
            let mut semi = false;
            match self.peek() {
                Tok::Semi => { self.bump(); semi = true; }
                Tok::RBrace => { self.bump(); }
                _ => {
                    // error: unexpected token, skip to matching }
                    let p = self.cur_pos();
                    self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected '}'", tok_disp(self.peek())) });
                    cmd.ill_formed = true;
                    self.skip_to_rbrace();
                    cmds.push(cmd);
                    ill = true;
                    break;
                }
            }
            cmd.semi = semi;
            cmds.push(cmd);
            if !semi { break; }
        }
        let mut blk = CmdBlock { kind: BlockKind::Plain, cmds, pos: open };
        blk.ill_formed = ill;
        blk
    }

    fn skip_to_rbrace(&mut self) {
        // skip until matching }
        while !matches!(self.peek(), Tok::Eof | Tok::RBrace) { self.bump(); }
        if matches!(self.peek(), Tok::RBrace) { self.bump(); }
    }

    fn parse_command(&mut self) -> Command {
        let mut pipes: Vec<Pipeline> = Vec::new();
        let mut ends_line = false;
        let mut ill = false;
        loop {
            let seg = self.parse_segment();
            pipes.push(Pipeline { segs: vec![seg] });
            if matches!(self.peek(), Tok::Pipe) {
                self.bump();
                continue;
            }
            if matches!(self.peek(), Tok::Question) {
                ends_line = true;
                self.bump();
                match self.peek() {
                    Tok::Pipe => { self.bump(); continue; }
                    Tok::Semi => { self.bump(); return Command { pipes, ends_line, ill_formed: false, semi: true }; }
                    Tok::RBrace => { self.bump(); return Command { pipes, ends_line, ill_formed: false, semi: false }; }
                    _ => {
                        let p = self.cur_pos();
                        self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected '}}'", tok_disp(self.peek())) });
                        return Command { pipes, ends_line, ill_formed: true, semi: false };
                    }
                }
            }
            return Command { pipes, ends_line, ill_formed: false, semi: false };
        }
    }

    fn parse_segment(&mut self) -> Segment {
        let mut words: Vec<Word> = Vec::new();
        let mut redirs = Vec::new();
        let mut first = true;
        loop {
            match self.peek().clone() {
                Tok::Word(w) => { words.push(Word { parts: w }); self.bump(); }
                Tok::Str(v) => { words.push(Word { parts: vec![WPart::Lit { value: v, quote: b'"', src: vec![] }] }); self.bump(); }
                Tok::Id(n) => { words.push(Word { parts: vec![WPart::Lit { value: n, quote: 0, src: vec![] }] }); self.bump(); }
                Tok::Int(v) => {
                    let val = v;
                    // number followed by redirect op => fd
                    if !first && (matches!(self.peek_at(1), Tok::Redirect(_, _)) || matches!(self.peek_at(1), Tok::InRedirect(_))) {
                        if matches!(self.peek_at(1), Tok::InRedirect(_)) {
                            let p = self.cur_pos();
                            self.errors.push(PErr { line: p.line, col: p.col, msg: "unexpected '<', expected output redirection".to_string() });
                            self.bump(); self.bump();
                            continue;
                        }
                        if let Tok::Redirect(fd, app) = self.peek_at(1).clone() {
                            if val > 255 || val < 0 {
                                let p = self.cur_pos();
                                self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected output redirection", v) });
                                self.bump();
                                continue;
                            }
                            let f = fd.unwrap_or(1);
                            self.bump(); self.bump();
                            redirs.push(Redirect::Out { fd: val as u8, append: app, target: self.parse_redir_target(), is_num: false });
                            continue;
                        }
                        unreachable!()
                    }
                    words.push(Word { parts: vec![WPart::Lit { value: val.to_string().into_bytes(), quote: 0, src: vec![] }] });
                    self.bump();
                }
                Tok::Redirect(fd, app) => {
                    self.bump();
                    redirs.push(Redirect::Out { fd: fd.unwrap_or(1), append: app, target: self.parse_redir_target(), is_num: false });
                }
                Tok::InRedirect(here) => {
                    self.bump();
                    let t = self.parse_redir_target();
                    redirs.push(Redirect::In { target: t, here });
                }
                _ => break,
            }
            first = false;
        }
        if words.is_empty() {
            let p = self.cur_pos();
            self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected argument", tok_disp(self.peek())) });
        }
        Segment { words, redirs }
    }

    fn parse_redir_target(&mut self) -> Vec<u8> {
        match self.peek().clone() {
            Tok::Word(w) => {
                let mut s = Vec::new();
                for p in &w {
                    if let WPart::Lit { value, .. } = p { s.extend_from_slice(value); }
                    else if let WPart::Exp(n) = p { s.extend_from_slice(n); }
                }
                self.bump(); s
            }
            Tok::Str(v) => { self.bump(); v }
            Tok::Int(v) => { self.bump(); v.to_string().into_bytes() }
            Tok::Id(n) => { self.bump(); n }
            _ => {
                let p = self.cur_pos();
                self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected argument", tok_disp(self.peek())) });
                vec![]
            }
        }
    }
}

impl CmdBlock {
    pub fn set_kind(&mut self, k: BlockKind) { self.kind = k; }
}
RSEOF
