use crate::ast::*;
use crate::lexer::*;
use crate::colors::Cols;
use crate::Pos;
use std::fmt::Write as _;

// escape a byte string the way the runtime `repr` does
pub fn esc_bytes(b: &[u8], c: &Cols) -> String {
    let mut s = String::new();
    for &ch in b {
        match ch {
            b'\\' => s.push_str(c.bold("\\\\").as_str()),
            b'\'' => s.push_str(c.bold("\\'").as_str()),
            b'"' => s.push_str(c.bold("\\\"").as_str()),
            0 => s.push_str(c.bold("\\0").as_str()),
            b'\t' => s.push_str(c.bold("\\t").as_str()),
            b'\n' => s.push_str(c.bold("\\n").as_str()),
            b'\r' => s.push_str(c.bold("\\r").as_str()),
            0x01..=0x08 | 0x0b | 0x0c | 0x0e..=0x1f | 0x7f => {
                s.push_str(&c.bold(&format!("\\u{{{:x}}}", ch)));
            }
            _ => s.push(ch as char),
        }
    }
    s
}

pub struct Printer<'a> {
    pub c: &'a Cols,
    pub file: String,
    pub out: String,
    pub mode: Mode,   // Lex | Ast | Ir
}

#[derive(Clone, Copy, PartialEq)]
pub enum Mode { Lex, Ast, Ir }

impl<'a> Printer<'a> {
    pub fn new(c: &'a Cols, file: &str, mode: Mode) -> Self {
        Printer { c, file: file.to_string(), out: String::new(), mode }
    }
    fn w(&mut self, s: &str) { self.out.push_str(s); }
    fn wln(&mut self) { self.out.push('\n'); }

    // ---------------- lex printer ----------------
    pub fn print_tokens(&mut self, toks: &[Token]) {
        let sep = self.c.sep();
        self.w(&sep); self.wln();
        for t in toks {
            if matches!(t.tok, Tok::Eof) { continue; }
            self.w(&self.c.green(&self.file));
            self.w(&format!(" (line {}, column {}):\t", t.line, t.col));
            self.w(&self.tok_text(&t.tok));
            self.wln();
        }
        self.w(&sep); self.wln();
    }

    fn tok_text(&self, t: &Tok) -> String {
        let c = self.c;
        match t {
            Tok::Id(n) => c.green(&String::from_utf8_lossy(n)),
            Tok::Int(v) => v.to_string(),
            Tok::Float(v) => crate::fmt_disp(*v),
            Tok::Char(ch) => format!("'{}{}{}'", "", c.bold(&crate::repr_char(*ch, c)), ""),
            Tok::Str(s) => format!("\"{}\"", c.bold(&crate::repr_bytes(s))),
            Tok::Kw(k) => c.blue(crate::parser::kw_name(*k)),
            Tok::LParen => "(".into(), Tok::RParen => ")".into(),
            Tok::LBracket => "[".into(), Tok::RBracket => "]".into(),
            Tok::Colon => ":".into(), Tok::Comma => ",".into(), Tok::Assign => "=".into(),
            Tok::Plus => c.yellow("+"), Tok::Minus => c.yellow("-"), Tok::Star => c.yellow("*"),
            Tok::Slash => c.yellow("/"), Tok::Percent => c.yellow("%"),
            Tok::PlusPlus => c.yellow("++"), Tok::EqEq => c.yellow("=="), Tok::NotEq => c.yellow("!="),
            Tok::Lt => c.yellow("<"), Tok::Gt => c.yellow(">"), Tok::Le => c.yellow("<="), Tok::Ge => c.yellow(">="),
            Tok::Dot => c.yellow("."), Tok::At => "@[".into(),
            Tok::LBrace => "{".into(), Tok::RBrace => "}".into(),
            Tok::AmpBrace => "&{".into(), Tok::DollarBrace => "${".into(),
            Tok::Pipe => c.yellow("|"), Tok::Semi => ";".into(), Tok::Question => c.yellow("?"),
            Tok::Word(p) => self.word_lex_text(p),
            Tok::Glob(g) => c.yellow(&String::from_utf8_lossy(g)),
            Tok::Dollar(_) => "$".into(),
            Tok::Redirect(_, true) => c.yellow(">>"),
            Tok::Redirect(_, false) => c.yellow(">"),
            Tok::InRedirect(true) => c.yellow("<<"),
            Tok::InRedirect(false) => c.yellow("<"),
            Tok::Amp => c.yellow("&"),
            Tok::Eof => "".into(),
        }
    }

    fn word_lex_text(&self, parts: &[WPart]) -> String {
        let mut s = String::new();
        for p in parts {
            match p {
                WPart::Lit { value: _, quote, src } => {
                    if *quote == 0 { s.push_str(&String::from_utf8_lossy(src)); }
                    else { s.push_str(&format!("{}{}{}", *quote as char, String::from_utf8_lossy(src), *quote as char)); }
                }
                WPart::Exp(n) => { s.push_str("${{"); s.push_str(&self.c.green(&String::from_utf8_lossy(n))); s.push_str("}}"); }
            }
        }
        s
    }

    // ---------------- ast / ir printer ----------------
    pub fn print_block(&mut self, b: &Block, indent: usize, mode: Mode) {
        for st in &b.stmts { self.print_stmt(st, indent, mode); }
    }

    fn ind(&mut self, n: usize) { for _ in 0..n { self.w("\t"); } }

    pub fn print_stmt(&mut self, st: &Stmt, ind: usize, mode: Mode) {
        self.ind(ind);
        match st {
            Stmt::Let(name, e, _) => {
                self.w(&self.c.blue("let")); self.w(" ");
                match mode {
                    Mode::Ast => self.w(&self.c.green(&String::from_utf8_lossy(name))),
                    _ => { self.w(&self.c.green("#")); self.w(&self.c.green(&crate::slot_str(name))); }
                }
                self.w(" = ");
                self.print_expr(e, true, mode);
                self.wln();
            }
            Stmt::Assign(t, v, _) => {
                self.print_lvalue(t, mode);
                self.w(" = ");
                self.print_expr(v, true, mode);
                self.wln();
            }
            Stmt::Expr(e, _) => { self.print_expr(e, true, mode); self.wln(); }
            Stmt::If { cond, then, els, .. } => {
                self.w(&self.c.blue("if")); self.w(" ");
                self.print_expr(cond, false, mode);
                self.w(&self.c.blue(" ")); self.w(&self.c.blue("then")); self.wln();
                self.print_block(then, ind + 1, mode);
                if let Some(eb) = els {
                    self.ind(ind); self.w(&self.c.blue("else")); self.wln();
                    self.print_block(eb, ind + 1, mode);
                }
                self.ind(ind); self.w(&self.c.blue("end")); self.wln();
            }
            Stmt::While { cond, body, .. } => {
                self.w(&self.c.blue("while")); self.w(" ");
                self.print_expr(cond, false, mode);
                self.w(" "); self.w(&self.c.blue("do")); self.wln();
                self.print_block(body, ind + 1, mode);
                self.ind(ind); self.w(&self.c.blue("end")); self.wln();
            }
            Stmt::For { var, iter, body, .. } => {
                self.w(&self.c.blue("for")); self.w(" ");
                match mode {
                    Mode::Ast => self.w(&self.c.green(&String::from_utf8_lossy(var))),
                    _ => { self.w(&self.c.green("#")); self.w(&self.c.green(&crate::slot_str(var))); }
                }
                self.w(" "); self.w(&self.c.blue("in")); self.w(" ");
                self.print_expr(iter, false, mode);
                self.w(" "); self.w(&self.c.blue("do")); self.wln();
                self.print_block(body, ind + 1, mode);
                self.ind(ind); self.w(&self.c.blue("end")); self.wln();
            }
            Stmt::Return(e, _) => { self.w(&self.c.blue("return")); if !matches!(e, Expr::Nil(_)) { self.w(" "); self.print_expr(e, true, mode); } self.wln(); }
            Stmt::Break(_) => { self.w(&self.c.blue("break")); self.wln(); }
            Stmt::Cmd(cb, _) => { self.print_cmd(cb, ind, mode); }
            Stmt::Func(name, f, _) => {
                let _ = name;
                self.print_func(f, ind, mode);
            }
        }
    }

    fn print_lvalue(&mut self, e: &Expr, mode: Mode) {
        match e {
            Expr::Var(n, _) => match mode {
                Mode::Ast => self.w(&self.c.green(&String::from_utf8_lossy(n))),
                _ => { self.w(&self.c.green("#")); self.w(&self.c.green(&crate::slot_str(n))); }
            },
            Expr::Index(o, i, _) => {
                self.print_lvalue(o, mode);
                self.w("[");
                self.print_expr(i, false, mode);
                self.w("]");
            }
            Expr::Member(o, k, _) => {
                self.print_lvalue(o, mode);
                self.w(&self.c.yellow("."));
                self.w(&self.c.green(&String::from_utf8_lossy(k)));
            }
            Expr::Self_(p) => {
                match mode {
                    Mode::Ast => self.w(&self.c.blue("self")),
                    _ => { self.w(&self.c.green("#")); self.w(&self.c.green(&crate::slot_str_self(p))); }
                }
            }
            Expr::Paren(e2) => self.print_lvalue(e2, mode),
            _ => { self.w("***ill-formed***"); }
        }
    }

    pub fn print_expr(&mut self, e: &Expr, multi: bool, mode: Mode) {
        let c = self.c;
        match e {
            Expr::Nil(_) => self.w(&c.blue("nil")),
            Expr::Bool(b, _) => self.w(&c.blue(if *b { "true" } else { "false" })),
            Expr::Int(v, _) => self.w(&v.to_string()),
            Expr::Float(v, _) => self.w(&crate::fmt_disp(*v)),
            Expr::Char(ch, _) => { self.w("'"); self.w(&c.bold(&crate::repr_char(*ch, c))); self.w("'"); }
            Expr::Str(s, _) => { self.w("\""); self.w(&c.bold(&crate::repr_bytes(s))); self.w("\""); }
            Expr::Var(n, p) => match mode {
                Mode::Ast => self.w(&c.green(&String::from_utf8_lossy(n))),
                _ => { self.w(&c.green("#")); self.w(&c.green(&crate::slot_str(n))); }
            },
            Expr::Self_(_) => match mode {
                Mode::Ast => self.w(&c.blue("self")),
                _ => { self.w(&c.green("#")); self.w(&c.green(&crate::slot_str(b"self"))); }
            },
            Expr::Array(items, _) => self.print_array(items, multi, mode),
            Expr::Dict(items, _) => self.print_dict(items, multi, mode),
            Expr::Call(f, args, _) => {
                self.print_expr(f, false, mode);
                self.w("(");
                for (i, a) in args.iter().enumerate() { if i > 0 { self.w(", "); } self.print_expr(a, false, mode); }
                self.w(")");
            }
            Expr::Index(o, i, _) => {
                self.print_expr(o, false, mode);
                self.w("[");
                self.print_expr(i, false, mode);
                self.w("]");
            }
            Expr::Member(o, k, _) => {
                self.print_expr(o, false, mode);
                self.w(&c.yellow("."));
                self.w(&c.green(&String::from_utf8_lossy(k)));
            }
            Expr::Unary(op, v, _) => {
                self.w("(");
                match op {
                    UnOp::Not => { self.w(&c.blue("not")); }
                    UnOp::Neg => { self.w(&c.yellow("-")); }
                }
                self.w(" ");
                self.print_expr(v, false, mode);
                self.w(")");
            }
            Expr::Binary(op, a, b, _) => {
                self.w("(");
                self.print_expr(a, false, mode);
                self.w(" ");
                match op {
                    BinOp::And | BinOp::Or => self.w(&c.blue(op.sym())),
                    _ => self.w(&c.yellow(op.sym())),
                }
                self.w(" ");
                self.print_expr(b, false, mode);
                self.w(")");
            }
            Expr::Try(v, _) => { self.print_expr(v, multi, mode); self.w(&c.yellow("?")); }
            Expr::If(cond, then, els, _) => {
                self.w(&c.blue("if")); self.w(" ");
                self.print_expr(cond, false, mode);
                self.w(" "); self.w(&c.blue("then")); self.wln();
                self.print_block(then, 1, mode);
                if let Some(eb) = els {
                    self.w(&c.blue("else")); self.wln();
                    self.print_block(eb, 1, mode);
                }
                self.w(&c.blue("end"));
            }
            Expr::Func(f, _) => self.print_func(f, 0, mode),
            Expr::Cmd(cb, _) => self.print_cmd_inline(cb, mode),
        }
    }

    fn print_array(&mut self, items: &[Expr], multi: bool, mode: Mode) {
        if items.is_empty() { self.w("[]"); return; }
        if multi {
            self.w("[\n");
            for (i, it) in items.iter().enumerate() {
                self.ind(1); self.print_expr(it, true, mode);
                if i + 1 < items.len() { self.w(","); }
                self.w("\n");
            }
            self.w("]");
        } else {
            self.w("[ ");
            for (i, it) in items.iter().enumerate() { if i > 0 { self.w(", "); } self.print_expr(it, false, mode); }
            self.w(" ]");
        }
    }

    fn print_dict(&mut self, items: &[(Expr, Expr)], multi: bool, mode: Mode) {
        if items.is_empty() { self.w("@[]"); return; }
        if multi {
            self.w("@[\n");
            for (i, (k, v)) in items.iter().enumerate() {
                self.ind(1);
                if let Expr::Var(n, _) = k { self.w(&self.c.green(&String::from_utf8_lossy(n))); }
                else { self.print_expr(k, false, mode); }
                self.w(": ");
                self.print_expr(v, true, mode);
                if i + 1 < items.len() { self.w(","); }
                self.w("\n");
            }
            self.w("]");
        } else {
            self.w("@[ ");
            for (i, (k, v)) in items.iter().enumerate() {
                if i > 0 { self.w(", "); }
                if let Expr::Var(n, _) = k { self.w(&self.c.green(&String::from_utf8_lossy(n))); }
                else { self.print_expr(k, false, mode); }
                self.w(": ");
                self.print_expr(v, false, mode);
            }
            self.w(" ]");
        }
    }

    fn print_func(&mut self, f: &FuncLit, ind: usize, mode: Mode) {
        self.w(&self.c.blue("function"));
        self.w("(");
        match mode {
            Mode::Ast => {
                for (i, p) in f.params.iter().enumerate() { if i > 0 { self.w(", "); } self.w(&self.c.green(&String::from_utf8_lossy(p))); }
            }
            _ => { self.w(&format!("{}", f.params.len())); }
        }
        self.w(")"); self.wln();
        match mode {
            Mode::Ast => self.print_block(&f.body, ind + 1, mode),
            _ => {
                for (i, s) in crate::slots_of(f).iter().enumerate() {
                    self.ind(ind + 1);
                    self.w(&self.c.blue("let")); self.w(" ");
                    self.w(&self.c.green("#")); self.w(&self.c.green(&i.to_string()));
                    self.w(": ");
                    match s {
                        crate::SlotKind::Auto => self.w(&self.c.blue("auto")),
                        crate::SlotKind::Self_ => { self.w(&self.c.blue("auto")); self.w(" "); self.w(&self.c.green("self")); }
                        crate::SlotKind::Capture(n) => { self.w(&self.c.blue("capture")); self.w(" "); self.w(&self.c.green("#")); self.w(&self.c.green(&n.to_string())); }
                    }
                    self.wln();
                }
                self.print_block(&f.body, ind + 1, mode);
            }
        }
        self.ind(ind); self.w(&self.c.blue("end"));
    }

    fn print_cmd_inline(&mut self, cb: &CmdBlock, mode: Mode) {
        let kw = match cb.kind { BlockKind::Capture => "${", BlockKind::Async => "&{", _ => "{" };
        self.w(kw); self.wln();
        for (i, cmd) in cb.cmds.iter().enumerate() {
            self.ind(1);
            self.print_command(cmd, mode);
            if cmd.semi { self.w(";"); }
            if i + 1 < cb.cmds.len() { self.wln(); }
        }
        self.wln(); self.w("}");
        if cb.kind != BlockKind::Plain { self.w("}"); }
    }

    fn print_cmd(&mut self, cb: &CmdBlock, ind: usize, mode: Mode) {
        let kw = match cb.kind { BlockKind::Capture => "${", BlockKind::Async => "&{", _ => "{" };
        self.w(kw); self.wln();
        for (i, cmd) in cb.cmds.iter().enumerate() {
            self.ind(ind + 1);
            self.print_command(cmd, mode);
            if cmd.semi { self.w(";"); }
            if i + 1 < cb.cmds.len() || cb.kind != BlockKind::Plain { self.wln(); }
        }
        self.ind(ind); self.w("}");
        if cb.kind != BlockKind::Plain { self.w("}"); }
        if cb.kind == BlockKind::Async { /* .join() handled by caller */ }
        self.wln();
    }

    fn print_command(&mut self, cmd: &Command, mode: Mode) {
        if cmd.ill_formed { self.w("***ill-formed***"); }
        for (i, p) in cmd.pipes.iter().enumerate() {
            if i > 0 { self.w(&self.c.yellow(" | ")); }
            for (j, seg) in p.segs.iter().enumerate() {
                if j > 0 { self.w(&self.c.yellow(" | ")); }
                for (k, wd) in seg.words.iter().enumerate() {
                    if k > 0 { self.w(" "); }
                    self.print_word(wd, mode);
                }
                for r in &seg.redirs {
                    match r {
                        Redirect::Out { fd, append, target, is_num } => {
                            self.w(" ");
                            self.w(&self.c.yellow(&format!("{}{}{}", fd, if *append { ">>" } else { ">" }, "")));
                            if *is_num { self.w(&target.iter().map(|&b| b as char).collect::<String>()); }
                            else { self.w("\""); self.w(&crate::repr_bytes(target)); self.w("\""); }
                        }
                        Redirect::In { target, here } => {
                            self.w(" ");
                            self.w(&self.c.yellow(if *here { "<<" } else { "<" }));
                            self.w("\""); self.w(&crate::repr_bytes(target)); self.w("\"");
                        }
                    }
                }
            }
        }
        if cmd.ends_line { self.w(&self.c.yellow(" ?")); }
    }

    fn print_word(&mut self, wd: &Word, mode: Mode) {
        let mut s = String::new();
        for p in &wd.parts {
            match p {
                WPart::Lit { value, quote, src } => {
                    if *quote == 0 {
                        s.push_str(&crate::repr_bytes(value));
                    } else {
                        s.push_str(&format!("\"{}\"", crate::repr_bytes(value)));
                    }
                }
                WPart::Exp(n) => { s.push_str(&self.c.yellow("${")); s.push_str(&self.c.green(&String::from_utf8_lossy(n))); s.push_str("}"); }
            }
        }
        self.w("\""); self.w(&s); self.w("\"");
    }
}
