{"command": "cd /workspace && cat > src/parser.rs <<'RSEOF'
use crate::ast::*;
use crate::lexer::*;
use crate::Pos;
use std::cell::Cell;

pub struct PErr { pub line: usize, pub col: usize, pub msg: String }

struct Scope { vars: Vec<(Vec<u8>, usize)>, fdepth: usize }

struct FnSlots { kinds: Vec<SlotKind>, captures: Vec<(usize, usize)> }

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    pub errors: Vec<PErr>,
    scopes: Vec<Scope>,
    fns: Vec<FnSlots>,
    pub abort: bool,
}

impl Parser {
    pub fn new(toks: Vec<Token>) -> Self {
        let mut fns = vec![FnSlots { kinds: vec![SlotKind::Auto], captures: vec![] }];
        let scopes = vec![Scope { vars: vec![(b"std".to_vec(), 0)], fdepth: 0 }];
        let _ = &mut fns;
        Parser { toks, pos: 0, errors: Vec::new(), scopes, fns, abort: false }
    }
    fn peek(&self) -> &Tok { &self.toks[self.pos].tok }
    fn peek_at(&self, n: usize) -> &Tok { if self.pos + n < self.toks.len() { &self.toks[self.pos + n].tok } else { &Tok::Eof } }
    fn line(&self, n: usize) -> usize { self.toks[self.pos + n].line }
    fn col(&self, n: usize) -> usize { self.toks[self.pos + n].col }
    fn bump(&mut self) -> Tok { let t = self.toks[self.pos].tok.clone(); if self.pos + 1 < self.toks.len() { self.pos += 1; } t }
    fn bump_n(&mut self, n: usize) { for _ in 0..n { self.bump(); } }
    fn cur_pos(&self) -> Pos { Pos::new(self.line(0), self.col(0)) }
    fn err_here(&mut self, msg: &str) { self.errors.push(PErr { line: self.line(0), col: self.col(0), msg: msg.to_string() }); }
    fn is_kw(&self, k: Kw) -> bool { matches!(self.peek(), Tok::Kw(x) if *x == k) }
    fn kw_at(&self, n: usize, k: Kw) -> bool { matches!(self.peek_at(n), Tok::Kw(x) if *x == k) }

    fn fdepth(&self) -> usize { self.scopes.last().unwrap().fdepth }

    fn push_scope(&mut self, fdepth: usize) { self.scopes.push(Scope { vars: vec![], fdepth }); }
    fn pop_scope(&mut self) { self.scopes.pop(); }

    fn declare(&mut self, name: &[u8], pos: Pos) -> usize {
        let fd = self.fdepth();
        if let Some((_, s)) = self.scopes.last().unwrap().vars.iter().find(|(n, _)| n == name) {
            self.errors.push(PErr { line: pos.line, col: pos.col, msg: format!("duplicate variable '{}'", String::from_utf8_lossy(name)) });
            return *s;
        }
        let s = self.fns[fd].kinds.len();
        self.fns[fd].kinds.push(SlotKind::Auto);
        self.scopes.last_mut().unwrap().vars.push((name.to_vec(), s));
        s
    }

    fn slot_of(&self, name: &[u8]) -> Option<(usize, usize)> {
        for s in self.scopes.iter().rev() {
            if let Some((_, slot)) = s.vars.iter().find(|(n, _)| n == name) {
                return Some((s.fdepth, *slot));
            }
        }
        None
    }

    fn get_self_slot(&mut self) -> usize {
        let fd = self.fdepth();
        if let Some(i) = self.fns[fd].kinds.iter().position(|k| matches!(k, SlotKind::Self_)) { return i; }
        self.fns[fd].kinds.push(SlotKind::Self_);
        self.fns[fd].kinds.len() - 1
    }

    fn ref_var(&mut self, name: &[u8], pos: Pos) -> usize {
        match self.slot_of(name) {
            Some((fd, slot)) => {
                if fd == self.fdepth() { return slot; }
                // capture chain
                self.capture_chain(fd, slot)
            }
            None => usize::MAX,
        }
    }

    fn capture_chain(&mut self, f_outer: usize, s_outer: usize) -> usize {
        // find the slot in level f_outer+1..=fdepth()
        let cur = self.fdepth();
        // build the chain from the outer side
        let mut s = s_outer;
        for lvl in f_outer + 1..=cur {
            // find or create a capture slot in `lvl` referring to `s` (a slot in lvl-1)
            let existing = self.fns[lvl].captures.iter().find(|(p, _)| *p == s).map(|(_, sl)| *sl);
            match existing {
                Some(sl) => { s = sl; }
                None => {
                    let sl = self.fns[lvl].kinds.len();
                    self.fns[lvl].kinds.push(SlotKind::Capture(s));
                    self.fns[lvl].captures.push((s, sl));
                    s = sl;
                }
            }
        }
        s
    }

    pub fn parse_program(&mut self) -> (Vec<Stmt>, Vec<SlotKind>) {
        let body = self.parse_block_body(true);
        let kinds = self.fns[0].kinds.clone();
        (body, kinds)
    }

    fn parse_block_body(&mut self, top: bool) -> Vec<Stmt> {
        let mut out = Vec::new();
        loop {
            if matches!(self.peek(), Tok::Eof) {
                if !top { self.errors.push(PErr { line: 0, col: 0, msg: "unexpected end of file".to_string() }); }
                break;
            }
            if self.is_kw(Kw::End) { break; }
            self.parse_stmt(&mut out);
        }
        out
    }

    fn starts_expr(&self) -> bool {
        match self.peek() {
            Tok::Id(_) | Tok::Int(_) | Tok::Float(_) | Tok::Char(_) | Tok::Str(_) | Tok::LParen
            | Tok::LBracket | Tok::At | Tok::LBrace | Tok::DollarBrace | Tok::AmpBrace => true,
            Tok::Kw(k) => matches!(k, Kw::True | Kw::False | Kw::Nil | Kw::Self_ | Kw::Not | Kw::If | Kw::Function),
            _ => false,
        }
    }

    fn parse_stmt(&mut self, out: &mut Vec<Stmt>) {
        match self.peek().clone() {
            Tok::Kw(Kw::Let) => { self.bump(); self.parse_let(out); }
            Tok::Kw(Kw::Return) => {
                let p = self.cur_pos(); self.bump();
                let e = self.parse_expr(0);
                out.push(Stmt::Return(e, p));
            }
            Tok::Kw(Kw::Break) => { let p = self.cur_pos(); self.bump(); out.push(Stmt::Break(p)); }
            Tok::Kw(Kw::Function) if matches!(self.peek_at(1), Tok::Id(_)) => {
                let p = self.cur_pos(); self.bump();
                let name = match self.bump() { Tok::Id(n) => n, _ => vec![] };
                let np = self.cur_pos();
                let slot = self.declare(&name, np);
                let f = self.parse_func_body(p);
                out.push(Stmt::Func(name, f, Pos::new(p.line, p.col)));
                let _ = slot;
            }
            Tok::Kw(Kw::If) => { self.parse_if_stmt(out); }
            Tok::Kw(Kw::While) => {
                let p = self.cur_pos(); self.bump();
                let cond = self.parse_expr(0);
                self.expect(Kw::Do, "do");
                let body = self.parse_block_body(false);
                if !self.is_kw(Kw::End) { self.err_here("unexpected end of file"); } else { self.bump(); }
                out.push(Stmt::While { cond, body: Block { stmts: body }, pos: p });
            }
            Tok::Kw(Kw::For) => {
                let p = self.cur_pos(); self.bump();
                let var = match self.peek().clone() { Tok::Id(n) => { let vp = self.cur_pos(); self.bump(); (n, vp) }, _ => { self.err_here("unexpected token, expected identifier"); (vec![], NOPOS) } };
                if !self.is_kw(Kw::In) { self.err_here("unexpected token, expected 'in'"); } else { self.bump(); }
                let it = self.parse_expr(0);
                self.expect(Kw::Do, "do");
                self.push_scope(self.fdepth());
                let slot = self.declare(&var.0, var.1);
                let body = self.parse_block_body(false);
                if !self.is_kw(Kw::End) { self.err_here("unexpected end of file"); } else { self.bump(); }
                self.pop_scope();
                out.push(Stmt::For { var: var.0, slot, iter: it, body: Block { stmts: body }, pos: p });
            }
            _ => self.parse_expr_stmt(out),
        }
    }

    fn expect(&mut self, k: Kw, what: &str) {
        if !self.is_kw(k) { self.err_here(&format!("unexpected {}, expected {}", tok_disp(self.peek()), what)); }
        else { self.bump(); }
    }

    fn parse_let(&mut self, out: &mut Vec<Stmt>) {
        let p = Pos::new(self.line(0), self.col(0));
        let name = match self.peek().clone() {
            Tok::Id(n) => { let np = self.cur_pos(); self.bump(); (n, np) }
            _ => { self.err_here("unexpected token, expected identifier"); (vec![], p) }
        };
        let slot = self.declare(&name.0, name.1);
        let mut e = Expr::Nil(p);
        if matches!(self.peek(), Tok::Assign) { self.bump(); e = self.parse_expr(0); }
        out.push(Stmt::Let(name.0, slot, e, p));
    }

    fn parse_expr_stmt(&mut self, out: &mut Vec<Stmt>) {
        if !self.starts_expr() {
            self.err_here(&format!("unexpected {}, expected expression", tok_disp(self.peek())));
            return;
        }
        let e = self.parse_expr(0);
        if matches!(self.peek(), Tok::Assign) {
            self.bump();
            let v = self.parse_expr(0);
            out.push(Stmt::Assign(e, v, NOPOS));
        } else {
            out.push(Stmt::Expr(e, NOPOS));
        }
    }

    fn build_if(&mut self, branches: Vec<(Expr, Block)>, els: Option<Block>, p: Pos) -> Expr {
        let mut it = branches.into_iter().rev();
        let (c0, b0) = it.next().unwrap();
        let mut cur = Expr::If(Box::new(c0), Box::new(b0), els.map(|b| Box::new(b)), p);
        for (c, b) in it {
            cur = Expr::If(Box::new(c), Box::new(b), Some(Box::new(Block { stmts: vec![Stmt::Expr(cur, p)] })), p);
        }
        cur
    }

    fn parse_if_stmt(&mut self, out: &mut Vec<Stmt>) {
        let p = self.cur_pos(); self.bump();
        let cond = self.parse_expr(0);
        self.expect(Kw::Then, "then");
        let mut branches: Vec<(Expr, Block)> = vec![];
        let mut els: Option<Block> = None;
        branches.push((cond, Block { stmts: self.parse_block_body(false) }));
        loop {
            if self.is_kw(Kw::End) { self.bump(); break; }
            if self.is_kw(Kw::ElseIf) {
                self.bump();
                let c = self.parse_expr(0);
                self.expect(Kw::Then, "then");
                branches.push((c, Block { stmts: self.parse_block_body(false) }));
                continue;
            }
            if self.is_kw(Kw::Else) {
                self.bump();
                els = Some(Block { stmts: self.parse_block_body(false) });
                if !self.is_kw(Kw::End) { self.err_here("unexpected token, expected end"); } else { self.bump(); }
                break;
            }
            self.err_here("unexpected token, expected end, else or elseif");
            break;
        }
        let e = self.build_if(branches, els, p);
        out.push(Stmt::Expr(e, p));
    }

    fn parse_func_body(&mut self, p: Pos) -> FuncLit {
        let mut params = Vec::new();
        if matches!(self.peek(), Tok::LParen) { self.bump(); } else { self.err_here(&format!("unexpected {}, expected '('", tok_disp(self.peek()))); }
        self.push_scope(self.fdepth() + 1);
        self.fns.push(FnSlots { kinds: vec![], captures: vec![] });
        loop {
            match self.peek().clone() {
                Tok::Id(n) => { let pp = self.cur_pos(); self.bump(); let s = self.declare(&n, pp); params.push(n); let _ = s; }
                Tok::RParen => { self.bump(); break; }
                Tok::Eof => { self.errors.push(PErr { line: 0, col: 0, msg: "unexpected end of file".to_string() }); break; }
                _ => { self.err_here(&format!("unexpected {}, expected ')'", tok_disp(self.peek()))); break; }
            }
            match self.peek().clone() {
                Tok::Comma => { self.bump(); }
                Tok::RParen => { self.bump(); break; }
                _ => { self.err_here(&format!("unexpected {}, expected ',' or ')'", tok_disp(self.peek()))); break; }
            }
        }
        let body = self.parse_block_body(false);
        if !self.is_kw(Kw::End) { self.err_here("unexpected end of file"); } else { self.bump(); }
        let kinds = self.fns.pop().unwrap().kinds;
        self.pop_scope();
        FuncLit { params, body: Block { stmts: body }, pos: p, kinds }
    }

    // ---------------- expressions ----------------
    pub fn parse_expr(&mut self, min_prec: u8) -> Expr {
        let mut lhs = self.parse_unary();
        loop {
            let op = match self.peek() {
                Tok::Kw(Kw::Or) => Some(BinOp::Or),
                Tok::Kw(Kw::And) => Some(BinOp::And),
                Tok::EqEq => Some(BinOp::EqEq),
                Tok::NotEq => Some(BinOp::NotEq),
                Tok::Lt => Some(BinOp::Lt),
                Tok::Gt => Some(BinOp::Gt),
                Tok::Le => Some(BinOp::Le),
                Tok::Ge => Some(BinOp::Ge),
                Tok::PlusPlus => Some(BinOp::Concat),
                Tok::Plus => Some(BinOp::Plus),
                Tok::Minus => Some(BinOp::Minus),
                Tok::Star => Some(BinOp::Star),
                Tok::Slash => Some(BinOp::Slash),
                Tok::Percent => Some(BinOp::Percent),
                _ => None,
            };
            let (op, prec) = match op { None => break, Some(op) => (op, op.prec()) };
            if prec < min_prec { break; }
            self.bump();
            let rhs = self.parse_expr(prec + 1);
            lhs = Expr::Binary(op, Box::new(lhs), Box::new(rhs), NOPOS);
        }
        lhs
    }

    fn parse_unary(&mut self) -> Expr {
        match self.peek() {
            Tok::Kw(Kw::Not) => { let p = self.cur_pos(); self.bump(); let e = self.parse_unary(); Expr::Unary(UnOp::Not, Box::new(e), p) }
            Tok::Minus => { let p = self.cur_pos(); self.bump(); let e = self.parse_unary(); Expr::Unary(UnOp::Neg, Box::new(e), p) }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            match self.peek().clone() {
                Tok::LParen => {
                    let p = self.cur_pos(); self.bump();
                    let mut args = Vec::new();
                    if matches!(self.peek(), Tok::RParen) { self.bump(); }
                    else {
                        loop {
                            args.push(self.parse_expr(0));
                            match self.peek() {
                                Tok::Comma => { self.bump(); }
                                Tok::RParen => { self.bump(); break; }
                                _ => { self.err_here(&format!("unexpected {}, expected ')'", tok_disp(self.peek()))); break; }
                            }
                        }
                    }
                    e = Expr::Call(Box::new(e), args, p);
                }
                Tok::LBracket => {
                    let p = self.cur_pos(); self.bump();
                    let i = self.parse_expr(0);
                    if matches!(self.peek(), Tok::RBracket) { self.bump(); } else { self.err_here("unexpected token, expected ']'"); }
                    e = Expr::Index(Box::new(e), Box::new(i), p);
                }
                Tok::Dot => {
                    self.bump();
                    match self.peek().clone() {
                        Tok::Id(n) => { let p = self.cur_pos(); self.bump(); e = Expr::Member(Box::new(e), n, p); }
                        _ => { self.err_here("unexpected token, expected identifier"); }
                    }
                }
                Tok::Question => {
                    let p = self.cur_pos(); self.bump();
                    if self.fdepth() == 0 { self.errors.push(PErr { line: p.line, col: p.col, msg: "try operator outside function".to_string() }); }
                    e = Expr::Try(Box::new(e), p);
                }
                _ => break,
            }
        }
        e
    }

    fn parse_primary(&mut self) -> Expr {
        let (l, c) = (self.line(0), self.col(0));
        match self.peek().clone() {
            Tok::Int(v) => { self.bump(); Expr::Int(v, Pos::new(l, c)) }
            Tok::Float(v) => { self.bump(); Expr::Float(v, Pos::new(l, c)) }
            Tok::Char(v) => { self.bump(); Expr::Char(v, Pos::new(l, c)) }
            Tok::Str(v) => { self.bump(); Expr::Str(v, Pos::new(l, c)) }
            Tok::Kw(Kw::True) => { self.bump(); Expr::Bool(true, Pos::new(l, c)) }
            Tok::Kw(Kw::False) => { self.bump(); Expr::Bool(false, Pos::new(l, c)) }
            Tok::Kw(Kw::Nil) => { self.bump(); Expr::Nil(Pos::new(l, c)) }
            Tok::Kw(Kw::Self_) => {
                let p = Pos::new(l, c); self.bump();
                let slot = if self.fdepth() == 0 {
                    self.errors.push(PErr { line: p.line, col: p.col, msg: "self keyword outside function".to_string() });
                    usize::MAX
                } else { self.get_self_slot() };
                Expr::Self_(p, slot)
            }
            Tok::Id(n) => {
                let p = Pos::new(l, c); self.bump();
                let slot = self.ref_var(&n, p);
                if slot == usize::MAX {
                    self.errors.push(PErr { line: p.line, col: p.col, msg: format!("undeclared variable '{}'", String::from_utf8_lossy(&n)) });
                }
                Expr::Var(n, p, slot)
            }
            Tok::LParen => {
                self.bump();
                let e = self.parse_expr(0);
                if matches!(self.peek(), Tok::RParen) { self.bump(); } else { self.err_here("unexpected token, expected ')'"); }
                e
            }
            Tok::LBracket => {
                let p = Pos::new(l, c); self.bump();
                let mut items = Vec::new();
                if matches!(self.peek(), Tok::RBracket) { self.bump(); }
                else {
                    loop {
                        items.push(self.parse_expr(0));
                        match self.peek() {
                            Tok::Comma => { self.bump(); }
                            Tok::RBracket => { self.bump(); break; }
                            _ => { self.err_here(&format!("unexpected {}, expected ']'", tok_disp(self.peek()))); break; }
                        }
                    }
                }
                Expr::Array(items, p)
            }
            Tok::At => {
                let p = Pos::new(l, c); self.bump();
                if !matches!(self.peek(), Tok::LBracket) { self.err_here("unexpected token, expected '['"); }
                self.bump();
                let mut items: Vec<(Expr, Expr)> = Vec::new();
                let mut seen: Vec<Vec<u8>> = Vec::new();
                if matches!(self.peek(), Tok::RBracket) { self.bump(); }
                else {
                    loop {
                        let k = match self.peek().clone() {
                            Tok::Id(n) => { let kp = self.cur_pos(); self.bump(); if seen.contains(&n) { self.errors.push(PErr { line: kp.line, col: kp.col, msg: format!("duplicate key '{}'", String::from_utf8_lossy(&n)) }); } seen.push(n.clone()); Expr::Var(n, kp, usize::MAX) }
                            _ => { self.err_here(&format!("unexpected {}, expected identifier", tok_disp(self.peek()))); Expr::Nil(NOPOS) }
                        };
                        if !matches!(self.peek(), Tok::Colon) { self.err_here("unexpected token, expected ':'"); } else { self.bump(); }
                        let v = self.parse_expr(0);
                        items.push((k, v));
                        match self.peek() {
                            Tok::Comma => { self.bump(); }
                            Tok::RBracket => { self.bump(); break; }
                            _ => { self.err_here(&format!("unexpected {}, expected ']'", tok_disp(self.peek()))); break; }
                        }
                    }
                }
                Expr::Dict(items, p)
            }
            Tok::Kw(Kw::Function) => {
                let p = Pos::new(l, c); self.bump();
                if !matches!(self.peek(), Tok::LParen) { self.err_here(&format!("unexpected {}, expected '('", tok_disp(self.peek()))); }
                let f = self.parse_func_body(p);
                Expr::Func(Box::new(f), p)
            }
            Tok::Kw(Kw::If) => {
                let p = Pos::new(l, c); self.bump();
                let cond = self.parse_expr(0);
                self.expect(Kw::Then, "then");
                let mut branches: Vec<(Expr, Block)> = vec![];
                let mut els = None;
                branches.push((cond, Block { stmts: self.parse_block_body(false) }));
                loop {
                    if self.is_kw(Kw::End) { self.bump(); break; }
                    if self.is_kw(Kw::ElseIf) { self.bump(); let c2 = self.parse_expr(0); self.expect(Kw::Then, "then"); branches.push((c2, Block { stmts: self.parse_block_body(false) })); continue; }
                    if self.is_kw(Kw::Else) { self.bump(); els = Some(Block { stmts: self.parse_block_body(false) }); if !self.is_kw(Kw::End) { self.err_here("unexpected token, expected end"); } else { self.bump(); } break; }
                    self.err_here("unexpected token, expected end, else or elseif");
                    break;
                }
                self.build_if(branches, els, p)
            }
            Tok::LBrace | Tok::DollarBrace | Tok::AmpBrace => {
                let p = Pos::new(l, c);
                let kind = match self.peek() { Tok::DollarBrace => BlockKind::Capture, Tok::AmpBrace => BlockKind::Async, _ => BlockKind::Plain };
                self.bump();
                let mut blk = self.parse_cmd_block(p);
                blk.kind = kind;
                Expr::Cmd(Box::new(blk), p)
            }
            Tok::Eof => { self.err_here("unexpected end of file"); Expr::Nil(NOPOS) }
            _ => { self.err_here(&format!("unexpected {}, expected expression", tok_disp(self.peek()))); Expr::Nil(NOPOS) }
        }
    }

    // ---- command blocks ----
    pub fn parse_cmd_block(&mut self, open: Pos) -> CmdBlock {
        let mut cmds: Vec<Command> = Vec::new();
        let mut ill = false;
        if matches!(self.peek(), Tok::RBrace) {
            let p = self.cur_pos();
            self.errors.push(PErr { line: p.line, col: p.col, msg: "empty command block".to_string() });
            self.bump();
            return CmdBlock { kind: BlockKind::Plain, cmds, pos: open, ill_formed: false };
        }
        loop {
            let mut cmd = self.parse_command();
            let mut semi = false;
            match self.peek() {
                Tok::Semi => { self.bump(); semi = true; }
                Tok::RBrace => { self.bump(); }
                _ => {
                    let p = self.cur_pos();
                    self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected '}}'", tok_disp(self.peek())) });
                    cmd.ill_formed = true;
                    self.skip_to_rbrace();
                    cmd.semi = false;
                    cmds.push(cmd);
                    ill = true;
                    break;
                }
            }
            cmd.semi = semi;
            self.check_words(&cmd);
            cmds.push(cmd);
            if !semi { break; }
        }
        let blk = CmdBlock { kind: BlockKind::Plain, cmds, pos: open, ill_formed: ill };
        blk
    }

    fn check_words(&mut self, cmd: &Command) {
        for p in &cmd.pipes { for seg in &p.segs {
            for w in &seg.words {
                for part in &w.parts {
                    if let WPart::Exp(n) = part {
                        if self.slot_of(n).is_none() {
                            self.errors.push(PErr { line: 0, col: 0, msg: format!("undeclared variable '{}'", String::from_utf8_lossy(n)) });
                        }
                    }
                }
            }
            for r in &seg.redirs {
                if let Redirect::Out { target, is_num, .. } = r {
                    if !*is_num && !target.is_empty() {
                        // target may be an expansion? not modelled
                    }
                }
            }
        } }
    }

    fn skip_to_rbrace(&mut self) {
        let mut depth = 0usize;
        while !matches!(self.peek(), Tok::Eof) {
            match self.peek() {
                Tok::LBrace | Tok::DollarBrace | Tok::AmpBrace => { depth += 1; self.bump(); }
                Tok::RBrace => { if depth == 0 { self.bump(); break; } depth -= 1; self.bump(); }
                _ => { self.bump(); }
            }
        }
        if matches!(self.peek(), Tok::RBrace) && depth == 0 { self.bump(); }
    }

    fn parse_command(&mut self) -> Command {
        let mut pipes: Vec<Pipeline> = Vec::new();
        let mut ends_line = false;
        loop {
            let seg = self.parse_segment();
            pipes.push(Pipeline { segs: vec![seg] });
            if matches!(self.peek(), Tok::Pipe) { self.bump(); continue; }
            if matches!(self.peek(), Tok::Question) {
                ends_line = true;
                self.bump();
                match self.peek() {
                    Tok::Pipe => { self.bump(); continue; }
                    Tok::Semi => { self.bump(); return Command { pipes, ends_line, ill_formed: false, semi: true }; }
                    Tok::RBrace => { self.bump(); return Command { pipes, ends_line, ill_formed: false, semi: false }; }
                    _ => {
                        let p = self.cur_pos();
                        self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected '}}'", tok_disp(self.peek())) });
                        return Command { pipes, ends_line, ill_formed: true, semi: false };
                    }
                }
            }
            return Command { pipes, ends_line, ill_formed: false, semi: false };
        }
    }

    fn parse_segment(&mut self) -> Segment {
        let mut words: Vec<Word> = Vec::new();
        let mut redirs = Vec::new();
        let mut first = true;
        loop {
            match self.peek().clone() {
                Tok::Word(w) | Tok::Glob(w) => {
                    // convert $exp parts to variable references for analysis
                    let mut nw: Vec<WPart> = Vec::new();
                    for p in w {
                        match p {
                            WPart::Lit { value, quote, src } => nw.push(WPart::Lit { value, quote, src }),
                            WPart::Exp(n) => nw.push(WPart::Exp(n)),
                        }
                    }
                    for p in &nw {
                        if let WPart::Exp(n) = p {
                            let np = self.cur_pos();
                            if self.ref_var(n, np) == usize::MAX {
                                self.errors.push(PErr { line: np.line, col: np.col, msg: format!("undeclared variable '{}'", String::from_utf8_lossy(n)) });
                            }
                        }
                    }
                    words.push(Word { parts: nw });
                    self.bump();
                }
                Tok::Int(v) => {
                    let val = v;
                    if !first && (matches!(self.peek_at(1), Tok::Redirect(_, _))) {
                        if let Tok::Redirect(fd, app) = self.peek_at(1).clone() {
                            if val > 255 || val < 0 {
                                let p = self.cur_pos();
                                self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected output redirection", val) });
                                self.bump();
                                continue;
                            }
                            self.bump(); self.bump();
                            let t = self.parse_redir_target();
                            redirs.push(Redirect::Out { fd: val as u8, append: app, target: t.0, is_num: t.1 });
                            continue;
                        }
                        unreachable!()
                    }
                    words.push(Word { parts: vec![WPart::Lit { value: val.to_string().into_bytes(), quote: 0, src: vec![] }] });
                    self.bump();
                }
                Tok::Redirect(fd, app) => {
                    self.bump();
                    let t = self.parse_redir_target();
                    redirs.push(Redirect::Out { fd: fd.unwrap_or(1), append: app, target: t.0, is_num: t.1 });
                }
                Tok::InRedirect(here) => {
                    self.bump();
                    let t = self.parse_redir_target();
                    redirs.push(Redirect::In { target: t.0, here });
                }
                _ => break,
            }
            first = false;
        }
        if words.is_empty() {
            let p = self.cur_pos();
            self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected argument", tok_disp(self.peek())) });
        }
        Segment { words, redirs }
    }

    fn parse_redir_target(&mut self) -> (Vec<u8>, bool) {
        match self.peek().clone() {
            Tok::Word(w) | Tok::Glob(w) => {
                let mut s = Vec::new();
                for p in &w {
                    if let WPart::Lit { value, .. } = p { s.extend_from_slice(value); }
                    else if let WPart::Exp(n) = p { s.extend_from_slice(n); }
                }
                self.bump(); (s, false)
            }
            Tok::Str(v) => { self.bump(); (v, false) }
            Tok::Int(v) => { self.bump(); (v.to_string().into_bytes(), true) }
            Tok::Id(n) => { self.bump(); (n, false) }
            _ => {
                let p = self.cur_pos();
                self.errors.push(PErr { line: p.line, col: p.col, msg: format!("unexpected {}, expected argument", tok_disp(self.peek())) });
                (vec![], false)
            }
        }
    }
}

pub fn tok_disp(t: &Tok) -> String {
    match t {
        Tok::Id(n) => format!("'{}'", String::from_utf8_lossy(n)),
        Tok::Int(v) => format!("'{}'", v),
        Tok::Float(v) => format!("'{}'", crate::fmt_disp(*v)),
        Tok::Char(c) => format!("'{}'", c as char),
        Tok::Str(_) => "'string'".to_string(),
        Tok::Kw(k) => format!("'{}'", crate::kw_name(*k)),
        Tok::LParen => "'('".into(), Tok::RParen => "')'".into(),
        Tok::LBracket => "'['".into(), Tok::RBracket => "']'".into(),
        Tok::Colon => "':'".into(), Tok::Comma => "','".into(), Tok::Dot => "'.'".into(),
        Tok::Assign => "'='".into(), Tok::Plus => "'+'".into(), Tok::Minus => "'-'".into(),
        Tok::Star => "'*'".into(), Tok::Slash => "'/'".into(), Tok::Percent => "'%'".into(),
        Tok::PlusPlus => "'++'".into(), Tok::EqEq => "'=='".into(), Tok::NotEq => "'!='".into(),
        Tok::Lt => "'<'".into(), Tok::Gt => "'>'".into(), Tok::Le => "'<='".into(), Tok::Ge => "'>='".into(),
        Tok::At => "'@'".into(), Tok::LBrace => "'{'".into(), Tok::RBrace => "'}'".into(),
        Tok::AmpBrace => "'&{".into(), Tok::DollarBrace => "'${".into(),
        Tok::Pipe => "'|'".into(), Tok::Semi => "';'".into(), Tok::Question => "'?'".into(),
        Tok::Word(_) => "'word'".into(), Tok::Glob(_) => "'word'".into(), Tok::Dollar(_) => "'$'".into(),
        Tok::Redirect(_, _) => "'>'".into(), Tok::InRedirect(_) => "'<'".into(),
        Tok::Amp => "'&'".into(), Tok::Eof => "end of file".into(),
    }
}

pub fn kw_name(k: Kw) -> &'static str {
    match k {
        Kw::Let => "let", Kw::Function => "function", Kw::End => "end", Kw::If => "if",
        Kw::Then => "then", Kw::ElseIf => "elseif", Kw::Else => "else", Kw::While => "while",
        Kw::Do => "do", Kw::For => "for", Kw::In => "in", Kw::Return => "return",
        Kw::Break => "break", Kw::And => "and", Kw::Or => "or", Kw::Not => "not",
        Kw::True => "true", Kw::False => "false", Kw::Nil => "nil", Kw::Self_ => "self",
    }
}
