}

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Id(Vec<u8>),
    Int(i64),
    Float(f64),
    Char(u8),
    Str(Vec<u8>),
    Kw(Kw),
    LParen, RParen, LBracket, RBracket, Colon, Comma, Dot, Assign,
    Plus, Minus, Star, Slash, Percent,
    PlusPlus, EqEq, NotEq, Lt, Gt, Le, Ge,
    At,                 // @[
    LBrace, RBrace, AmpBrace, DollarBrace,
    Pipe, Semi, Question,
    Word(Vec<WPart>),
    Glob(Vec<u8>),
    Redirect(Option<u8>, bool),
    InRedirect(bool),
    Amp, Eof,
}

pub struct Token { pub tok: Tok, pub line: usize, pub col: usize }

pub struct LexErr { pub line: usize, pub col: usize, pub msg: String }

const KEYWORDS: &[(&str, Kw)] = &[
    ("let", Kw::Let), ("function", Kw::Function), ("end", Kw::End), ("if", Kw::If),
    ("then", Kw::Then), ("elseif", Kw::ElseIf), ("else", Kw::Else), ("while", Kw::While),
    ("do", Kw::Do), ("for", Kw::For), ("in", Kw::In), ("return", Kw::Return),
    ("break", Kw::Break), ("and", Kw::And), ("or", Kw::Or), ("not", Kw::Not),
    ("true", Kw::True), ("false", Kw::False), ("nil", Kw::Nil), ("self", Kw::Self_),
];

fn is_idc(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }
fn is_ws(b: u8) -> bool { b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' }
fn is_word_char(b: u8) -> bool {
    !matches!(b, b' ' | b'\t' | b'\n' | b'\r' | b';' | b'#' | b'?' | b'>' | b'<' | b'"' | b'\'' | b'\\' | b'$' | b'}' | b'|' | b'&' | b'@' | b'~' | b'{' | b'[')
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub line: usize,
    pub col: usize,
    depth: usize,
    pub errors: Vec<LexErr>,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        Lexer { src, pos: 0, line: 0, col: 0, depth: 0, errors: Vec::new() }
    }
    fn cur(&self) -> u8 { if self.pos < self.src.len() { self.src[self.pos] } else { 0 } }
    fn at(&self, n: usize) -> u8 { if self.pos + n < self.src.len() { self.src[self.pos + n] } else { 0 } }
    fn eof(&self) -> bool { self.pos >= self.src.len() }
    fn bump(&mut self) -> u8 {
        let b = self.cur();
        if self.pos < self.src.len() {
            self.pos += 1;
            if b == b'\n' { self.line += 1; self.col = 0; } else { self.col += 1; }
        }
        b
    }
    fn err(&mut self, line: usize, col: usize, msg: String) { self.errors.push(LexErr { line, col, msg }); }

    pub fn lex(&mut self) -> Vec<Token> {
        let mut out = Vec::new();
        loop {
            self.ws();
            let (l, c) = (self.line, self.col);
            if self.eof() { out.push(Token { tok: Tok::Eof, line: l, col: c }); break; }
            let b = self.cur();
            let t = if self.depth == 0 { self.out_tok(b, l, c) } else { self.in_tok(b, l, c) };
            match t { Some(t) => out.push(Token { tok: t, line: l, col: c }), None => {} }
        }
        out
    }

    fn ws(&mut self) {
        loop {
            while !self.eof() && is_ws(self.cur()) { self.bump(); }
            if self.cur() == b'#' { while !self.eof() && self.cur() != b'\n' { self.bump(); } continue; }
            break;
        }
    }

    // ============ outside command blocks ============
    fn out_tok(&mut self, b: u8, l: usize, c: usize) -> Option<Tok> {
        match b {
            b'(' => { self.bump(); Some(Tok::LParen) }
            b')' => { self.bump(); Some(Tok::RParen) }
            b'[' => { self.bump(); Some(Tok::LBracket) }
            b']' => { self.bump(); Some(Tok::RBracket) }
            b':' => { self.bump(); Some(Tok::Colon) }
            b',' => { self.bump(); Some(Tok::Comma) }
            b'=' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::EqEq) } else { Some(Tok::Assign) } }
            b'+' => { self.bump(); if self.cur() == b'+' { self.bump(); Some(Tok::PlusPlus) } else { Some(Tok::Plus) } }
            b'-' => { self.bump(); Some(Tok::Minus) }
            b'*' => { self.bump(); Some(Tok::Star) }
            b'/' => { self.bump(); Some(Tok::Slash) }
            b'%' => { self.bump(); Some(Tok::Percent) }
            b'<' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::Le) } else { Some(Tok::Lt) } }
            b'>' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::Ge) } else { Some(Tok::Gt) } }
            b'.' => { self.bump(); Some(Tok::Dot) }
            b'"' => { let s = self.str_lit(l, c, true); Some(Tok::Str(s.0)) }
            b'\'' => { let v = self.char_lit(l, c, true); Some(Tok::Char(v)) }
            b'@' => {
                self.bump();
                if self.cur() == b'[' { self.bump(); Some(Tok::At) }
                else { self.err(l, c, "unexpected '@'.".into()); None }
            }
            b'|' => { self.bump(); self.err(l, c, "unexpected '|'.".into()); None }
            b'$' => { self.bump(); self.err(l, c, "unexpected '$'.".into()); None }
            b'&' => { self.bump(); self.err(l, c, "unexpected '&'.".into()); None }
            b';' => { self.bump(); self.err(l, c, "unexpected ';'.".into()); None }
            b'~' => { self.bump(); self.err(l, c, "unexpected '~'.".into()); None }
            b'\\' => { self.bump(); self.err(l, c, "unexpected '\\'.".into()); None }
            b'}' => { self.bump(); self.err(l, c, "unexpected '}'.".into()); None }
            b'?' => { self.bump(); Some(Tok::Question) }
            b'_' | b'a'..=b'z' | b'A'..=b'Z' => self.ident(),
            b'0'..=b'9' => self.num(l, c),
            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn ident(&mut self) -> Tok {
        let st = self.pos;
        while !self.eof() && is_idc(self.cur()) { self.bump(); }
        let s = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("");
        for (k, kk) in KEYWORDS { if *k == s { return Tok::Kw(*kk); } }
        Tok::Id(self.src[st..self.pos].to_vec())
    }

    fn num(&mut self, l: usize, c: usize) -> Tok {
        let st = self.pos;
        while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
        let mut isf = false;
        if self.cur() == b'.' && self.at(1).is_ascii_digit() {
            self.bump();
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            isf = true;
        }
        if (self.cur() == b'e' || self.cur() == b'E') && self.at(1).is_ascii_digit() {
            self.bump();
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            isf = true;
        }
        let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
        if self.cur() == b'.' || self.cur() == b'e' || self.cur() == b'E' {
            let bad = if self.eof() { "end of file".to_string() } else { format!("'{}'.", self.cur() as char) };
            self.err(l, c, format!("unexpected {}.", bad));
            if !self.eof() { self.bump(); }
            self.pos = st; self.line = l; self.col = c;
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
            return match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            };
        }
        if isf { Tok::Float(txt.parse::<f64>().unwrap_or(f64::INFINITY)) }
        else {
            match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            }
        }
    }

    fn unescape(&mut self, l: usize, c: usize, allow: &[u8]) -> u8 {
        let sc = self.col;
        self.bump();
        let ch = self.cur();
        match ch {
            b'n' => { self.bump(); 0x0a }
            b't' => { self.bump(); 0x09 }
            b'r' => { self.bump(); 0x0d }
            b'0' => { self.bump(); 0x00 }
            b'\'' if allow.contains(&b'\'') => { self.bump(); b'\'' }
            b'"' if allow.contains(&b'"') => { self.bump(); b'"' }
            b'\\' => { self.bump(); b'\\' }
            _ => {
                let name = if ch == 0 && self.eof() { "\\'".to_string() } else { format!("'\\{}'", ch as char) };
                self.err(l, sc, format!("invalid escape sequence {}.", name));
                self.bump(); 0
            }
        }
    }

    fn str_lit(&mut self, l: usize, c: usize, normal: bool) -> (Vec<u8>, Vec<u8>) {
        let allow: &[u8] = if normal { &[b'\'', b'"'] } else { &[b'"'] };
        let mut out = Vec::new();
        let mut src = Vec::new();
        self.bump();
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            let ch = self.cur();
            if ch == b'"' { self.bump(); break; }
            if ch == b'\\' {
                let sc = self.col;
                let b0 = self.bump();
                let b1 = self.cur();
                src.push(b0); src.push(b1);
                out.push(self.unescape(l, sc, allow));
                continue;
            }
            out.push(self.bump());
            src.push(ch);
        }
        (out, src)
    }

    fn char_lit(&mut self, l: usize, c: usize, normal: bool) -> u8 {
        let allow: &[u8] = if normal { &[b'\'', b'"'] } else { &[b'\''] };
        self.bump();
        let mut v = 0u8;
        if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); return v; }
        if self.cur() == b'\\' {
            let sc = self.col;
            let b0 = self.bump();
            let _b1 = self.cur();
            v = self.unescape(l, sc, allow);
            let _ = b0;
        } else { v = self.bump(); }
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            if self.cur() == b'\'' { self.bump(); break; }
            self.err(self.line, self.col, format!("unexpected '{}'.", self.cur() as char));
            self.bump();
        }
        v
    }

    // ============ inside command blocks ============
    fn in_tok(&mut self, b: u8, l: usize, c: usize) -> Option<Tok> {
        match b {
            b'{' => { self.todo(l, c, 87); None }
            b'[' => { self.todo(l, c, 87); None }
            b'}' => { self.bump(); if self.depth > 0 { self.depth -= 1; } Some(Tok::RBrace) }
            b'(' => { self.bump(); Some(Tok::LParen) }
            b')' => { self.bump(); Some(Tok::RParen) }
            b'>' => { self.bump(); let app = self.cur() == b'>'; if app { self.bump(); } Some(Tok::Redirect(None, app)) }
            b'<' => { self.bump(); let hr = self.cur() == b'<'; if hr { self.bump(); } Some(Tok::InRedirect(hr)) }
            b';' => { self.bump(); Some(Tok::Semi) }
            b'|' => { self.bump(); Some(Tok::Pipe) }
            b'?' => { self.bump(); Some(Tok::Question) }
            b'#' => { while !self.eof() && self.cur() != b'\n' { self.bump(); } None }
            b'"' => {
                let (s, src) = self.str_lit(l, c, false);
                Some(Tok::Word(vec![WPart::Lit { value: s, quote: b'"', src }]))
            }
            b'\'' => {
                let s = self.str_lit_sq(l, c);
                Some(Tok::Word(vec![WPart::Lit { value: s, quote: b'\'', src: vec![] }]))
            }
            b'&' => {
                if self.at(1) == b'{' { self.todo(l, c, 91); None }
                else { self.word() }
            }
            b'$' => { self.word() }
            b'_' | b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'.' | b',' | b':' | b'=' | b'+' | b'-'
                 | b'!' | b'^' | b'/' | b'%' | b'*' | b')' | b']' | b'~' => self.word(),
            b'\\' => {
                self.bump();
                if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); return None; }
                let ch = self.bump();
                if ch == b'\n' { Some(Tok::Word(vec![WPart::Lit { value: vec![b'\\', b'\n'], quote: 0, src: vec![] }])) }
                else { Some(Tok::Word(vec![WPart::Lit { value: vec![ch], quote: 0, src: vec![] }])) }
            }
            b'\n' => None,
            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn todo(&mut self, _l: usize, _c: usize, line: usize) {
        eprintln!();
        eprintln!("thread 'main' ({}) panicked at src/syntax/lexer/automata/expansion.rs:{}:17:", std::process::id(), line);
        eprintln!("not yet implemented");
        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        std::process::exit(101);
    }

    fn str_lit_sq(&mut self, l: usize, c: usize) -> Vec<u8> {
        let allow: &[u8] = &[b'\''];
        let mut out = Vec::new();
        self.bump();
        loop {
            if self.eof() { self.err(self.line, self.col, "unexpected end of file.".into()); break; }
            let ch = self.cur();
            if ch == b'\'' { self.bump(); break; }
            if ch == b'\\' { out.push(self.unescape(l, c, allow)); continue; }
            out.push(self.bump());
        }
        out
    }

    fn word(&mut self) -> Option<Tok> {
        let (l, c) = (self.line, self.col);
        let st = self.pos;
        let mut parts: Vec<WPart> = Vec::new();
        let mut lit = Vec::new();
        loop {
            if self.eof() { break; }
            let ch = self.cur();
            match ch {
                b'\\' => {
                    // escape
                    let nx = self.at(1);
                    if nx == b'\n' {
                        if !lit.is_empty() { parts.push(WPart::Lit { value: std::mem::take(&mut lit), quote: 0, src: vec![] }); }
                        self.bump(); self.bump();
                        parts.push(WPart::Lit { value: vec![b'\\'], quote: 0, src: vec![] });
                        break;
                    }
                    if nx == b'n' || nx == b't' || nx == b'r' || nx == b'0' {
                        let sc = self.col; let _ = sc;
                        lit.push(self.bump()); lit.push(self.bump());
                        self.unescape(l, c, &[b'\'']);
                        continue;
                    }
                    if !lit.is_empty() { parts.push(WPart::Lit { value: std::mem::take(&mut lit), quote: 0, src: vec![] }); }
                    let v = self.unescape(l, c, &[b'\'']);
                    lit.push(v);
                    continue;
                }
                b'$' => {
                    if !lit.is_empty() { parts.push(WPart::Lit { value: std::mem::take(&mut lit), quote: 0, src: vec![] }); }
                    match self.dollar() {
                        Some(n) => parts.push(WPart::Exp(n)),
                        None => {}
                    }
                    continue;
                }
                _ if is_word_char(ch) => { lit.push(self.bump()); }
                _ => break,
            }
        }
        if !lit.is_empty() { parts.push(WPart::Lit { value: lit, quote: 0, src: vec![] }); }
        if parts.is_empty() { return None; }
        // rebuild the raw text from the source
        let raw = self.src[st..self.pos].to_vec();
        // if the whole thing is only literals without quotes, allow it as a word
        if parts.len() == 1 {
            if let WPart::Lit { value, quote: 0, .. } = &parts[0] {
                let txt = String::from_utf8_lossy(value).to_string();
                if !txt.is_empty() && txt.bytes().all(|b| b.is_ascii_digit()) {
                    if let Ok(v) = txt.parse::<i64>() {
                        // integer word
                        let _ = raw;
                        return Some(Tok::Int(v));
                    }
                    if txt == "*" || txt == "%" || txt == "~" || txt == "~/" {
                        return Some(Tok::Glob(value.clone()));
                    }
                }
                if txt == "*" || txt == "%" || txt == "~" || txt == "~/" { return Some(Tok::Glob(value.clone())); }
            }
        }
        Some(Tok::Word(parts))
    }

    fn dollar(&mut self) -> Option<Vec<u8>> {
        // at '$'
        let (l, c) = (self.line, self.col);
        self.bump();
        if self.cur() == b'{' {
            self.bump();
            let mut txt = Vec::new();
            loop {
                if self.eof() { break; }
                if self.cur() == b'}' { self.bump(); break; }
                let ch = self.cur();
                if ch == b'\\' {
                    let v = self.unescape(l, c, &[b'\'']);
                    txt.push(v);
                    continue;
                }
                txt.push(self.bump());
            }
            if txt.is_empty() || !(is_idc(txt[0]) && txt[0].is_ascii_alphabetic() || txt[0] == b'_') || txt.iter().any(|b| !is_idc(*b)) {
                let shown = crate::repr_bytes(&txt);
                self.err(l, c, format!("invalid identifier '{}'.", shown));
                return None;
            }
            return Some(txt);
        }
        // plain identifier
        let st = self.pos;
        while !self.eof() && is_idc(self.cur()) { self.bump(); }
        let name = self.src[st..self.pos].to_vec();
        if !name.is_empty() {
            if is_idc(name[0]) { return Some(name); }
            // digit start: not a valid identifier
            let _ = st;
        }
        // invalid: gather text
        let mut txt = Vec::new();
        // first, read until whitespace
        while !self.eof() && !is_ws(self.cur()) && is_word_char(self.cur()) { txt.push(self.bump()); }
        if txt.is_empty() {
            if !self.eof() { txt.push(self.bump()); }
            while !self.eof() && !is_ws(self.cur()) && is_word_char(self.cur()) { txt.push(self.bump()); }
        }
        let shown = crate::repr_bytes(&txt);
        self.err(l, c, format!("invalid identifier '{}'.", shown));
        None
    }
}

pub fn byte_disp(b: u8) -> String {
    match b {
        b'\n' => "'\\n'".into(),
        b'\t' => "'\\t'".into(),
        b'\r' => "'\\r'".into(),
        _ => format!("'{}'", b as char),
    }
}
RSEOF
echo ok"}

