use crate::ast::WPart;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Kw {
    Let, Function, End, If, Then, ElseIf, Else, While, Do, For, In, Return, Break,
    And, Or, Not, True, False, Nil, Self_,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Id(Vec<u8>),
    Int(i64),
    Float(f64),
    Char(u8),
    Str(Vec<u8>),
    Kw(Kw),
    LParen, RParen, LBracket, RBracket, Colon, Comma, Dot, Assign,
    Plus, Minus, Star, Slash, Percent,
    PlusPlus, EqEq, NotEq, Lt, Gt, Le, Ge,
    At,                 // @[
    LBrace, RBrace, AmpBrace, DollarBrace,
    Pipe, Semi, Question,
    Word(Vec<WPart>),
    Glob(Vec<u8>),
    Redirect(Option<u8>, bool),
    InRedirect(bool),
    Amp, Eof,
}

pub struct Token { pub tok: Tok, pub line: usize, pub col: usize }

pub struct LexErr { pub line: usize, pub col: usize, pub msg: String }

const KEYWORDS: &[(&str, Kw)] = &[
    ("let", Kw::Let), ("function", Kw::Function), ("end", Kw::End), ("if", Kw::If),
    ("then", Kw::Then), ("elseif", Kw::ElseIf), ("else", Kw::Else), ("while", Kw::While),
    ("do", Kw::Do), ("for", Kw::For), ("in", Kw::In), ("return", Kw::Return),
    ("break", Kw::Break), ("and", Kw::And), ("or", Kw::Or), ("not", Kw::Not),
    ("true", Kw::True), ("false", Kw::False), ("nil", Kw::Nil), ("self", Kw::Self_),
];

fn is_idc(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }
fn is_ws(b: u8) -> bool { b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' }
fn is_word_char(b: u8) -> bool {
    !matches!(b, b' ' | b'\t' | b'\n' | b'\r' | b';' | b'#' | b'?' | b'>' | b'<' | b'"' | b'\'' | b'\\' | b'$' | b'}' | b'|' | b'&' | b'@' | b'~' | b'{' | b'[')
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub line: usize,
    pub col: usize,
    depth: usize,
    pub errors: Vec<LexErr>,
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        Lexer { src, pos: 0, line: 0, col: 0, depth: 0, errors: Vec::new() }
    }
    fn cur(&self) -> u8 { if self.pos < self.src.len() { self.src[self.pos] } else { 0 } }
    fn at(&self, n: usize) -> u8 { if self.pos + n < self.src.len() { self.src[self.pos + n] } else { 0 } }
    fn eof(&self) -> bool { self.pos >= self.src.len() }
    fn bump(&mut self) -> u8 {
        let b = self.cur();
        if self.pos < self.src.len() {
            self.pos += 1;
            if b == b'\n' { self.line += 1; self.col = 0; } else { self.col += 1; }
        }
        b
    }
    fn err(&mut self, line: usize, col: usize, msg: String) { self.errors.push(LexErr { line, col, msg }); }

    pub fn lex(&mut self) -> Vec<Token> {
        let mut out = Vec::new();
        loop {
            self.ws();
            let (l, c) = (self.line, self.col);
            if self.eof() { out.push(Token { tok: Tok::Eof, line: l, col: c }); break; }
            let b = self.cur();
            let t = if self.depth == 0 { self.out_tok(b, l, c) } else { self.in_tok(b, l, c) };
            match t { Some(t) => out.push(Token { tok: t, line: l, col: c }), None => {} }
        }
        out
    }

    fn ws(&mut self) {
        loop {
            while !self.eof() && is_ws(self.cur()) { self.bump(); }
            if self.cur() == b'#' { while !self.eof() && self.cur() != b'\n' { self.bump(); } continue; }
            break;
        }
    }

    // ============ outside command blocks ============
    fn out_tok(&mut self, b: u8, l: usize, c: usize) -> Option<Tok> {
        match b {
            b'(' => { self.bump(); Some(Tok::LParen) }
            b')' => { self.bump(); Some(Tok::RParen) }
            b'[' => { self.bump(); Some(Tok::LBracket) }
            b']' => { self.bump(); Some(Tok::RBracket) }
            b':' => { self.bump(); Some(Tok::Colon) }
            b',' => { self.bump(); Some(Tok::Comma) }
            b'=' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::EqEq) } else { Some(Tok::Assign) } }
            b'+' => { self.bump(); if self.cur() == b'+' { self.bump(); Some(Tok::PlusPlus) } else { Some(Tok::Plus) } }
            b'-' => { self.bump(); Some(Tok::Minus) }
            b'*' => { self.bump(); Some(Tok::Star) }
            b'/' => { self.bump(); Some(Tok::Slash) }
            b'%' => { self.bump(); Some(Tok::Percent) }
            b'<' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::Le) } else { Some(Tok::Lt) } }
            b'>' => { self.bump(); if self.cur() == b'=' { self.bump(); Some(Tok::Ge) } else { Some(Tok::Gt) } }
            b'.' => { self.bump(); Some(Tok::Dot) }
            b'"' => { let s = self.str_lit(l, c, true); Some(Tok::Str(s.0)) }
            b'\'' => { let v = self.char_lit(l, c, true); Some(Tok::Char(v)) }
            b'@' => {
                self.bump();
                if self.cur() == b'[' { self.bump(); Some(Tok::At) }
                else { self.err(l, c, "unexpected '@'.".into()); None }
            }
            b'|' => { self.bump(); self.err(l, c, "unexpected '|'.".into()); None }
            b'$' => { self.bump(); self.err(l, c, "unexpected '$'.".into()); None }
            b'&' => { self.bump(); self.err(l, c, "unexpected '&'.".into()); None }
            b';' => { self.bump(); self.err(l, c, "unexpected ';'.".into()); None }
            b'~' => { self.bump(); self.err(l, c, "unexpected '~'.".into()); None }
            b'\\' => { self.bump(); self.err(l, c, "unexpected '\\'.".into()); None }
            b'}' => { self.bump(); self.err(l, c, "unexpected '}'.".into()); None }
            b'?' => { self.bump(); Some(Tok::Question) }
            b'_' | b'a'..=b'z' | b'A'..=b'Z' => self.ident(),
            b'0'..=b'9' => self.num(l, c),
            _ => { self.bump(); self.err(l, c, format!("unexpected '{}'.", byte_disp(b))); None }
        }
    }

    fn ident(&mut self) -> Tok {
        let st = self.pos;
        while !self.eof() && is_idc(self.cur()) { self.bump(); }
        let s = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("");
        for (k, kk) in KEYWORDS { if *k == s { return Tok::Kw(*kk); } }
        Tok::Id(self.src[st..self.pos].to_vec())
    }

    fn num(&mut self, l: usize, c: usize) -> Tok {
        let st = self.pos;
        while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
        let mut isf = false;
        if self.cur() == b'.' && self.at(1).is_ascii_digit() {
            self.bump();
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            isf = true;
        }
        if (self.cur() == b'e' || self.cur() == b'E') && self.at(1).is_ascii_digit() {
            self.bump();
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            isf = true;
        }
        let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
        if self.cur() == b'.' || self.cur() == b'e' || self.cur() == b'E' {
            let bad = if self.eof() { "end of file".to_string() } else { format!("'{}'.", self.cur() as char) };
            self.err(l, c, format!("unexpected {}.", bad));
            if !self.eof() { self.bump(); }
            self.pos = st; self.line = l; self.col = c;
            while !self.eof() && self.cur().is_ascii_digit() { self.bump(); }
            let txt = std::str::from_utf8(&self.src[st..self.pos]).unwrap_or("").to_string();
            return match txt.parse::<i64>() {
                Ok(v) => Tok::Int(v),
                Err(_) => { self.err(l, c, format!("invalid number '{}'.", txt)); Tok::Int(0) }
            };
        }
