use std::rc::Rc;
use std::cell::RefCell;
use std::collections::HashMap;
use crate::colors::Cols;
use crate::ast::Pos;

pub type SlotCell = Rc<RefCell<Value>>;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Char(u8),
    Str(Vec<u8>),
    Arr(Rc<RefCell<Vec<Value>>>),
    Dict(Rc<RefCell<HashMap<Vec<u8>, Value>>>),
    Func(Rc<FuncVal>),
    Err(Rc<ErrVal>),
    Job(Rc<JobVal>),
}

pub struct FuncVal {
    pub name: String,          // display name; "" for closures
    pub pos: Pos,
    pub params: Vec<Vec<u8>>,
    pub kinds: Vec<crate::ast::SlotKind>,
    pub body: crate::ast::Block,
    pub captures: Vec<(usize, usize)>,
    pub captured: Vec<SlotCell>,   // parent cells, indexed by capture parent slot
    pub native: Option<Native>,
    pub this: Option<Value>,       // for bound functions: the `self`
}

pub type Native = fn(&mut Interp, Vec<Value>) -> Result<Value, Panic>;

pub struct ErrVal { pub msg: Vec<u8>, pub typ: Value }
pub struct JobVal { pub rx: std::sync::mpsc::Receiver<Value>, pub joined: RefCell<bool> }

#[derive(Clone)]
pub struct Panic { pub msg: String }

pub fn fmt_disp(v: f64) -> String { format!("{}", v) }
pub fn fmt_dbg(v: f64) -> String { format!("{:?}", v) }

pub fn repr_bytes(b: &[u8]) -> String {
    let c = Cols::new(false);
    crate::printer::esc_bytes(b, &c)
}
pub fn repr_char(b: u8, _c: &Cols) -> String {
    let c = Cols::new(false);
    crate::printer::esc_bytes(&[b], &c)
}

pub fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Nil => "nil",
        Value::Bool(_) => "bool",
        Value::Int(_) => "int",
        Value::Float(_) => "float",
        Value::Char(_) => "char",
        Value::Str(_) => "string",
        Value::Arr(_) => "array",
        Value::Dict(_) => "dict",
        Value::Func(_) => "function",
        Value::Err(_) => "error",
        Value::Job(_) => "dict",
    }
}

pub fn repr(v: &Value, c: &Cols) -> String {
    match v {
        Value::Nil => c.yellow("nil"),
        Value::Bool(b) => c.yellow(if *b { "true" } else { "false" }),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => fmt_dbg(*f),
        Value::Char(ch) => c.yellow(&crate::printer::esc_bytes(&[*ch], c)),
        Value::Str(s) => { let mut o = String::new(); o.push_str(&c.yellow("\"")); o.push_str(&crate::printer::esc_bytes(s, c)); o.push_str(&c.yellow("\"")); o }
        Value::Arr(a) => {
            let mut o = String::new();
            o.push_str("[ ");
            let items = a.borrow().clone();
            for (i, x) in items.iter().enumerate() { if i > 0 { o.push_str(", "); } o.push_str(&repr(x, c)); }
            o.push_str(" ]");
            o
        }
        Value::Dict(d) => {
            let mut o = String::new();
            o.push_str("@[ ");
            let items: Vec<(Vec<u8>, Value)> = d.borrow().iter().map(|(k, v)| (k.clone(), v.clone())).collect();
            for (i, (k, v)) in items.iter().enumerate() { if i > 0 { o.push_str(", "); } o.push_str(&c.yellow("\"")); o.push_str(&crate::printer::esc_bytes(k, c)); o.push_str(&c.yellow("\": ")); o.push_str(&repr(v, c)); }
            o.push_str(" ]");
            o
        }
        Value::Func(f) => {
            if f.name.is_empty() { format!("function<{} (line {}, column {})>", c.green(""), f.pos.line, f.pos.col) }
            else { f.name.clone() }
        }
        Value::Err(e) => {
            let mut o = String::new();
            o.push_str(&c.yellow("error: "));
            o.push_str(&c.yellow("\"")); o.push_str(&crate::printer::esc_bytes(&e.msg, c)); o.push_str(&c.yellow("\""));
            o.push_str(" ("); o.push_str(&repr(&e.typ, c)); o.push_str(")");
            o
        }
        Value::Job(j) => {
            let _ = j;
            "@[ \"join\": <command>.join ]".to_string()
        }
    }
}

pub fn to_string(v: &Value) -> Vec<u8> {
    match v {
        Value::Nil => b"nil".to_vec(),
        Value::Bool(b) => if *b { b"true".to_vec() } else { b"false".to_vec() },
        Value::Int(i) => i.to_string().into_bytes(),
        Value::Float(f) => crate::printer::float_disp_bytes(*f),
        Value::Char(ch) => vec![*ch],
        Value::Str(s) => s.clone(),
        Value::Arr(_) | Value::Dict(_) | Value::Func(_) | Value::Err(_) | Value::Job(_) => crate::printer::float_disp_bytes(0.0),
    }
}
