use crate::ast::*;
use crate::interp::*;
use crate::value::*;
use std::collections::HashMap;
use std::os::unix::io::{AsRawFd, FromRawFd};
use std::process::Stdio;

#[derive(Clone)]
pub enum InSpec { Inherit, Here(Vec<u8>), File(String) }
#[derive(Clone)]
pub enum OutSpec { Inherit, File(String, bool), Fd(u8), Capture }

#[derive(Clone)]
pub struct Segment {
    pub argv: Vec<Vec<u8>>,
    pub stdin: InSpec,
    pub stdout: OutSpec,
    pub stderr: OutSpec,   // used for stderr fd or file
    pub pos: Pos,
}

#[derive(Clone)]
pub struct RunPlan {
    pub segs: Vec<Segment>,
}

// Expand a word into a list of argv values (usually one, or many for globs)
fn glob_matches(pattern_dir: &str, pat: &[u8]) -> Vec<String> {
    // pattern may contain `*` (many chars), `%` (single char) and `?`
    let dir = std::path::PathBuf::from(pattern_dir);
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(&dir) {
        let mut entries: Vec<String> = Vec::new();
        for e in rd.flatten() { if let Some(n) = e.file_name().to_str() { entries.push(n.to_string()); } }
        entries.sort();
        for e in entries {
            if crate::glob::match_word(pat, e.as_bytes()) {
                if pattern_dir == "." { out.push(format!("./{}", e)); }
                else if pattern_dir.is_empty() { out.push(e); }
                else { out.push(format!("{}/{}", pattern_dir, e)); }
            }
        }
    }
    out
}

fn home_dir() -> String { std::env::var("HOME").unwrap_or_default() }

pub fn word_to_args(w: &Word) -> Vec<Vec<u8>> {
    // build the literal text with expansions
    let mut s: Vec<u8> = Vec::new();
    let mut has_glob = false;
    let mut dollar = false;
    for p in &w.parts {
        match p {
            WPart::Lit { value, quote, src } => {
                let _ = src;
                if *quote == 0 { s.extend_from_slice(value); }
                else { s.extend_from_slice(value); }
            }
            WPart::Exp(_) => {}
        }
    }
    let _ = has_glob;
    let _ = dollar;
    vec![s]
}

pub fn build_segment(seg: &Segment) -> Result<(Vec<Vec<u8>>), crate::value::Panic> { Ok(seg.argv.clone()) }
