use crate::ast::*;
use crate::value::*;
use crate::ast::Pos;
use std::rc::Rc;
use std::cell::RefCell;
use std::collections::HashMap;

pub enum Flow { Val(Value), Ret(Value), Try(Value), Brk }

pub struct Env {
    pub slots: Vec<SlotCell>,
}

pub struct Interp {
    pub out: std::io::BufWriter<std::io::Stdout>,
    pub file: String,
    pub globals: Vec<SlotCell>,
    pub modules: HashMap<String, Value>,
    pub exit: Option<i32>,
    pub rng: Option<u64>,
    pub cwd: String,
}

fn mkcell(v: Value) -> SlotCell { Rc::new(RefCell::new(v)) }

impl Interp {
    pub fn new(file: &str, globals: Vec<SlotCell>) -> Self {
        Interp { out: std::io::BufWriter::new(std::io::stdout()), file: file.to_string(), globals,
                 modules: HashMap::new(), exit: None, rng: None, cwd: std::env::current_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_default() }
    }

    pub fn flush(&mut self) { let _ = self.out.flush(); }

    pub fn run_program(&mut self, prog: &Block) -> Value {
        let env = Env { slots: self.globals.clone() };
        match self.eval_block(prog, &env) {
            Flow::Val(v) | Flow::Try(v) => v,
            Flow::Ret(v) => v,
            Flow::Brk => Value::Nil,
        }
    }

    fn slot(&self, env: &Env, i: usize) -> Value {
        env.slots[i].borrow().clone()
    }

    fn set_slot(&self, env: &Env, i: usize, v: Value) {
        *env.slots[i].borrow_mut() = v;
    }

    pub fn eval_block(&mut self, b: &Block, env: &Env) -> Flow {
        let mut last = Flow::Val(Value::Nil);
        for st in &b.stmts {
            match self.eval_stmt(st, env) {
                Ok(v) => { last = v; if matches!(last, Flow::Ret(_) | Flow::Brk) { break; } }
                Err(p) => { return Err(p); }
            }
        }
        Ok(last)
    }

    fn eval_stmt(&mut self, st: &Stmt, env: &Env) -> Result<Flow, Panic> {
        match st {
            Stmt::Let(_, slot, e, _) => {
                let v = self.eval(e, env)?;
                self.set_slot(env, *slot, v);
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Assign(t, v, _) => {
                let val = self.eval(v, env)?;
                self.assign_lvalue(t, val, env)?;
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Expr(e, _) => {
                let v = self.eval(e, env)?;
                Ok(Flow::Val(v))
            }
            Stmt::If { cond, then, els, .. } => {
                let c = self.eval(cond, env)?;
                let b = match c { Value::Bool(b) => b, _ => return Err(self.cond_panic(cond, &c)) };
                if b { self.eval_block(then, env) } else if let Some(eb) = els { self.eval_block(eb, env) } else { Ok(Flow::Val(Value::Nil)) }
            }
            Stmt::While { cond, body, .. } => {
                loop {
                    let c = self.eval(cond, env)?;
                    let b = match c { Value::Bool(b) => b, _ => return Err(self.cond_panic(cond, &c)) };
                    if !b { break; }
                    match self.eval_block(body, env) {
                        Ok(Flow::Brk) => break,
                        Ok(_) => {}
                        Err(p) => return Err(p),
                        Ok(Flow::Ret(v)) => return Ok(Flow::Ret(v)),
                        Ok(Flow::Try(v)) => return Ok(Flow::Try(v)),
                        Ok(Flow::Val(_)) => {}
                    }
                }
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::For { var: _, slot, iter, body, .. } => {
                let f = self.eval(iter, env)?;
                let fun = match &f { Value::Func(x) => x.clone(), _ => return Err(self.call_panic(&f, iter)) };
                loop {
                    let r = self.call_fn(&fun, vec![], None, &iter)?;
                    match r {
                        Value::Dict(d) => {
                            let finished = match d.borrow().get(b"finished") {
                                Some(Value::Bool(b)) => *b,
                                _ => return Err(Panic { msg: "iteration has no 'finished' field".into() }),
                            };
                            if finished { break; }
                            let val = d.borrow().get(b"value").cloned().unwrap_or(Value::Nil);
                            self.set_slot(env, *slot, val);
                            match self.eval_block(body, env) {
                                Ok(Flow::Brk) => break,
                                Err(p) => return Err(p),
                                Ok(Flow::Ret(v)) => return Ok(Flow::Ret(v)),
                                Ok(Flow::Try(v)) => return Ok(Flow::Try(v)),
                                Ok(_) => {}
