                                Some(Value::Bool(b)) => *b,
                                _ => return Err(Panic { msg: "iteration has no 'finished' field".into() }),
                            };
                            if finished { break; }
                            let val = d.borrow().get(b"value").cloned().unwrap_or(Value::Nil);
                            self.set_slot(env, *slot, val);
                            match self.eval_block(body, env) {
                                Ok(Flow::Brk) => break,
                                Err(p) => return Err(p),
                                Ok(Flow::Ret(v)) => return Ok(Flow::Ret(v)),
                                Ok(Flow::Try(v)) => return Ok(Flow::Try(v)),
                                Ok(_) => {}
                            }
                        }
                        _ => return Err(Panic { msg: "iteration has no 'finished' field".into() }),
                    }
                }
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Return(e, _) => {
                let v = self.eval(e, env)?;
                Ok(Flow::Ret(v))
            }
            Stmt::Break(_) => Ok(Flow::Brk),
            Stmt::Cmd(cb, _) => {
                match cb.kind {
                    BlockKind::Plain => { let _ = self.run_block(cb, env)?; Ok(Flow::Val(Value::Nil)) }
                    _ => {
                        let v = self.eval(Stmt::Expr(Expr::Cmd(Box::new(cb.clone()), NOPOS), NOPOS).as_expr(), env)?;
                        Ok(Flow::Val(v))
                    }
                }
            }
            Stmt::Func(_, f, _) => {
                let fv = self.make_closure(f, env)?;
                // assigned by the slot pass: the statement slot is implicit
                let _ = fv;
                Ok(Flow::Val(Value::Nil))
            }
        }
    }
}

