                            Value::Bool(b2) => Ok(Value::Bool(b2)),
                            _ => Err(panic_here(&self.file, crate::expr_pos(b), format!("value ({}) has unexpected type, expected bool", crate::value::repr(&y)))),
                        }
                    }
                    BinOp::Or => {
                        let x = self.eval(a, env)?;
                        let xb = match x { Value::Bool(b) => b, _ => return Err(panic_here(&self.file, crate::expr_pos(a), format!("value ({}) has unexpected type, expected bool", crate::value::repr(&x)))) };
                        if xb { return Ok(Value::Bool(true)); }
