            Expr::Cmd(cb, _) => {
                match cb.kind {
                    BlockKind::Capture => self.run_block(cb, env, BlockKind::Capture),
                    BlockKind::Async => self.make_job(cb, env),
                    BlockKind::Plain => {
                        let r = self.run_block(cb, env, BlockKind::Plain)?;
