impl Interp {
    pub fn call_fn(&mut self, f: &Rc<FuncVal>, mut args: Vec<Value>, this: Option<Value>) -> Result<Value, Panic> {
        if let Some(n) = f.native {
            if args.len() < f.params.len() {
                return Err(panic_top(&self.file, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), f.params.len())));
            }
            if f.params.len() == 0 { args.clear(); }
            return n(self, args);
        }
        if args.len() != f.params.len() {
            return Err(panic_top(&self.file, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), f.params.len())));
        }
        let mut slots: Vec<SlotCell> = Vec::with_capacity(f.kinds.len());
        let mut i = 0;
        for k in &f.kinds {
            match k {
                SlotKind::Auto => { slots.push(mkcell(Value::Nil)); }
                SlotKind::Self_ => { slots.push(mkcell(this.clone().unwrap_or(Value::Nil))); }
                SlotKind::Capture(ps) => {
                    // find the captured cell for parent slot *ps
                    let cell = f.captured.iter().find(|(idx, _)| *idx == *ps).map(|(_, c)| c.clone());
                    match cell {
                        Some(c) => slots.push(c),
                        None => slots.push(mkcell(Value::Nil)),
                    }
                }
            }
            let _ = i; i += 1;
        }
        for (j, a) in args.into_iter().enumerate() { *slots[j].borrow_mut() = a; }
        let env = Env { slots };
        match self.eval_block(&f.body, &env) {
            Flow::Val(v) | Flow::Ret(v) | Flow::Try(v) => Ok(v),
            Flow::Brk => Ok(Value::Nil),
        }
    }

    fn make_closure(&mut self, f: &FuncLit, env: &Env) -> Result<Value, Panic> {
        let mut captures = Vec::new();
        let mut captured = Vec::new();
        for (i, k) in f.kinds.iter().enumerate() {
            if let SlotKind::Capture(ps) = k {
                captures.push(i);
                captured.push((*ps, env.slots[*ps].clone()));
            }
        }
        Ok(Value::Func(Rc::new(FuncVal {
            name: String::new(), pos: f.pos, params: f.params.clone(), kinds: f.kinds.clone(),
            body: f.body.clone(), captures, captured, native: None, this: None,
        })))
    }

    pub fn index(&mut self, ov: &Value, iv: &Value, ipos: Pos) -> Result<Value, Panic> {
        let file = self.file.clone();
        match ov {
            Value::Dict(d) => {
                let k = match iv { Value::Str(s) => s.clone(), _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected string", crate::value::repr(iv)))) };
                match d.borrow().get(&k) { Some(v) => Ok(v.clone()), None => Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))) }
            }
            Value::Arr(a) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected int", crate::value::repr(iv)))) };
                let av = a.borrow();
                if i < 0 || (i as usize) >= av.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                Ok(av[i as usize].clone())
            }
            Value::Str(s) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected int", crate::value::repr(iv)))) };
                if i < 0 || (i as usize) >= s.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                Ok(Value::Char(s[i as usize]))
            }
            Value::Err(_) => Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))),
            _ => Err(panic_here(&file, crate::expr_pos(&Expr::Nil(NOPOS)), format!("value ({}) has unexpected type, expected string, array, dict or error", crate::value::repr(ov)))),
        }
    }

    pub fn assign_lvalue(&mut self, t: &Expr, v: Value, env: &Env) -> Result<(), Panic> {
        let file = self.file.clone();
        match t {
            Expr::Var(_, _, slot) => { *env.slots[*slot].borrow_mut() = v; Ok(()) }
            Expr::Self_(_, slot) => { *env.slots[*slot].borrow_mut() = v; Ok(()) }
            Expr::Member(o, k, p) => {
                let ov = self.eval(o, env)?;
                self.set_index(&ov, &Value::Str(k.clone()), v, *p)
            }
            Expr::Index(o, i, p) => {
                let ov = self.eval(o, env)?;
                let iv = self.eval(i, env)?;
                self.set_index(&ov, &iv, v, *p)
            }
            _ => Err(panic_here(&file, NOPOS, "invalid assignment".into())),
        }
    }

    fn set_index(&mut self, ov: &Value, iv: &Value, v: Value, ipos: Pos) -> Result<(), Panic> {
        let file = self.file.clone();
        match ov {
            Value::Dict(d) => {
                let k = match iv { Value::Str(s) => s.clone(), _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected string", crate::value::repr(iv)))) };
                d.borrow_mut().insert(k, v);
                Ok(())
            }
            Value::Arr(a) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected int", crate::value::repr(iv)))) };
                let mut av = a.borrow_mut();
                if i < 0 || (i as usize) >= av.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                av[i as usize] = v;
                Ok(())
            }
            Value::Err(_) => Ok(()),
            _ => Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected array, dict or error", crate::value::repr(ov)))),
        }
    }
}

