pub fn expr_pos(e: &Expr) -> Pos {
    match e {
        Expr::Nil(p) | Expr::Bool(_, p) | Expr::Int(_, p) | Expr::Float(_, p) | Expr::Char(_, p)
        | Expr::Str(_, p) | Expr::Array(_, p) | Expr::Dict(_, p) | Expr::Call(_, _, p)
        | Expr::Index(_, _, p) | Expr::Member(_, _, p) | Expr::Unary(_, _, p)
        | Expr::Try(_, p) | Expr::If(_, _, _, p) | Expr::Func(_, p) | Expr::Cmd(_, p)
        | Expr::Self_(p, _) => *p,
        Expr::Var(_, p, _) => *p,
        Expr::Binary(_, _, _, _) => NOPOS,
    }
}

fn type_err(file: &str, pos: Pos, v: &Value, exp: &str) -> Panic {
    panic_here(file, pos, format!("value ({}) has unexpected type, expected {}", crate::value::repr(v), exp))
}

pub fn binop(_it: &mut Interp, op: BinOp, x: &Value, y: &Value, p: Pos, pa: Pos, pb: Pos) -> Result<Value, Panic> {
    let file = &_it.file.clone();
    match op {
        BinOp::Concat => {
            let a = crate::value::to_bytes(x);
            let b = crate::value::to_bytes(y);
            let mut o = a; o.extend_from_slice(&b);
            Ok(Value::Str(o))
        }
        _ => {
            match (x, y) {
                (Value::Int(a), Value::Int(b)) => match op {
                    BinOp::Plus => Ok(Value::Int(a.wrapping_add(*b))),
                    BinOp::Minus => Ok(Value::Int(a.wrapping_sub(*b))),
                    BinOp::Star => Ok(Value::Int(a.wrapping_mul(*b))),
                    BinOp::Slash => if *b == 0 { Err(panic_here(file, p, "division by zero".into())) } else { Ok(Value::Int(a / b)) },
                    BinOp::Percent => if *b == 0 { Err(panic_here(file, p, "division by zero".into())) } else { Ok(Value::Int(a % b)) },
                    BinOp::Lt => Ok(Value::Bool(a < b)),
                    BinOp::Gt => Ok(Value::Bool(a > b)),
                    BinOp::Le => Ok(Value::Bool(a <= b)),
                    BinOp::Ge => Ok(Value::Bool(a >= b)),
                    BinOp::EqEq => Ok(Value::Bool(a == b)),
                    BinOp::NotEq => Ok(Value::Bool(a != b)),
                    _ => Ok(Value::Nil),
                },
                (Value::Float(a), Value::Float(b)) => match op {
                    BinOp::Plus => Ok(Value::Float(a + b)),
                    BinOp::Minus => Ok(Value::Float(a - b)),
                    BinOp::Star => Ok(Value::Float(a * b)),
                    BinOp::Slash => Ok(Value::Float(a / b)),
                    BinOp::Percent => Ok(Value::Float(a % b)),
                    BinOp::Lt => Ok(Value::Bool(a < b)),
                    BinOp::Gt => Ok(Value::Bool(a > b)),
                    BinOp::Le => Ok(Value::Bool(a <= b)),
                    BinOp::Ge => Ok(Value::Bool(a >= b)),
                    BinOp::EqEq => Ok(Value::Bool(a == b)),
                    BinOp::NotEq => Ok(Value::Bool(a != b)),
                    _ => Ok(Value::Nil),
                },
                (Value::Str(a), Value::Str(b)) => match op {
                    BinOp::Lt => Ok(Value::Bool(a.as_slice() < b.as_slice())),
                    BinOp::Gt => Ok(Value::Bool(a.as_slice() > b.as_slice())),
                    BinOp::Le => Ok(Value::Bool(a.as_slice() <= b.as_slice())),
                    BinOp::Ge => Ok(Value::Bool(a.as_slice() >= b.as_slice())),
                    BinOp::EqEq => Ok(Value::Bool(a == b)),
                    BinOp::NotEq => Ok(Value::Bool(a != b)),
                    _ => Err(panic_here(file, pa, format!("value ({}) has unexpected type, expected int or float", crate::value::repr(x)))),
                },
                (Value::Char(a), Value::Char(b)) => match op {
                    BinOp::Lt => Ok(Value::Bool(a < b)),
                    BinOp::Gt => Ok(Value::Bool(a > b)),
                    BinOp::Le => Ok(Value::Bool(a <= b)),
                    BinOp::Ge => Ok(Value::Bool(a >= b)),
                    BinOp::EqEq => Ok(Value::Bool(a == b)),
                    BinOp::NotEq => Ok(Value::Bool(a != b)),
                    _ => Err(panic_here(file, pa, format!("value ({}) has unexpected type, expected int or float", crate::value::repr(x)))),
                },
                _ => {
                    // equality between different types
                    if matches!(op, BinOp::EqEq) { return Ok(Value::Bool(false)); }
                    if matches!(op, BinOp::NotEq) { return Ok(Value::Bool(true)); }
                    // order comparisons: check the first operand's type
                    match x {
                        Value::Int(_) | Value::Float(_) | Value::Str(_) | Value::Char(_) => Err(panic_here(file, pb, format!("value ({}) has unexpected type, expected {}", crate::value::repr(y), match x {
                            Value::Int(_) => "int",
                            Value::Float(_) => "float",
                            Value::Str(_) => "string",
                            Value::Char(_) => "char",
                            _ => "",
                        }))),
                        _ => Err(panic_here(file, pa, format!("value ({}) has unexpected type, expected int, float, byte or string", crate::value::repr(x)))),
                    }
                }
            }
        }
    }
}

fn values_equal(x: &Value, y: &Value) -> bool {
    match (x, y) {
        (Value::Arr(a), Value::Arr(b)) => {
            let av = a.borrow().clone(); let bv = b.borrow().clone();
            av.len() == bv.len() && av.iter().zip(bv.iter()).all(|(x, y)| values_equal(x, y))
        }
        (Value::Dict(a), Value::Dict(b)) => {
            let ad = a.borrow().clone(); let bd = b.borrow().clone();
            ad.len() == bd.len() && ad.iter().all(|(k, v)| bd.get(k).map(|w| values_equal(v, w)).unwrap_or(false))
        }
        _ => {
            // structural equality via repr for other types
            crate::value::repr(x) == crate::value::repr(y)
        }
    }
}

impl Interp {
    pub fn call_fn(&mut self, f: &Rc<FuncVal>, mut args: Vec<Value>, this: Option<Value>) -> Result<Value, Panic> {
        if let Some(n) = f.native {
            if args.len() < f.params.len() {
                return Err(panic_top(&self.file, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), f.params.len())));
            }
            if f.params.len() == 0 { args.clear(); }
            return n(self, args);
        }
        if args.len() != f.params.len() {
            return Err(panic_top(&self.file, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), f.params.len())));
        }
        let mut slots: Vec<SlotCell> = Vec::with_capacity(f.kinds.len());
        let mut i = 0;
        for k in &f.kinds {
            match k {
                SlotKind::Auto => { slots.push(mkcell(Value::Nil)); }
                SlotKind::Self_ => { slots.push(mkcell(this.clone().unwrap_or(Value::Nil))); }
                SlotKind::Capture(ps) => {
                    // find the captured cell for parent slot *ps
                    let cell = f.captured.iter().find(|(idx, _)| *idx == *ps).map(|(_, c)| c.clone());
                    match cell {
                        Some(c) => slots.push(c),
                        None => slots.push(mkcell(Value::Nil)),
                    }
                }
            }
            let _ = i; i += 1;
        }
        for (j, a) in args.into_iter().enumerate() { *slots[j].borrow_mut() = a; }
        let env = Env { slots };
        match self.eval_block(&f.body, &env) {
            Flow::Val(v) | Flow::Ret(v) | Flow::Try(v) => Ok(v),
            Flow::Brk => Ok(Value::Nil),
        }
    }

    fn make_closure(&mut self, f: &FuncLit, env: &Env) -> Result<Value, Panic> {
        let mut captures = Vec::new();
        let mut captured = Vec::new();
        for (i, k) in f.kinds.iter().enumerate() {
            if let SlotKind::Capture(ps) = k {
                captures.push(i);
                captured.push((*ps, env.slots[*ps].clone()));
            }
        }
        Ok(Value::Func(Rc::new(FuncVal {
            name: String::new(), pos: f.pos, params: f.params.clone(), kinds: f.kinds.clone(),
            body: f.body.clone(), captures, captured, native: None, this: None,
        })))
    }

    pub fn index(&mut self, ov: &Value, iv: &Value, ipos: Pos) -> Result<Value, Panic> {
        let file = self.file.clone();
        match ov {
            Value::Dict(d) => {
                let k = match iv { Value::Str(s) => s.clone(), _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected string", crate::value::repr(iv)))) };
                match d.borrow().get(&k) { Some(v) => Ok(v.clone()), None => Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))) }
            }
            Value::Arr(a) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected int", crate::value::repr(iv)))) };
                let av = a.borrow();
                if i < 0 || (i as usize) >= av.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                Ok(av[i as usize].clone())
            }
            Value::Str(s) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected int", crate::value::repr(iv)))) };
                if i < 0 || (i as usize) >= s.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                Ok(Value::Char(s[i as usize]))
            }
            Value::Err(_) => Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))),
            _ => Err(panic_here(&file, crate::expr_pos(&Expr::Nil(NOPOS)), format!("value ({}) has unexpected type, expected string, array, dict or error", crate::value::repr(ov)))),
        }
