// ---------------- command execution ----------------
pub struct Argv { pub args: Vec<Vec<u8>> }

fn glob_dirs(pattern: &str) -> Vec<String> {
    // split off directory prefix
    let (dir, rest) = match pattern.rfind('/') {
        Some(i) => (pattern[..i].to_string(), pattern[i + 1..].to_string()),
        None => (String::new(), pattern.to_string()),
    };
    let mut out = Vec::new();
    let full_dir = if dir.is_empty() { ".".to_string() } else if dir.starts_with('/') { dir.clone() } else if dir.starts_with("./") { dir.clone() } else { format!("./{}", dir) };
    if let Ok(rd) = std::fs::read_dir(&full_dir) {
        let mut names: Vec<String> = Vec::new();
        for e in rd.flatten() { names.push(e.file_name().to_string_lossy().to_string()); }
        names.sort();
        for n in names {
            if crate::glob::match_word(rest.as_bytes(), n.as_bytes()) {
                let path = if dir.is_empty() { format!("./{}", n) } else { format!("{}/{}", full_dir, n) };
                out.push(path);
            }
        }
    }
    out
}

impl Interp {
    fn expand_word(&mut self, w: &Word, env: &Env) -> Result<Vec<Vec<u8>>, Panic> {
        let mut s: Vec<u8> = Vec::new();
        let mut globbable = false;
        for p in &w.parts {
            match p {
                WPart::Lit { value, quote, src } => {
                    let _ = src;
                    s.extend_from_slice(value);
                    if *quote == 0 {
                        if value.iter().any(|&b| b == b'*' || b == b'%') { globbable = true; }
                    }
                }
                WPart::Exp(n) => {
                    let v = match self.slot_of_name(n, env) { Some(i) => env.slots[i].borrow().clone(), None => Value::Nil };
                    s.extend_from_slice(&crate::value::to_bytes(&v));
                }
            }
        }
        if globbable {
            let m = glob_dirs(&String::from_utf8_lossy(&s));
            if m.is_empty() { return Ok(Vec::new()); }
            return Ok(m.into_iter().map(|x| x.into_bytes()).collect());
        }
        Ok(vec![s])
    }

    fn slot_of_name(&self, name: &[u8], env: &Env) -> Option<usize> {
        // use the parser's slot info: we need the mapping; use the global std slot for `std`
        None
    }

    fn expand_target(&mut self, w: &Option<Word>, env: &Env) -> Result<Vec<u8>, Panic> {
        match w {
            Some(w) => {
                let mut s = Vec::new();
                for p in &w.parts {
                    match p {
                        WPart::Lit { value, .. } => s.extend_from_slice(value),
                        WPart::Exp(n) => {
                            let v = Value::Nil;
                            let _ = v;
                        }
                    }
                }
                Ok(s)
            }
            None => Ok(Vec::new()),
        }
    }

    pub fn run_block(&mut self, cb: &CmdBlock, env: &Env, kind: BlockKind) -> Result<Value, Panic> {
        // build argv for all segments first
        let mut built: Vec<Vec<Vec<Vec<u8>>>> = Vec::new();   // per command: per segment: args
        let mut redirs: Vec<Vec<Vec<crate::ast::Redirect>>> = Vec::new();
        let mut poss: Vec<Vec<Pos>> = Vec::new();
        for cmd in &cb.cmds {
            let mut segargs = Vec::new();
            let mut segred = Vec::new();
            let mut segpos = Vec::new();
            for p in &cmd.pipes {
                for seg in &p.segs {
                    let mut args = Vec::new();
                    let mut any = false;
                    for w in &seg.words {
                        let r = self.expand_word(w, env)?;
                        if !r.is_empty() { any = true; }
                        args.extend(r);
                    }
                    if !any { return Ok(Value::Nil); }
                    segargs.push(args);
                    segred.push(seg.redirs.clone());
                    segpos.push(seg_pos(seg));
                }
            }
            built.push(segargs);
            redirs.push(segred);
            poss.push(segpos);
        }
        let _ = &redirs;
        let _ = &poss;
        match kind {
            BlockKind::Async => self.make_job_from(&built, env),
            _ => crate::cmdexec::run_cmds(self, &built, cb, env, kind),
        }
    }

    fn make_job_from(&mut self, built: &Vec<Vec<Vec<Vec<u8>>>>, _env: &Env) -> Result<Value, Panic> {
        let _ = built;
        let (tx, rx) = std::sync::mpsc::channel();
        let job = Rc::new(JobVal { rx, joined: std::cell::Cell::new(false) });
        let joinf = Value::Func(Rc::new(FuncVal {
            name: "<command>.join".into(),
            pos: NOPOS, params: vec![], kinds: vec![SlotKind::Auto],
            body: Block { stmts: vec![] }, captures: vec![], captured: vec![],
            native: Some(crate::stdlib::job_join), this: Some(Value::Job(job.clone())),
        }));
        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
        m.insert(b"join".to_vec(), joinf);
        let _ = tx;
        Ok(Value::Job(job))
    }
}

fn seg_pos(s: &Segment) -> Pos { NOPOS }
