{"command": "cd /workspace && cat > src/cmdexec.rs <<'RSEOF'
use crate::ast::*;
use crate::value::*;
use crate::interp::*;
use crate::Pos;
use std::rc::Rc;
use std::cell::RefCell;
use std::collections::HashMap;
use std::os::unix::io::{AsRawFd, FromRawFd};
use std::process::Stdio;

#[derive(Clone, Debug)]
pub enum InSpec { Inherit, Here(Vec<u8>), File(String) }
#[derive(Clone, Debug)]
pub enum OutSpec { Inherit, File(String, bool), Fd(u8), Capture }

#[derive(Clone, Debug)]
pub struct PlanSeg {
    pub argv: Vec<Vec<u8>>,
    pub stdin: InSpec,
    pub stdout: OutSpec,
    pub stderr: OutSpec,
    pub pos: Pos,
}

#[derive(Clone, Debug)]
pub struct PlanCmd { pub segs: Vec<PlanSeg>, pub pos: Pos }

pub struct Plan { pub cmds: Vec<PlanCmd> }

fn home_dir() -> String { std::env::var("HOME").unwrap_or_default() }

pub fn target_bytes(t: &Target) -> Vec<u8> {
    let mut s = Vec::new();
    for p in &t.parts {
        match p {
            WPart::Lit { value, .. } => s.extend_from_slice(value),
            WPart::Exp(_, _) => {}
        }
    }
    s
}

pub fn build_plan(cb: &CmdBlock, argvs: &[Vec<Vec<Vec<u8>>>>, redirs: &[Vec<Vec<Redirect>>], poss: &[Vec<Pos>]) -> Plan {
    let mut cmds = Vec::new();
    for (ci, cmd) in cb.cmds.iter().enumerate() {
        let mut segs = Vec::new();
        let mut idx = 0usize;
        for p in &cmd.pipes {
            for seg in &p.segs {
                let mut stdin = InSpec::Inherit;
                let mut stdout = OutSpec::Inherit;
                let mut stderr = OutSpec::Inherit;
                for r in &redirs[ci][idx] {
                    match r {
                        Redirect::Out { fd, append, target } => {
                            let path = String::from_utf8_lossy(&target_bytes(target)).to_string();
                            if target.is_num {
                                match fd {
                                    0 => { /* unsupported */ }
                                    1 => stdout = OutSpec::Fd(1),
                                    _ => {}
                                }
                                if target.num == 1 { stdout = OutSpec::Fd(1); }
                                else if target.num == 2 { stdout = OutSpec::Fd(2); }
                            } else {
                                if *fd == 0 { /* unsupported */ }
                                else if *fd == 1 { stdout = OutSpec::File(path, *append); }
                                else if *fd == 2 { stderr = OutSpec::File(path, *append); }
                            }
                        }
                        Redirect::In { target, here } => {
                            let path = String::from_utf8_lossy(&target_bytes(target)).to_string();
                            if *here { stdin = InSpec::Here(path.into_bytes()); }
                            else { stdin = InSpec::File(path); }
                        }
                    }
                }
                segs.push(PlanSeg { argv: argvs[ci][idx].clone(), stdin, stdout, stderr, pos: poss[ci][idx] });
                idx += 1;
            }
        }
        let pos = segs.first().map(|s| s.pos).unwrap_or(NOPOS);
        cmds.push(PlanCmd { segs, pos });
    }
    Plan { cmds }
}

// run a set of argv entries as a pipeline, with capture or inherit
pub struct RunOut { pub status: i64, pub stdout: Vec<u8>, pub stderr: Vec<u8>, pub fail: Option<Rc<ErrVal>> }

pub fn spawn_pipeline(segs: &[PlanSeg], capture: bool) -> Result<RunOut, String> {
    let n = segs.len();
    let mut pipe_out: Vec<Option<(std::os::unix::pipe::RwPair,)>> = Vec::new();
    let _ = &mut pipe_out;
    // create pipes between segments
    let mut pipes: Vec<Option<(i32, i32)>> = Vec::new();
    for _ in 0..n.saturating_sub(1) {
        match unix_pipe() {
            Ok((r, w)) => pipes.push(Some((r, w))),
            Err(e) => return Err(e),
        }
    }
    let mut cap_out: Option<(i32, i32)> = None;
    let mut cap_err: Option<(i32, i32)> = None;
    if capture {
        cap_out = unix_pipe().ok();
        cap_err = unix_pipe().ok();
    }
    let mut children = Vec::new();
    for (i, seg) in segs.iter().enumerate() {
        let mut cmd = std::process::Command::new(String::from_utf8_lossy(&seg.argv[0]).to_string());
        for a in &seg.argv[1..] { cmd.arg(String::from_utf8_lossy(a).to_string()); }
        // stdin
        match &seg.stdin {
