            Some(fd) if fd >= 0 => { let f = unsafe { std::fs::File::from_raw_fd(fd) }; cmd.stderr(std::process::Stdio::from(f)); }
            Some(_) => { cmd.stderr(std::process::Stdio::inherit()); }
