    let mut stderr = Vec::new();
    if let Some((r, w)) = cap_out { unsafe { c_close(w); } stdout = read_all(r); }
    if let Some((r, w)) = cap_err { unsafe { c_close(w); } stderr = read_all(r); }
    let mut statuses = Vec::new();
    for c in children.into_iter().flatten() {
        match c.wait() {
            Ok(st) => statuses.push(crate::cmdexec::status_of(&st)),
            Err(_) => statuses.push(-1),
        }
    }
