    }
    s
}

// expand all words of a segment into argv, applying glob expansion
pub fn expand_words(w: &[Word], env: &Env) -> Result<Vec<Vec<u8>>, Panic> {
    let mut out = Vec::new();
    for wd in w {
        let mut s: Vec<u8> = Vec::new();
        let mut globbable = false;
        for p in &wd.parts {
            match p {
                WPart::Lit { value, quote, src } => {
                    let _ = src;
                    s.extend_from_slice(value);
                    if *quote == 0 && value.iter().any(|&b| b == b'*' || b == b'%') { globbable = true; }
                }
                WPart::Exp(_, slot) => {
                    if *slot != usize::MAX {
                        let v = env.slots[*slot].borrow().clone();
                        s.extend_from_slice(&crate::value::to_bytes(&v));
                    }
                }
            }
        }
        if globbable {
            let m = crate::globm::glob_dirs(&String::from_utf8_lossy(&s));
            if m.is_empty() { continue; }
            for x in m { out.push(x.into_bytes()); }
        } else { out.push(s); }
    }
    Ok(out)
}

pub fn build_plan(cb: &CmdBlock, env: &Env) -> Result<Plan, Panic> {
    let mut cmds = Vec::new();
    for cmd in &cb.cmds {
        let mut segs = Vec::new();
        for p in &cmd.pipes {
            for seg in &p.segs {
                let argv = expand_words(&seg.words, env)?;
                let mut redirs = Vec::new();
                for r in &seg.redirs {
                    match r {
                        Redirect::Out { fd, append, target } => {
                            if target.is_num {
                                match target.num {
                                    1 => redirs.push((*fd, Act::Fd(1))),
                                    2 => redirs.push((*fd, Act::Fd(2))),
                                    _ => redirs.push((*fd, Act::Fd(target.num as u8))),
                                }
                            } else {
                                let path = String::from_utf8_lossy(&target_bytes(target, env)).to_string();
                                redirs.push((*fd, Act::File(path, *append)));
                            }
                        }
                        Redirect::In { target, here } => {
                            let t = String::from_utf8_lossy(&target_bytes(target, env)).to_string();
                            if *here { redirs.push((0, Act::Here(t.into_bytes()))); }
                            else { redirs.push((0, Act::File(t, false))); }
                        }
                    }
                }
                segs.push(Seg { argv, redirs, pos: seg.pos });
            }
        }
        let pos = segs.first().map(|s| s.pos).unwrap_or(NOPOS);
        cmds.push(PlanCmd { segs, pos });
    }
    Ok(Plan { cmds })
}

extern "C" { fn close(fd: i32) -> i32; fn pipe(fds: *mut i32) -> i32; fn dup2(a: i32, b: i32) -> i32; fn read(fd: i32, buf: *mut u8, n: usize) -> isize; fn write(fd: i32, buf: *const u8, n: usize) -> isize; fn fcntl(fd: i32, cmd: i32, arg: i32) -> i32; }

pub fn mk_pipe() -> Result<(i32, i32), String> {
    let mut fds = [0i32; 2];
    let r = unsafe { pipe(fds.as_mut_ptr()) };
    if r != 0 { return Err("pipe failed".into()); }
    Ok((fds[0], fds[1]))
}

pub unsafe fn c_close(fd: i32) { let _ = close(fd); }

pub fn read_all(fd: i32) -> Vec<u8> {
    let mut out = Vec::new();
    let mut buf = [0u8; 4096];
    loop {
        let n = unsafe { read(fd, buf.as_mut_ptr(), 4096) };
        if n <= 0 { break; }
        out.extend_from_slice(&buf[..n as usize]);
    }
    unsafe { c_close(fd) };
    out
}

pub struct Res { pub statuses: Vec<i64>, pub stdout: Vec<u8>, pub stderr: Vec<u8>, pub spawn_err: Option<String> }

pub fn run_pipeline(segs: &[Seg], capture: bool) -> Res {
    let n = segs.len();
    let mut pipes: Vec<Option<(i32, i32)>> = Vec::new();
    for _ in 0..n.saturating_sub(1) {
        match mk_pipe() { Ok(p) => pipes.push(Some(p)), Err(_) => pipes.push(None) }
    }
    let cap_out = if capture { mk_pipe().ok() } else { None };
    let cap_err = if capture { mk_pipe().ok() } else { None };

    // resolve fd sources
    // src[i] = (fd, i32) meaning "in the child, fd should come from this raw fd"
    let mut children: Vec<Option<std::process::Child>> = Vec::new();
    let mut spawn_err: Option<String> = None;
    for (i, seg) in segs.iter().enumerate() {
        // default sources
        let mut in_src: Option<i32> = None;   // None = inherit 0
        if i == 0 { in_src = None; } else {
            if let Some((r, _)) = pipes[i - 1] { in_src = Some(r); }
        }
        let mut out_src: Option<i32> = None;
        if i == n - 1 {
            if let Some((_, w)) = cap_out { out_src = Some(w); }
        } else if let Some((_, w)) = pipes[i] { out_src = Some(w); }
        let mut err_src: Option<i32> = None;
        if i == n - 1 { if let Some((_, w)) = cap_err { err_src = Some(w); } }
        let mut here: Option<Vec<u8>> = None;
        for (fd, act) in &seg.redirs {
            match act {
                Act::File(p, app) => {
                    if *fd == 0 {
                        match std::fs::File::open(p) { Ok(f) => { in_src = Some(std::os::unix::io::AsRawFd::as_raw_fd(&f)); std::mem::forget(f); }, Err(_) => { spawn_err = Some("No such file or directory (os error 2)".into()); } }
                    } else {
                        match std::fs::OpenOptions::new().write(true).create(true).append(*app).open(p) {
                            Ok(f) => { let r = std::os::unix::io::AsRawFd::as_raw_fd(&f); if *fd == 1 { out_src = Some(r); } else { err_src = Some(r); } std::mem::forget(f); }
                            Err(e) => { spawn_err = Some(e.to_string()); }
                        }
                    }
                }
                Act::Fd(t) => {
                    match (*fd, *t) {
                        (1, 1) => { out_src = None; }
                        (1, 2) => { out_src = Some(-2); }
                        (2, 1) => { err_src = Some(-1); }
                        (2, 2) => { err_src = None; }
                        (2, 0) | (1, 0) => { spawn_err = Some(format!("unsupported file descriptor ({})", t)); }
                        _ => {}
                    }
                }
                Act::Here(s) => { here = Some(s.clone()); }
            }
        }
        if spawn_err.is_some() {
            // close already opened pipes
            for p in pipes.iter().flatten() { unsafe { c_close(p.0); c_close(p.1); } }
            return Res { statuses: vec![127], stdout: Vec::new(), stderr: Vec::new(), spawn_err };
        }
        let mut cmd = std::process::Command::new(String::from_utf8_lossy(&seg.argv[0]).to_string());
        for a in &seg.argv[1..] { cmd.arg(String::from_utf8_lossy(a).to_string()); }
        match in_src {
            Some(fd) if fd >= 0 => { let f = unsafe { std::fs::File::from_raw_fd(fd) }; cmd.stdin(std::process::Stdio::from(f)); }
            Some(_) => { cmd.stdin(std::process::Stdio::inherit()); }
            None if here.is_some() => { cmd.stdin(std::process::Stdio::piped()); }
            None => { cmd.stdin(std::process::Stdio::inherit()); }
        }
        match out_src {
            Some(fd) if fd >= 0 => { let f = unsafe { std::fs::File::from_raw_fd(fd) }; cmd.stdout(std::process::Stdio::from(f)); }
            Some(-2) => { cmd.stdout(std::process::Stdio::from(crate::cmdexec::dup_stderr_file())); }
            None => { cmd.stdout(std::process::Stdio::inherit()); }
            _ => {}
        }
        match err_src {
            Some(fd) if fd >= 0 => { let f = unsafe { std::fs::File::from_raw_fd(fd) }; cmd.stderr(std::process::Stdio::from(f)); }
            Some(_) => { cmd.stderr(std::process::Stdio::inherit()); }
            None => { cmd.stderr(std::process::Stdio::inherit()); }
        }
        match cmd.spawn() {
            Ok(c) => children.push(Some(c)),
            Err(e) => {
                let msg = e.to_string();
                for p in pipes.iter().flatten() { unsafe { c_close(p.0); c_close(p.1); } }
                return Res { statuses: vec![127], stdout: Vec::new(), stderr: Vec::new(), spawn_err: Some(msg) };
            }
        }
    }
    // write heredocs
    for (i, seg) in segs.iter().enumerate() {
        for (fd, act) in &seg.redirs {
            if let Act::Here(s) = act {
                if *fd == 0 {
                    if let Some(c) = children.get_mut(i).and_then(|c| c.as_mut()) {
                        if let Some(mut w) = c.stdin.take() {
                            use std::io::Write;
                            let _ = w.write_all(s);
                        }
                    }
                }
            }
        }
    }
    for p in pipes.iter().flatten() { unsafe { c_close(p.0); c_close(p.1); } }
    let mut stdout = Vec::new();
    let mut stderr = Vec::new();
    if let Some((r, w)) = cap_out { unsafe { c_close(w); } stdout = read_all(r); }
    if let Some((r, w)) = cap_err { unsafe { c_close(w); } stderr = read_all(r); }
    let mut statuses = Vec::new();
    for c in children.into_iter().flatten() {
        match c.wait() {
            Ok(st) => statuses.push(crate::cmdexec::status_of(&st)),
            Err(_) => statuses.push(-1),
        }
    }
    Res { statuses, stdout, stderr, spawn_err: None }
}

pub fn dup_stderr_file() -> std::fs::File {
    unsafe { std::fs::File::from_raw_fd(dup2(2, 2)); std::fs::File::from_raw_fd(dup_fd(2)) }
}
extern "C" { fn dup(fd: i32) -> i32; }
pub unsafe fn dup_fd(fd: i32) -> i32 { dup(fd) }

pub fn status_of(st: &std::process::ExitStatus) -> i64 {
    if let Some(c) = st.code() { return c as i64; }
    match signal_of(st) { Some(s) => 255 + s as i64, None => -1 }
}

pub fn signal_of(st: &std::process::ExitStatus) -> Option<i32> {
    use std::os::unix::process::ExitStatusExt;
    let raw = st.into_raw();
    if raw & 0xff == 0 { None } else { Some((raw & 0x7f) as i32) }
}
