use crate::ast::*;
use crate::value::*;
use crate::interp::*;
use crate::Pos;
use std::rc::Rc;
use std::os::unix::io::FromRawFd;
use std::process::Stdio;
use std::io::Write;

#[derive(Clone, Debug)]
pub enum Act { File(String, bool), Fd(u8), Here(Vec<u8>) }

#[derive(Clone, Debug)]
pub struct Seg { pub argv: Vec<Vec<u8>>, pub redirs: Vec<(u8, Act)>, pub pos: Pos }
#[derive(Clone, Debug)]
pub struct PlanCmd { pub segs: Vec<Seg>, pub pos: Pos }
pub struct Plan { pub cmds: Vec<PlanCmd> }

pub fn target_bytes(t: &Target, env: &Env) -> Vec<u8> {
    let mut s = Vec::new();
    for p in &t.parts {
        match p {
            WPart::Lit { value, .. } => s.extend_from_slice(value),
            WPart::Exp(_, slot) => {
                if *slot != usize::MAX {
                    let v = env.slots[*slot].borrow().clone();
                    s.extend_from_slice(&crate::value::to_bytes(&v));
                }
            }
        }
    }
    s
}

pub fn expand_words(w: &[Word], env: &Env) -> Result<Vec<Vec<u8>>, Panic> {
    let mut out = Vec::new();
    for wd in w {
        let mut s: Vec<u8> = Vec::new();
        let mut globbable = false;
        for p in &wd.parts {
            match p {
                WPart::Lit { value, quote, src } => {
                    let _ = src;
                    s.extend_from_slice(value);
                    if *quote == 0 && value.iter().any(|&b| b == b'*' || b == b'%') { globbable = true; }
                }
                WPart::Exp(_, slot) => {
                    if *slot != usize::MAX {
                        let v = env.slots[*slot].borrow().clone();
                        s.extend_from_slice(&crate::value::to_bytes(&v));
                    }
                }
            }
        }
        if globbable {
            let m = crate::globm::glob_dirs(&String::from_utf8_lossy(&s));
            if m.is_empty() { continue; }
            for x in m { out.push(x.into_bytes()); }
        } else { out.push(s); }
    }
    Ok(out)
}

pub fn build_plan(cb: &CmdBlock, env: &Env) -> Result<Plan, Panic> {
    let mut cmds = Vec::new();
    for cmd in &cb.cmds {
        let mut segs = Vec::new();
        for p in &cmd.pipes {
            for seg in &p.segs {
                let argv = expand_words(&seg.words, env)?;
                let mut redirs = Vec::new();
                for r in &seg.redirs {
                    match r {
                        Redirect::Out { fd, append, target } => {
                            if target.is_num { redirs.push((*fd, Act::Fd(target.num as u8))); }
                            else {
                                let path = String::from_utf8_lossy(&target_bytes(target, env)).to_string();
                                redirs.push((*fd, Act::File(path, *append)));
                            }
                        }
                        Redirect::In { target, here } => {
                            let t = String::from_utf8_lossy(&target_bytes(target, env)).to_string();
                            if *here { redirs.push((0, Act::Here(t.into_bytes()))); }
                            else { redirs.push((0, Act::File(t, false))); }
                        }
                    }
                }
                segs.push(Seg { argv, redirs, pos: seg.pos });
            }
        }
        let pos = segs.first().map(|s| s.pos).unwrap_or(NOPOS);
        cmds.push(PlanCmd { segs, pos });
    }
    Ok(Plan { cmds })
}

extern "C" { fn close(fd: i32) -> i32; fn pipe(fds: *mut i32) -> i32; fn dup(fd: i32) -> i32; fn read(fd: i32, buf: *mut u8, n: usize) -> isize; }

pub fn mk_pipe() -> Option<(i32, i32)> {
    let mut fds = [0i32; 2];
    if unsafe { pipe(fds.as_mut_ptr()) } != 0 { return None; }
    Some((fds[0], fds[1]))
}
pub unsafe fn c_close(fd: i32) { let _ = close(fd); }
pub unsafe fn c_dup(fd: i32) -> i32 { dup(fd) }

pub fn read_all(fd: i32) -> Vec<u8> {
    let mut out = Vec::new();
    let mut buf = [0u8; 8192];
    loop {
        let n = unsafe { read(fd, buf.as_mut_ptr(), 8192) };
        if n <= 0 { break; }
        out.extend_from_slice(&buf[..n as usize]);
    }
    out
}

pub struct Res { pub statuses: Vec<i64>, pub stdout: Vec<u8>, pub stderr: Vec<u8>, pub spawn_err: Option<String> }

pub fn run_pipeline(segs: &[Seg], capture: bool) -> Res {
    let n = segs.len();
    let mut pipes: Vec<Option<(i32, i32)>> = Vec::new();
    for _ in 0..n.saturating_sub(1) { pipes.push(mk_pipe()); }
    let cap_out = if capture { mk_pipe() } else { None };
    let cap_err = if capture { mk_pipe() } else { None };

    let mut children: Vec<Option<std::process::Child>> = Vec::new();
    let mut spawn_err: Option<String> = None;
    let mut open_fds: Vec<i32> = Vec::new();

    for (i, seg) in segs.iter().enumerate() {
        let mut in_src: Option<i32> = None;
        if i > 0 { if let Some((r, _)) = pipes[i - 1] { in_src = Some(r); open_fds.push(r); } }
        let mut out_src: Option<i32> = None;
        if i == n - 1 { if let Some((_, w)) = cap_out { out_src = Some(w); open_fds.push(w); } }
        else if let Some((_, w)) = pipes[i] { out_src = Some(w); open_fds.push(w); }
        let mut err_src: Option<i32> = None;
        if i == n - 1 { if let Some((_, w)) = cap_err { err_src = Some(w); open_fds.push(w); } }
        let mut here: Option<Vec<u8>> = None;
        for (fd, act) in &seg.redirs {
            match act {
                Act::File(p, app) => {
                    if *fd == 0 {
                        match std::fs::File::open(p) {
                            Ok(f) => { let r = f.as_raw_fd(); in_src = Some(r); std::mem::forget(f); open_fds.push(r); }
                            Err(e) => { spawn_err = Some(e.to_string()); }
                        }
                    } else {
                        match std::fs::OpenOptions::new().write(true).create(true).truncate(!*app).append(*app).open(p) {
                            Ok(f) => { let r = f.as_raw_fd(); if *fd == 1 { out_src = Some(r); } else { err_src = Some(r); } std::mem::forget(f); open_fds.push(r); }
                            Err(e) => { spawn_err = Some(e.to_string()); }
                        }
                    }
                }
                Act::Fd(t) => {
                    if *t == 0 { spawn_err = Some(format!("unsupported file descriptor ({})", t)); continue; }
                    if *t > 2 { spawn_err = Some(format!("unsupported file descriptor ({})", t)); continue; }
                    let src = match *t { 0 => in_src.unwrap_or(-0), 1 => out_src.unwrap_or(-1), _ => err_src.unwrap_or(-2) };
                    let base = if src < 0 { -src } else { src };
                    let nd = unsafe { c_dup(base) };
                    if *fd == 0 { in_src = Some(nd); } else if *fd == 1 { out_src = Some(nd); } else { err_src = Some(nd); }
                    open_fds.push(nd);
                }
                Act::Here(s) => { here = Some(s.clone()); }
            }
        }
        if let Some(e) = spawn_err.clone() {
            for f in open_fds.iter() { unsafe { c_close(*f); } }
            return Res { statuses: vec![127], stdout: Vec::new(), stderr: Vec::new(), spawn_err: Some(e) };
        }
        let mut cmd = std::process::Command::new(String::from_utf8_lossy(&seg.argv[0]).to_string());
        for a in &seg.argv[1..] { cmd.arg(String::from_utf8_lossy(a).to_string()); }
        // stdin
        if here.is_some() { cmd.stdin(Stdio::piped()); }
        else {
            match in_src {
                Some(fd) => { let d = unsafe { c_dup(fd) }; cmd.stdin(Stdio::from(std::fs::File::from_raw_fd(d))); }
                None => { cmd.stdin(Stdio::inherit()); }
            }
        }
        // stdout
        match out_src {
            Some(fd) => { let d = unsafe { c_dup(fd) }; cmd.stdout(Stdio::from(std::fs::File::from_raw_fd(d))); }
            None => { cmd.stdout(Stdio::inherit()); }
        }
        // stderr
        match err_src {
            Some(fd) => { let d = unsafe { c_dup(fd) }; cmd.stderr(Stdio::from(std::fs::File::from_raw_fd(d))); }
            None => { cmd.stderr(Stdio::inherit()); }
        }
        match cmd.spawn() {
            Ok(c) => children.push(Some(c)),
            Err(e) => {
                let msg = e.to_string();
                for f in open_fds.iter() { unsafe { c_close(*f); } }
                return Res { statuses: vec![127], stdout: Vec::new(), stderr: Vec::new(), spawn_err: Some(msg) };
            }
        }
    }
    // write heredocs
    for (i, seg) in segs.iter().enumerate() {
        for (fd, act) in &seg.redirs {
            if let Act::Here(s) = act {
                if *fd == 0 && here_is_piped(seg) {
                    if let Some(c) = children.get_mut(i).and_then(|c| c.as_mut()) {
                        if let Some(mut w) = c.stdin.take() { let _ = w.write_all(s); }
                    }
                }
            }
        }
    }
    // close parent copies
    for (r, w) in pipes.iter().flatten() { unsafe { c_close(*r); c_close(*w); } }
    let mut stdout = Vec::new();
    let mut stderr = Vec::new();
    if let Some((r, w)) = cap_out { unsafe { c_close(w); } stdout = read_all(r); unsafe { c_close(r); } }
    if let Some((r, w)) = cap_err { unsafe { c_close(w); } stderr = read_all(r); unsafe { c_close(r); } }
    let mut statuses = Vec::new();
    for c in children.into_iter().flatten() {
        match c.wait() {
            Ok(st) => statuses.push(crate::cmdexec::status_of(&st)),
            Err(_) => statuses.push(-1),
        }
    }
    Res { statuses, stdout, stderr, spawn_err: None }
}

fn here_is_piped(seg: &Seg) -> bool { true }

pub fn status_of(st: &std::process::ExitStatus) -> i64 {
    if let Some(c) = st.code() { return c as i64; }
    match signal_of(st) { Some(s) => 255 + s as i64, None => -1 }
}
pub fn signal_of(st: &std::process::ExitStatus) -> Option<i32> {
    use std::os::unix::process::ExitStatusExt;
    let raw = st.into_raw();
    if raw & 0xff == 0 { None } else { Some((raw & 0x7f) as i32) }
}
