}

pub fn expand_words(w: &[Word], env: &Env) -> Result<Vec<Vec<u8>>, Panic> {
    let mut out = Vec::new();
    for wd in w {
        let mut s: Vec<u8> = Vec::new();
        let mut globbable = false;
        for p in &wd.parts {
            match p {
                WPart::Lit { value, quote, src } => {
                    let _ = src;
                    s.extend_from_slice(value);
                    if *quote == 0 && value.iter().any(|&b| b == b'*' || b == b'%') { globbable = true; }
                }
                WPart::Exp(_, slot) => {
                    if *slot != usize::MAX {
                        let v = env.slots[*slot].borrow().clone();
                        s.extend_from_slice(&crate::value::to_bytes(&v));
                    }
                }
            }
        }
        if globbable {
            let m = crate::globm::glob_dirs(&String::from_utf8_lossy(&s));
            if m.is_empty() { continue; }
            for x in m { out.push(x.into_bytes()); }
        } else { out.push(s); }
    }
    Ok(out)
}

pub fn build_plan(cb: &CmdBlock, env: &Env) -> Result<Plan, Panic> {
    let mut cmds = Vec::new();
    for cmd in &cb.cmds {
        let mut segs = Vec::new();
        for p in &cmd.pipes {
            for seg in &p.segs {
                let argv = expand_words(&seg.words, env)?;
                let mut redirs = Vec::new();
                for r in &seg.redirs {
                    match r {
                        Redirect::Out { fd, append, target } => {
                            if target.is_num { redirs.push((*fd, Act::Fd(target.num as u8))); }
                            else {
                                let path = String::from_utf8_lossy(&target_bytes(target, env)).to_string();
                                redirs.push((*fd, Act::File(path, *append)));
                            }
                        }
                        Redirect::In { target, here } => {
                            let t = String::from_utf8_lossy(&target_bytes(target, env)).to_string();
                            if *here { redirs.push((0, Act::Here(t.into_bytes()))); }
                            else { redirs.push((0, Act::File(t, false))); }
                        }
                    }
                }
                segs.push(Seg { argv, redirs, pos: seg.pos });
            }
        }
        let pos = segs.first().map(|s| s.pos).unwrap_or(NOPOS);
        cmds.push(PlanCmd { segs, pos });
    }
