        }
    }

    pub fn make_job(&mut self, plan: crate::cmdexec::Plan, _cb: &CmdBlock, _env: &Env) -> Result<Value, Panic> {
        let job = Rc::new(JobVal { rx: std::sync::mpsc::channel().1, joined: std::cell::Cell::new(false) });
        let _ = &job;
        let joinf = Value::Func(Rc::new(FuncVal {
