// ------------- command block execution -------------
impl Interp {
    pub fn run_block(&mut self, cb: &CmdBlock, env: &Env, kind: BlockKind) -> Result<Value, Panic> {
        let plan = crate::cmdexec::build_plan(cb, env)?;
        match kind {
            BlockKind::Async => {
                let job = Rc::new(JobVal { plan, joined: std::cell::Cell::new(false) });
                let joinf = Value::Func(Rc::new(FuncVal {
                    name: "<command>.join".into(), pos: NOPOS, params: vec![], kinds: vec![SlotKind::Auto],
                    body: Block { stmts: vec![] }, captures: vec![], captured: vec![],
                    native: Some(crate::stdlib::job_join), this: None,
                }));
                let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
                m.insert(b"join".to_vec(), joinf);
                let _ = m;
                Ok(Value::Job(job))
            }
            BlockKind::Capture => {
                let mut sout = Vec::new();
                let mut serr = Vec::new();
                let mut first_err: Option<Rc<ErrVal>> = None;
                let mut multi: Vec<Value> = Vec::new();
                for cmd in &plan.cmds {
                    let res = crate::cmdexec::run_pipeline(&cmd.segs, true);
                    if let Some(e) = &res.spawn_err {
                        let ed = self.err_dict(res.statuses, cmd.pos, Value::Str(sout.clone()), Value::Str(serr.clone()));
                        return Ok(Value::Err(Rc::new(ErrVal { msg: e.clone().into_bytes(), typ: ed })));
                    }
                    sout.extend_from_slice(&res.stdout);
                    serr.extend_from_slice(&res.stderr);
                    let fails: Vec<usize> = res.statuses.iter().enumerate().filter(|(_, s)| **s != 0).map(|(i, _)| i).collect();
                    if fails.is_empty() { continue; }
                    let mut errs: Vec<Value> = Vec::new();
                    for i in &fails {
                        errs.push(Value::Err(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: self.err_dict(vec![res.statuses[*i]], cmd.segs[*i].pos, Value::Nil, Value::Nil) })));
                    }
                    if errs.len() == 1 { first_err = Some(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: errs[0].clone() })); }
                    else {
                        multi = errs;
                        first_err = Some(Rc::new(ErrVal { msg: b"Some commands failed in the pipeline".to_vec(), typ: Value::Arr(Rc::new(RefCell::new(multi.clone()))) }));
                    }
                    break;
                }
                match first_err {
                    None => Ok(Value::Dict(Rc::new(RefCell::new({
                        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
                        m.insert(b"stdout".to_vec(), Value::Str(sout));
                        m.insert(b"stderr".to_vec(), Value::Str(serr));
                        m
                    })))),
                    Some(ev) => {
                        let ed = {
                            let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
                            m.insert(b"stdout".to_vec(), Value::Str(sout));
                            m.insert(b"stderr".to_vec(), Value::Str(serr));
                            m.insert(b"error".to_vec(), Value::Err(ev.clone()));
                            Value::Dict(Rc::new(RefCell::new(m)))
                        };
                        Ok(Value::Err(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: ed })))
                    }
                }
            }
            BlockKind::Plain => {
                let mut err: Option<Value> = None;
                for cmd in &plan.cmds {
                    let res = crate::cmdexec::run_pipeline(&cmd.segs, false);
                    if let Some(e) = &res.spawn_err {
                        err = Some(Value::Err(Rc::new(ErrVal { msg: e.clone().into_bytes(), typ: self.err_dict(res.statuses.clone(), cmd.pos, Value::Nil, Value::Nil) })));
                        break;
                    }
                    let fails: Vec<usize> = res.statuses.iter().enumerate().filter(|(_, s)| **s != 0).map(|(i, _)| i).collect();
                    if fails.is_empty() { continue; }
                    if fails.len() == 1 {
                        err = Some(Value::Err(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: self.err_dict(vec![res.statuses[fails[0]]], cmd.segs[fails[0]].pos, Value::Nil, Value::Nil) })));
                    } else {
                        let errs: Vec<Value> = fails.iter().map(|i| Value::Err(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: self.err_dict(vec![res.statuses[*i]], cmd.segs[*i].pos, Value::Nil, Value::Nil) }))).collect();
                        err = Some(Value::Err(Rc::new(ErrVal { msg: b"Some commands failed in the pipeline".to_vec(), typ: Value::Arr(Rc::new(RefCell::new(errs))) })));
                    }
                    break;
                }
                Ok(err.unwrap_or(Value::Nil))
            }
        }
    }

    fn err_dict(&self, statuses: Vec<i64>, pos: Pos, _so: Value, _se: Value) -> Value {
        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
        m.insert(b"status".to_vec(), Value::Int(*statuses.last().unwrap_or(&0)));
        m.insert(b"pos".to_vec(), Value::Str(format!("{} (line {}, column {})", self.file, pos.line, pos.col).into_bytes()));
        Value::Dict(Rc::new(RefCell::new(m)))
    }
}
