macro_rules! need_str {
    ($it:expr, $v:expr, $pos:expr) => {
        match $v { Value::Str(s) => s.clone(), _ => return Err(arg_err(&$it.file, $pos, &$v, "string")) }
    };
}

pub fn type_(_it: &mut Interp, args: Vec<Value>, _this: Option<Value>) -> Result<Value, Panic> {
    Ok(Value::Str(type_name(&args[0]).as_bytes().to_vec()))
}
pub fn len(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    match &args[0] {
        Value::Str(s) => Ok(Value::Int(s.len() as i64)),
        Value::Arr(a) => Ok(Value::Int(a.borrow().len() as i64)),
        Value::Dict(d) => Ok(Value::Int(d.borrow().len() as i64)),
        _ => Err(arg_err(&it.file, NOPOS, &args[0], "string, array or dict")),
    }
}
pub fn is_empty(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    match &args[0] {
        Value::Str(s) => Ok(Value::Bool(s.is_empty())),
        Value::Arr(a) => Ok(Value::Bool(a.borrow().is_empty())),
        Value::Dict(d) => Ok(Value::Bool(d.borrow().is_empty())),
        _ => Err(arg_err(&it.file, NOPOS, &args[0], "string, array or dict")),
    }
}
pub fn to_string(_it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    Ok(Value::Str(crate::value::display(&args[0]).into_bytes()))
}
pub fn trim(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let s = need_str!(it, args[0], NOPOS);
    let txt = String::from_utf8_lossy(&s).to_string();
    Ok(Value::Str(txt.trim().as_bytes().to_vec()))
}
pub fn substr(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let s = need_str!(it, args[0], NOPOS);
    let (a, b) = match (&args[1], &args[2]) {
        (Value::Int(x), Value::Int(y)) => (*x, *y),
        _ => return Err(arg_err(&it.file, NOPOS, &args[1], "int")),
    };
    if a < 0 || b < 0 { return Ok(Value::Nil); }
    let start = a as usize;
    let end = start + b as usize;
    if end > s.len() { return Ok(Value::Nil); }
    Ok(Value::Str(s[start..end].to_vec()))
}
pub fn split(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let s = need_str!(it, args[0], NOPOS);
    let sep = need_str!(it, args[1], NOPOS);
    let st = String::from_utf8_lossy(&s).to_string();
    let sp = String::from_utf8_lossy(&sep).to_string();
    let parts: Vec<Value> = st.split(sp.as_str()).map(|p| Value::Str(p.as_bytes().to_vec())).collect();
    Ok(Value::Arr(Rc::new(RefCell::new(parts))))
}
pub fn replace(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let s = need_str!(it, args[0], NOPOS);
    let a = need_str!(it, args[1], NOPOS);
    let b = need_str!(it, args[2], NOPOS);
    let st = String::from_utf8_lossy(&s).to_string();
    let sa = String::from_utf8_lossy(&a).to_string();
    let sb = String::from_utf8_lossy(&b).to_string();
    Ok(Value::Str(st.replace(sa.as_str(), sb.as_str()).into_bytes()))
}
pub fn contains(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    match (&args[0], &args[1]) {
        (Value::Arr(a), v) => Ok(Value::Bool(a.borrow().iter().any(|x| crate::value::repr(x) == crate::value::repr(v)))),
        (Value::Str(s), Value::Char(c)) => Ok(Value::Bool(s.contains(c))),
        (Value::Str(_), other) => Err(arg_err(&it.file, NOPOS, other, "char")),
        (Value::Dict(d), v) => Ok(Value::Bool(d.borrow().values().any(|x| crate::value::repr(x) == crate::value::repr(v)))),
        _ => Err(arg_err(&it.file, NOPOS, &args[0], "string, array or dict")),
    }
}
pub fn bytes(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let s = need_str!(it, args[0], NOPOS);
    Ok(Value::Arr(Rc::new(RefCell::new(s.into_iter().map(Value::Char).collect()))))
}
pub fn int(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let v = &args[0];
    match v {
        Value::Int(i) => Ok(Value::Int(*i)),
        Value::Float(f) => Ok(Value::Int(*f as i64)),
        Value::Str(s) => {
            let t = String::from_utf8_lossy(s).to_string();
            match t.parse::<i64>() {
                Ok(i) => Ok(Value::Int(i)),
                Err(_) => Err(panic_here(&it.file, NOPOS, format!("invalid value ({}), expected valid integer", crate::value::repr(v)))),
            }
        }
        _ => Err(arg_err(&it.file, NOPOS, v, "int, float or string")),
    }
}
pub fn float(it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let v = &args[0];
    match v {
        Value::Int(i) => Ok(Value::Float(*i as f64)),
        Value::Float(f) => Ok(Value::Float(*f)),
        Value::Str(s) => {
            let t = String::from_utf8_lossy(s).to_string();
            match t.parse::<f64>() {
