pub fn range(_it: &mut Interp, args: Vec<Value>, _t: Option<Value>) -> Result<Value, Panic> {
    let isf = matches!(args[0], Value::Float(_)) || matches!(args[1], Value::Float(_)) || matches!(args[2], Value::Float(_));
    let (mut cur, end, step): (f64, f64, f64) = match (&args[0], &args[1], &args[2]) {
        (Value::Int(a), Value::Int(b), Value::Int(c)) => (*a as f64, *b as f64, *c as f64),
        _ => (0.0, 0.0, 0.0),
    };
    let ints = (!isf) && matches!(args[0], Value::Int(_)) && matches!(args[1], Value::Int(_)) && matches!(args[2], Value::Int(_));
    let st: Rc<RefCell<(f64, f64, f64, bool)>> = Rc::new(RefCell::new((cur, end, step, ints)));
    let sc = st.clone();
    let f = mkf("std.range<impl>", 0, Box::new(move |_it, _args, _this| {
        let (c, e, s, ints) = *sc.borrow();
        if s == 0.0 { let mut m: HashMap<Vec<u8>, Value> = HashMap::new(); m.insert(b"finished".to_vec(), Value::Bool(true)); return Ok(Value::Dict(Rc::new(RefCell::new(m)))); }
        if (s > 0.0 && c >= e) || (s < 0.0 && c <= e) {
            let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
            m.insert(b"finished".to_vec(), Value::Bool(true));
            return Ok(Value::Dict(Rc::new(RefCell::new(m))));
        }
        *sc.borrow_mut() = (c + s, e, s, ints);
        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
        if ints {
            m.insert(b"finished".to_vec(), Value::Bool(false));
            m.insert(b"value".to_vec(), Value::Int(c as i64));
        } else {
            m.insert(b"finished".to_vec(), Value::Bool(false));
            m.insert(b"value".to_vec(), Value::Float(c));
        }
        Ok(Value::Dict(Rc::new(RefCell::new(m))))
    }));
    Ok(f)
}

