use crate::value::*;
use std::rc::Rc;
use std::cell::RefCell;
use std::collections::HashMap;

pub fn encode(v: &Value, indent: usize) -> Result<String, Panic> {
    let pad = "  ".repeat(indent);
    let pad2 = "  ".repeat(indent + 1);
    match v {
        Value::Nil => Ok("null".into()),
        Value::Bool(b) => Ok(if *b { "true".into() } else { "false".into() }),
        Value::Int(i) => Ok(i.to_string()),
        Value::Float(f) => Ok(fmt_json_float(*f)),
        Value::Char(c) => Ok(json_str(&[*c])),
        Value::Str(s) => Ok(json_str(s)),
        Value::Arr(a) => {
            let items = a.borrow().clone();
            if items.is_empty() { return Ok("[]".into()); }
            let mut o = String::from("[\n");
            for (i, x) in items.iter().enumerate() {
                o.push_str(&pad2);
                o.push_str(&encode(x, indent + 1)?);
                if i + 1 < items.len() { o.push(','); }
                o.push('\n');
            }
            o.push_str(&pad);
            o.push(']');
            Ok(o)
        }
        Value::Dict(d) => {
            let items: Vec<(Vec<u8>, Value)> = d.borrow().iter().map(|(k, v)| (k.clone(), v.clone())).collect();
            if items.is_empty() { return Ok("{}".into()); }
            let mut o = String::from("{\n");
            for (i, (k, x)) in items.iter().enumerate() {
                o.push_str(&pad2);
                o.push_str(&json_str(k));
                o.push_str(": ");
                o.push_str(&encode(x, indent + 1)?);
                if i + 1 < items.len() { o.push(','); }
                o.push('\n');
            }
            o.push_str(&pad);
            o.push('}');
            Ok(o)
        }
        Value::Func(_) | Value::Err(_) | Value::Job(_) => Err(Panic { msg: format!("invalid value ({}), expected nil, bool, byte, int, float, string, array or dict", crate::value::repr(v)) }),
    }
}

pub fn fmt_json_float(f: f64) -> String {
    if f.is_nan() || f.is_infinite() { return "null".into(); }
    let s = format!("{:?}", f);
    s
}

pub fn json_str(s: &[u8]) -> String {
    let mut o = String::from("\"");
    for &c in s {
        match c {
            b'"' => o.push_str("\\\""),
            b'\\' => o.push_str("\\\\"),
            b'\n' => o.push_str("\\n"),
            b'\r' => o.push_str("\\r"),
            b'\t' => o.push_str("\\t"),
            0x00..=0x1f => o.push_str(&format!("\\u{:04x}", c)),
            _ => o.push(c as char),
        }
    }
    o.push('"');
    o
}

pub struct P<'a> { pub s: &'a [u8], pub i: usize, pub line: usize, pub col: usize }

impl<'a> P<'a> {
    fn bump(&mut self) -> u8 {
        let c = self.s[self.i];
        self.i += 1;
        if c == b'\n' { self.line += 1; self.col = 1; } else { self.col += 1; }
        c
    }
    fn ws(&mut self) {
        while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') { self.bump(); }
    }
    fn err(&self, msg: &str) -> String { format!("{} at line {} column {}", msg, self.line, self.col) }
    fn eof(&self) -> bool { self.i >= self.s.len() }

    pub fn parse(&mut self) -> Result<Value, String> {
        self.ws();
        if self.eof() { return Err(self.err("EOF while parsing a value")); }
        let c = self.s[self.i];
        match c {
            b'[' => self.parse_arr(),
            b'{' => self.parse_obj(),
            b'"' => { let s = self.parse_str()?; Ok(Value::Str(s)) }
            b't' | b'f' | b'n' => self.parse_kw(),
            _ => self.parse_num(),
        }
    }
    fn parse_arr(&mut self) -> Result<Value, String> {
        self.bump();
        let mut out = Vec::new();
        self.ws();
        if !self.eof() && self.s[self.i] == b']' { self.bump(); return Ok(Value::Arr(Rc::new(RefCell::new(out)))); }
        loop {
            self.ws();
            if self.eof() { return Err(self.err("EOF while parsing a list")); }
            out.push(self.parse()?);
            self.ws();
            if self.eof() { return Err(self.err("EOF while parsing a list")); }
            match self.s[self.i] {
                b',' => { self.bump(); }
                b']' => { self.bump(); return Ok(Value::Arr(Rc::new(RefCell::new(out)))); }
                _ => return Err(self.err("expected `,` or `]`")),
            }
        }
    }
    fn parse_obj(&mut self) -> Result<Value, String> {
        self.bump();
        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
        self.ws();
        if !self.eof() && self.s[self.i] == b'}' { self.bump(); return Ok(Value::Dict(Rc::new(RefCell::new(m)))); }
        loop {
            self.ws();
            if self.eof() { return Err(self.err("EOF while parsing an object")); }
            if self.s[self.i] != b'"' { return Err(self.err("key must be a string")); }
            let k = self.parse_str()?;
            self.ws();
            if self.eof() { return Err(self.err("EOF while parsing an object")); }
            if self.s[self.i] != b':' { return Err(self.err("expected `:`")); }
            self.bump();
            self.ws();
            let v = self.parse()?;
            m.insert(k, v);
            self.ws();
            if self.eof() { return Err(self.err("EOF while parsing an object")); }
            match self.s[self.i] {
                b',' => { self.bump(); }
                b'}' => { self.bump(); return Ok(Value::Dict(Rc::new(RefCell::new(m)))); }
                _ => return Err(self.err("expected `,` or `}`")),
            }
        }
    }
    fn parse_str(&mut self) -> Result<Vec<u8>, String> {
        self.bump();
        let mut out = Vec::new();
        loop {
            if self.eof() { return Err(self.err("EOF while parsing a string")); }
            let c = self.s[self.i];
            if c == b'"' { self.bump(); return Ok(out); }
            if c == b'\\' {
                self.bump();
                if self.eof() { return Err(self.err("EOF while parsing a string")); }
                let e = self.bump();
                match e {
                    b'n' => out.push(b'\n'),
                    b't' => out.push(b'\t'),
                    b'r' => out.push(b'\r'),
                    b'b' => out.push(8),
                    b'f' => out.push(12),
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'u' => {
                        let mut v = 0u32;
                        for _ in 0..4 {
                            if self.eof() { return Err(self.err("EOF while parsing a string")); }
                            let h = self.bump();
                            match h.to_digit(16) { Some(d) => v = v * 16 + d, None => return Err(self.err("invalid escape")) }
                        }
                        if let Some(ch) = char::from_u32(v) {
                            let mut b = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut b).as_bytes());
                        }
                    }
                    _ => return Err(self.err("invalid escape")),
                }
                continue;
            }
            out.push(self.bump());
        }
    }
    fn parse_num(&mut self) -> Result<Value, String> {
        let st = self.i;
        if !self.eof() && self.s[self.i] == b'-' { self.bump(); }
        while !self.eof() && self.s[self.i].is_ascii_digit() { self.bump(); }
        let mut isf = false;
        if !self.eof() && self.s[self.i] == b'.' { isf = true; self.bump(); while !self.eof() && self.s[self.i].is_ascii_digit() { self.bump(); } }
        if !self.eof() && (self.s[self.i] == b'e' || self.s[self.i] == b'E') { isf = true; self.bump(); if !self.eof() && (self.s[self.i] == b'+' || self.s[self.i] == b'-') { self.bump(); } while !self.eof() && self.s[self.i].is_ascii_digit() { self.bump(); } }
        let txt = String::from_utf8_lossy(&self.s[st..self.i]).to_string();
        if txt.is_empty() || txt == "-" { return Err(self.err("expected value")); }
        if isf { match txt.parse::<f64>() { Ok(f) => Ok(Value::Float(f)), Err(_) => Err(self.err("expected value")) } }
        else { match txt.parse::<i64>() { Ok(i) => Ok(Value::Int(i)), Err(_) => { let f: f64 = txt.parse().unwrap_or(0.0); Ok(Value::Float(f)) } } }
    }
    fn parse_kw(&mut self) -> Result<Value, String> {
        let st = self.i;
        while !self.eof() && self.s[self.i].is_ascii_alphabetic() { self.bump(); }
        let txt = String::from_utf8_lossy(&self.s[st..self.i]).to_string();
        match txt.as_str() {
            "true" => Ok(Value::Bool(true)),
            "false" => Ok(Value::Bool(false)),
            "null" => Ok(Value::Nil),
            _ => Err(self.err("expected value")),
        }
    }
}

pub fn decode(s: &[u8]) -> Result<Value, String> {
    let mut p = P { s, i: 0, line: 1, col: 1 };
    let v = p.parse()?;
    p.ws();
    if !p.eof() { return Err(p.err("trailing characters")); }
    Ok(v)
}
