// A small backtracking regex engine (subset of Rust's `regex` crate features).
#[derive(Clone, Debug)]
enum Node {
    Char(u8),
    Any,
    Class(Vec<(u8, u8)>, bool),
    Group(Vec<Vec<Node>>),
    Repeat(Box<Node>, usize, Option<usize>, bool),
    Start,
    End,
    Empty,
}

pub struct Regex { pub alts: Vec<Vec<Node>> }

pub fn compile(pat: &str) -> Regex {
    let b = pat.as_bytes();
    let alts = parse_alts(b, &mut 0, 0);
    Regex { alts }
}

fn parse_alts(b: &[u8], i: &mut usize, depth: usize) -> Vec<Vec<Node>> {
    let mut alts = Vec::new();
    let mut cur: Vec<Node> = Vec::new();
    while *i < b.len() {
        let c = b[*i];
        match c {
            b')' => { if depth > 0 { break; } else { cur.push(Node::Char(c)); *i += 1; } }
            b'|' => { *i += 1; alts.push(std::mem::take(&mut cur)); }
            b'(' => {
                *i += 1;
                if *i + 1 < b.len() && b[*i] == b'?' && b[*i + 1] == b':' { *i += 2; }
                let inner = parse_alts(b, i, depth + 1);
                if *i < b.len() && b[*i] == b')' { *i += 1; }
                let g = Node::Group(inner);
                let (node, ni) = parse_quant(g, b, *i);
                *i = ni;
                cur.push(node);
            }
            b'^' => { *i += 1; cur.push(Node::Start); }
            b'$' => { *i += 1; cur.push(Node::End); }
            b'[' => { let (n, ni) = parse_class(b, *i); *i = ni; let (nn, nj) = parse_quant(n, b, *i); *i = nj; cur.push(nn); }
            b'.' => { *i += 1; let (n, ni) = parse_quant(Node::Any, b, *i); *i = ni; cur.push(n); }
            b'\\' => {
                *i += 1;
                if *i >= b.len() { cur.push(Node::Char(b'\\')); break; }
                let e = b[*i];
                *i += 1;
                let n = match e {
                    b'd' => Node::Class(vec![(b'0', b'9')], false),
                    b'D' => Node::Class(vec![(b'0', b'9')], true),
                    b'w' => Node::Class(vec![(b'a', b'z'), (b'A', b'Z'), (b'0', b'9'), (b'_', b'_')], false),
                    b'W' => Node::Class(vec![(b'a', b'z'), (b'A', b'Z'), (b'0', b'9'), (b'_', b'_')], true),
                    b's' => Node::Class(vec![(b' ', b' '), (b'\t', b'\t'), (b'\n', b'\n'), (b'\r', b'\r')], false),
                    b'S' => Node::Class(vec![(b' ', b' '), (b'\t', b'\t'), (b'\n', b'\n'), (b'\r', b'\r')], true),
                    b'n' => Node::Char(b'\n'),
                    b't' => Node::Char(b'\t'),
                    b'r' => Node::Char(b'\r'),
                    b'0' => Node::Char(0),
                    other => Node::Char(other),
                };
                let (nn, ni) = parse_quant(n, b, *i);
                *i = ni;
                cur.push(nn);
            }
            b'*' | b'+' | b'?' => { *i += 1; }
            other => {
                *i += 1;
                let (n, ni) = parse_quant(Node::Char(other), b, *i);
                *i = ni;
                cur.push(n);
            }
        }
    }
    alts.push(cur);
    alts
}

fn parse_quant(node: Node, b: &[u8], i: usize) -> (Node, usize) {
    if i >= b.len() { return (node, i); }
    let mut j = i;
    match b[j] {
        b'*' => { j += 1; let greedy = if j < b.len() && b[j] == b'?' { j += 1; false } else { true }; (Node::Repeat(Box::new(node), 0, None, greedy), j) }
        b'+' => { j += 1; let greedy = if j < b.len() && b[j] == b'?' { j += 1; false } else { true }; (Node::Repeat(Box::new(node), 1, None, greedy), j) }
        b'?' => { j += 1; (Node::Repeat(Box::new(node), 0, Some(1), true), j) }
        b'{' => {
            let mut k = j + 1;
            let mut n1 = 0usize; let mut has1 = false;
            while k < b.len() && b[k].is_ascii_digit() { n1 = n1 * 10 + (b[k] - b'0') as usize; has1 = true; k += 1; }
            if !has1 { return (node, i); }
            let mut n2: Option<usize> = Some(n1);
            if k < b.len() && b[k] == b',' {
                k += 1;
                let mut n2v = 0usize; let mut has2 = false;
                while k < b.len() && b[k].is_ascii_digit() { n2v = n2v * 10 + (b[k] - b'0') as usize; has2 = true; k += 1; }
                n2 = if has2 { Some(n2v) } else { None };
            }
            if k >= b.len() || b[k] != b'}' { return (node, i); }
            k += 1;
            (Node::Repeat(Box::new(node), n1, n2, true), k)
        }
        _ => (node, i),
    }
}

fn parse_class(b: &[u8], start: usize) -> (Node, usize) {
    let mut i = start + 1;
    let mut neg = false;
    if i < b.len() && (b[i] == b'^') { neg = true; i += 1; }
    let mut ranges: Vec<(u8, u8)> = Vec::new();
    let mut first = true;
    while i < b.len() {
        if b[i] == b']' && !first { i += 1; break; }
        first = false;
        if b[i] == b'[' && i + 1 < b.len() && b[i + 1] == b':' {
            let mut k = i + 2;
            let mut name = String::new();
            while k + 1 < b.len() && !(b[k] == b':' && b[k + 1] == b']') { name.push(b[k] as char); k += 1; }
            k += 2;
            for r in posix_class(&name) { ranges.push(r); }
            i = k;
            continue;
        }
        let mut c = b[i];
        if c == b'\\' && i + 1 < b.len() { i += 1; c = match b[i] { b'n' => b'\n', b't' => b'\t', b'r' => b'\r', other => other }; i += 1; }
        else { i += 1; }
        if i < b.len() && b[i] == b'-' && i + 1 < b.len() && b[i + 1] != b']' {
            let hi = b[i + 1];
            ranges.push((c, hi));
            i += 2;
        } else { ranges.push((c, c)); }
    }
    (Node::Class(ranges, neg), i)
}

fn posix_class(name: &str) -> Vec<(u8, u8)> {
    match name {
        "digit" => vec![(b'0', b'9')],
        "alpha" => vec![(b'a', b'z'), (b'A', b'Z')],
        "alnum" => vec![(b'a', b'z'), (b'A', b'Z'), (b'0', b'9')],
        "upper" => vec![(b'A', b'Z')],
        "lower" => vec![(b'a', b'z')],
        "space" => vec![(b'\t', b'\r'), (b' ', b' ')],
        "blank" => vec![(b'\t', b'\t'), (b' ', b' ')],
        "punct" => vec![(b'!', b'/'), (b':', b'@'), (b'[', b'`'), (b'{', b'~')],
        "xdigit" => vec![(b'0', b'9'), (b'a', b'f'), (b'A', b'F')],
        "cntrl" => vec![(0, 0x1f), (0x7f, 0x7f)],
        "print" => vec![(0x20, 0x7e)],
        "graph" => vec![(0x21, 0x7e)],
        "word" => vec![(b'a', b'z'), (b'A', b'Z'), (b'0', b'9'), (b'_', b'_')],
        _ => vec![(0, 0)],
    }
}

fn class_match(ranges: &[(u8, u8)], neg: bool, c: u8) -> bool {
    let inside = ranges.iter().any(|(a, b)| c >= *a && c <= *b);
    inside != neg
}

impl Regex {
    pub fn is_match(&self, s: &str) -> bool {
        let b = s.as_bytes();
        for start in 0..=b.len() {
            for alt in &self.alts {
                if m(&alt, b, start, &mut |_| true) { return true; }
            }
        }
        false
    }
    pub fn find(&self, s: &str) -> Option<(usize, usize)> {
        let b = s.as_bytes();
        for start in 0..=b.len() {
            for alt in &self.alts {
                let mut end = None;
                if m(&alt, b, start, &mut |e| { end = Some(e); true }) {
                    if let Some(e) = end { return Some((start, e)); }
                }
            }
        }
        None
    }
    pub fn split(&self, s: &str) -> Vec<String> {
        let mut out = Vec::new();
        let mut last = 0usize;
        let b = s.as_bytes();
        let mut i = 0usize;
        while i <= b.len() {
            match self.find_at(b, i) {
                Some((a, e)) => {
                    out.push(s[last..a].to_string());
                    if e == a { if a < b.len() { i = a + 1; } else { break; } } else { i = e; }
                    last = e;
                }
                None => break,
            }
        }
        out.push(s[last.min(s.len())..].to_string());
        out
    }
    fn find_at(&self, b: &[u8], from: usize) -> Option<(usize, usize)> {
        for start in from..=b.len() {
            for alt in &self.alts {
                let mut end = None;
                if m(&alt, b, start, &mut |e| { end = Some(e); true }) {
                    if let Some(e) = end { return Some((start, e)); }
                }
            }
        }
        None
    }
    pub fn replace(&self, s: &str, rep: &str) -> String {
        let b = s.as_bytes();
        let mut out = String::new();
        let mut last = 0usize;
        let mut i = 0usize;
        while i <= b.len() {
            match self.find_at(b, i) {
                Some((a, e)) => {
                    out.push_str(&s[last..a]);
                    out.push_str(rep);
                    if e == a {
                        if a < b.len() { out.push(s[a..a + 1].chars().next().unwrap_or(' ')); i = a + 1; last = a + 1; }
                        else { break; }
                    } else { i = e; last = e; }
                }
                None => break,
            }
        }
        if last <= s.len() { out.push_str(&s[last..]); }
        out
    }
}

fn m(nodes: &[Node], s: &[u8], pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
    if nodes.is_empty() { return k(pos); }
    match &nodes[0] {
        Node::Empty => m(&nodes[1..], s, pos, k),
        Node::Char(c) => pos < s.len() && s[pos] == *c && m(&nodes[1..], s, pos + 1, k),
        Node::Any => pos < s.len() && s[pos] != b'\n' && m(&nodes[1..], s, pos + 1, k),
        Node::Class(r, neg) => pos < s.len() && class_match(r, *neg, s[pos]) && m(&nodes[1..], s, pos + 1, k),
        Node::Start => pos == 0 && m(&nodes[1..], s, pos, k),
        Node::End => pos == s.len() && m(&nodes[1..], s, pos, k),
        Node::Group(alts) => {
            for alt in alts {
                let mut kk = |p: usize| m(&nodes[1..], s, p, k);
                if m(alt, s, pos, &mut kk) { return true; }
            }
            false
        }
        Node::Repeat(inner, min, max, greedy) => {
            rep_match(inner, nodes, s, pos, 0, *min, *max, *greedy, k)
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn rep_match(inner: &[Node], rest: &[Node], s: &[u8], pos: usize, count: usize, min: usize, max: Option<usize>, greedy: bool, k: &mut dyn FnMut(usize) -> bool) -> bool {
    if count < min {
        return m(inner, s, pos, &mut |p| {
            if p == pos && count >= min { false } else { rep_match(inner, rest, s, p, count + 1, min, max, greedy, k) }
        });
    }
    if let Some(mx) = max { if count >= mx { return m(rest, s, pos, k); } }
    if greedy {
        if m(inner, s, pos, &mut |p| {
            if p == pos { false } else { rep_match(inner, rest, s, p, count + 1, min, max, greedy, k) }
        }) { return true; }
        m(rest, s, pos, k)
    } else {
        if m(rest, s, pos, k) { return true; }
        m(inner, s, pos, &mut |p| { if p == pos { false } else { rep_match(inner, rest, s, p, count + 1, min, max, greedy, k) } })
    }
}
