// glob for command blocks: pattern matched relative to the current directory, results prefixed with ./ when relative
pub fn match_word(pat: &[u8], name: &[u8]) -> bool {
    crate::glob::match_word(pat, name)
}

fn home_dir() -> String { std::env::var("HOME").unwrap_or_default() }

pub fn glob_dirs(pattern: &str) -> Vec<String> {
    // expand ~/
    let mut pat = pattern.to_string();
    if pat.starts_with("~/") { pat = format!("{}/{}", home_dir(), &pat[2..]); }
    let (dir, rest) = match pat.rfind('/') {
        Some(i) => (pat[..i].to_string(), pat[i + 1..].to_string()),
        None => (String::new(), pat.clone()),
    };
    let full_dir = if dir.is_empty() { ".".to_string() }
        else if dir.starts_with('/') { dir.clone() }
        else if dir.starts_with("./") { dir.clone() }
        else { format!("./{}", dir) };
    // multi-component patterns: walk
    let mut out = Vec::new();
    let comps: Vec<&str> = pat.split('/').collect();
    if comps.len() == 1 {
        if let Ok(rd) = std::fs::read_dir(&full_dir) {
            let mut names: Vec<String> = Vec::new();
            for e in rd.flatten() { names.push(e.file_name().to_string_lossy().to_string()); }
            names.sort();
            for n in names {
                if match_word(rest.as_bytes(), n.as_bytes()) {
                    out.push(if dir.is_empty() { format!("./{}", n) } else { format!("{}/{}", full_dir, n) });
                }
            }
        }
        return out;
    }
    // multi-component
    let comps_owned: Vec<Vec<u8>> = comps.iter().map(|c| c.as_bytes().to_vec()).collect();
    walk(std::path::Path::new(&full_dir), &comps_owned, &mut out, String::new());
    out.sort();
    out
}

fn walk(dir: &std::path::Path, comps: &[Vec<u8>], out: &mut Vec<String>, prefix: String) {
    if comps.is_empty() { return; }
    let cur = &comps[0];
    let is_recurse = cur.as_slice() == b"**";
    let is_last = comps.len() == 1;
    let mut entries: Vec<(String, bool)> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let n = e.file_name().to_string_lossy().to_string();
            let isd = e.file_type().map(|t| t.is_dir()).unwrap_or(false);
            entries.push((n, isd));
        }
    }
    entries.sort();
    for (n, isd) in entries {
        let path = if prefix.is_empty() { format!("./{}", n) } else { format!("{}/{}", prefix, n) };
        if is_recurse {
            if isd {
                let sub = dir.join(&n);
                if is_last { out.push(path.clone()); }
                walk(&sub, comps, out, path.clone());
            }
        } else if match_word(cur, n.as_bytes()) {
            if is_last { out.push(path.clone()); }
            else if isd {
                let sub = dir.join(&n);
                walk(&sub, &comps[1..], out, path);
            }
        }
    }
}
