mod ast; mod lexer; mod parser; mod printer; mod colors; mod value; mod interp; mod stdlib; mod cmdexec; mod glob; mod globm; mod json; mod regex;

pub const VERSION: &str = "Hush 0.1.4";
pub const AUTHOR: &str = "gahag <gabriel.s.b@live.com>";
pub const ABOUT: &str = "Hush is a unix shell scripting language based on the Lua programming language";

pub fn fmt_disp(v: f64) -> String { format!("{}", v) }

fn help_text() -> String {
    format!("{}\n{}\n{}\n\nUSAGE:\n    {} [FLAGS] [arguments]...\n\nFLAGS:\n        --ast        Print the AST\n        --check      Perform only static analysis instead of executing.\n    -h, --help       Prints help information\n        --lex        Print the lexemes\n        --program    Print the PROGAM\n    -V, --version    Prints version information\n\nARGS:\n    <arguments>...    Script and/or arguments\n", VERSION, AUTHOR, ABOUT, "executable")
}

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut lex_flag = false; let mut ast_flag = false; let mut prog_flag = false; let mut check_flag = false;
    let mut rest: Vec<String> = Vec::new();
    let mut bad: Option<String> = None;
    let mut i = 0;
    while i < argv.len() {
        let a = &argv[i];
        match a.as_str() {
            "--lex" => lex_flag = true,
            "--ast" => ast_flag = true,
            "--program" => prog_flag = true,
            "--check" => check_flag = true,
            "-h" | "--help" => { print!("{}", help_text()); return; }
            "-V" | "--version" => { println!("{}", VERSION); return; }
            _ => {
                if a.starts_with("--") || (a.starts_with('-') && a.len() > 1) {
                    bad = Some(a.clone());
                    i += 1;
                    break;
                }
                rest.push(a.clone());
            }
        }
        i += 1;
    }
    for x in &argv[i..] { rest.push(x.clone()); }
    if let Some(b) = bad {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", b);
        eprintln!("USAGE:\n    {} [FLAGS] [arguments]...\n", "executable");
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    let script = rest.first().cloned();
    let args: Vec<String> = if script.is_some() { rest[1..].to_vec() } else { rest.clone() };

    let c = colors::Cols::new(crate::interp::tty_out());
    let mut content: Option<Vec<u8>> = None;
    let mut fname: String = "<stdin>".to_string();
    match &script {
        Some(p) if p != "-" => {
            match std::fs::File::open(p) {
                Ok(_) => {
                    match std::fs::read(p) {
                        Ok(b) => { content = Some(b); fname = p.clone(); }
                        Err(e) => {
                            let mut s = String::new();
                            s.push_str(&c.red("Panic"));
                            s.push_str(" in ");
                            s.push_str(&c.green(p));
                            s.push_str(&format!(" (line 0, column 0): {}", e));
                            s.push('\n');
                            eprint!("{}", s);
                            std::process::exit(127);
                        }
                    }
                }
                Err(e) => {
                    if e.kind() == std::io::ErrorKind::PermissionDenied {
                        let mut s = String::new();
                        s.push_str(&c.red("Panic"));
                        s.push_str(" in ");
                        s.push_str(&c.green(p));
                        s.push_str(&format!(" (line 0, column 0): {}", e));
                        s.push('\n');
                        eprint!("{}", s);
                        std::process::exit(127);
                    }
                    content = None;
                }
            }
        }
        _ => {}
    }
    let src = match content {
        Some(b) => b,
        None => {
            let mut buf = Vec::new();
