    if lex_flag {
        let mut p = printer::Printer::new(&c, &fname, printer::Mode::Lex);
        p.print_tokens(&toks);
        print!("{}", p.out);
    }
    let mut pr = parser::Parser::new(toks);
    let (prog, kinds) = pr.parse_program();
    let mut all_errs: Vec<(usize, usize, String)> = Vec::new();
