            let mut p = printer::Printer::new(&c, &fname, printer::Mode::Ast);
            p.print_block(&ast::Block { stmts: prog.clone() }, 0, printer::Mode::Ast);
            print!("{}", p.out);
        }
        let _ = std::io::stdout().flush();
        for (l, co, m) in all_errs {
            let mut s = String::new();
            s.push_str(&c.red("Error"));
            s.push_str(": ");
            s.push_str(&c.green(&fname));
            s.push_str(&format!(" (line {}, column {}) - {}", l, co, m));
            s.push('\n');
            eprint!("{}", s);
