use crate::value::*;
use crate::ast::BinOp;
use crate::ast::Pos;
use crate::interp::Panic;

pub fn panic_here(file: &str, pos: Pos, msg: String) -> Panic {
    Panic { msg: format!("{} (line {}, column {}): {}", file, pos.line, pos.col, msg) }
}

pub fn eval(op: BinOp, x: &Value, y: &Value, p: Pos, pa: Pos, pb: Pos, file: &str) -> Result<Value, Panic> {
    match op {
        BinOp::Concat => {
            let a = crate::value::to_bytes(x);
            let b = crate::value::to_bytes(y);
            let mut o = a; o.extend_from_slice(&b);
            Ok(Value::Str(o))
        }
        _ => match (x, y) {
            (Value::Int(a), Value::Int(b)) => match op {
                BinOp::Plus => Ok(Value::Int(a.wrapping_add(*b))),
                BinOp::Minus => Ok(Value::Int(a.wrapping_sub(*b))),
                BinOp::Star => Ok(Value::Int(a.wrapping_mul(*b))),
                BinOp::Slash => if *b == 0 { Err(panic_here(file, p, "division by zero".into())) } else { Ok(Value::Int(a / b)) },
                BinOp::Percent => if *b == 0 { Err(panic_here(file, p, "division by zero".into())) } else { Ok(Value::Int(a % b)) },
                BinOp::Lt => Ok(Value::Bool(a < b)),
                BinOp::Gt => Ok(Value::Bool(a > b)),
                BinOp::Le => Ok(Value::Bool(a <= b)),
                BinOp::Ge => Ok(Value::Bool(a >= b)),
                BinOp::EqEq => Ok(Value::Bool(a == b)),
                BinOp::NotEq => Ok(Value::Bool(a != b)),
                _ => Ok(Value::Nil),
            },
            (Value::Float(a), Value::Float(b)) => match op {
                BinOp::Plus => Ok(Value::Float(a + b)),
                BinOp::Minus => Ok(Value::Float(a - b)),
                BinOp::Star => Ok(Value::Float(a * b)),
                BinOp::Slash => Ok(Value::Float(a / b)),
                BinOp::Percent => Ok(Value::Float(a % b)),
                BinOp::Lt => Ok(Value::Bool(a < b)),
                BinOp::Gt => Ok(Value::Bool(a > b)),
                BinOp::Le => Ok(Value::Bool(a <= b)),
                BinOp::Ge => Ok(Value::Bool(a >= b)),
                BinOp::EqEq => Ok(Value::Bool(a == b)),
                BinOp::NotEq => Ok(Value::Bool(a != b)),
                _ => Ok(Value::Nil),
            },
            (Value::Str(a), Value::Str(b)) => match op {
                BinOp::Lt => Ok(Value::Bool(a.as_slice() < b.as_slice())),
                BinOp::Gt => Ok(Value::Bool(a.as_slice() > b.as_slice())),
                BinOp::Le => Ok(Value::Bool(a.as_slice() <= b.as_slice())),
                BinOp::Ge => Ok(Value::Bool(a.as_slice() >= b.as_slice())),
                BinOp::EqEq => Ok(Value::Bool(a == b)),
                BinOp::NotEq => Ok(Value::Bool(a != b)),
                _ => Err(panic_here(file, pa, format!("value ({}) has unexpected type, expected int or float", crate::value::repr(x)))),
            },
            (Value::Char(a), Value::Char(b)) => match op {
                BinOp::Lt => Ok(Value::Bool(a < b)),
                BinOp::Gt => Ok(Value::Bool(a > b)),
                BinOp::Le => Ok(Value::Bool(a <= b)),
                BinOp::Ge => Ok(Value::Bool(a >= b)),
                BinOp::EqEq => Ok(Value::Bool(a == b)),
                BinOp::NotEq => Ok(Value::Bool(a != b)),
                _ => Err(panic_here(file, pa, format!("value ({}) has unexpected type, expected int or float", crate::value::repr(x)))),
            },
            _ => {
                if matches!(op, BinOp::EqEq) { return Ok(Value::Bool(crate::values_equal(x, y))); }
                if matches!(op, BinOp::NotEq) { return Ok(Value::Bool(!crate::values_equal(x, y))); }
                match x {
                    Value::Int(_) => Err(panic_here(file, pb, format!("value ({}) has unexpected type, expected int", crate::value::repr(y)))),
                    Value::Float(_) => Err(panic_here(file, pb, format!("value ({}) has unexpected type, expected float", crate::value::repr(y)))),
                    Value::Str(_) => Err(panic_here(file, pb, format!("value ({}) has unexpected type, expected string", crate::value::repr(y)))),
                    Value::Char(_) => Err(panic_here(file, pb, format!("value ({}) has unexpected type, expected char", crate::value::repr(y)))),
                    _ => Err(panic_here(file, pa, format!("value ({}) has unexpected type, expected int, float, byte or string", crate::value::repr(x)))),
                }
            }
        },
    }
}
