use crate::ast::*;
use crate::value::*;
use crate::ast::Pos;
use std::rc::Rc;
use std::cell::RefCell;
use std::collections::HashMap;
use std::io::Write;

pub enum Flow { Val(Value), Ret(Value), Try(Value), Brk }
impl Flow { pub fn as_value(self) -> Result<Value, Panic> { match self { Flow::Val(v) => Ok(v), Flow::Ret(v) => Ok(v), Flow::Try(v) => Ok(v), Flow::Brk => Ok(Value::Nil) } } }

pub struct Env { pub slots: Vec<SlotCell> }

pub struct Interp {
    pub file: String,
    pub globals: Vec<SlotCell>,
    pub modules: HashMap<String, Value>,
    pub exit: Option<i32>,
    pub rng: u64,
    pub args: Vec<String>,
}

fn mkcell(v: Value) -> SlotCell { Rc::new(RefCell::new(v)) }

pub fn panic_here(file: &str, pos: Pos, msg: String) -> Panic {
    Panic { msg: format!("{} (line {}, column {}): {}", file, pos.line, pos.col, msg) }
}
pub fn panic_top(file: &str, msg: String) -> Panic {
    Panic { msg: format!("{} (line 0, column 0): {}", file, msg) }
}
pub fn type_err(file: &str, pos: Pos, v: &Value, exp: &str) -> Panic {
    panic_here(file, pos, format!("value ({}) has unexpected type, expected {}", crate::value::repr(v), exp))
}

pub fn values_equal(x: &Value, y: &Value) -> bool {
    match (x, y) {
        (Value::Arr(a), Value::Arr(b)) => {
            let av = a.borrow().clone(); let bv = b.borrow().clone();
            av.len() == bv.len() && av.iter().zip(bv.iter()).all(|(p, q)| values_equal(p, q))
        }
        (Value::Dict(a), Value::Dict(b)) => {
            let ad = a.borrow().clone(); let bd = b.borrow().clone();
            ad.len() == bd.len() && ad.iter().all(|(k, v)| bd.get(k).map(|w| values_equal(v, w)).unwrap_or(false))
        }
        (Value::Err(a), Value::Err(b)) => a.msg == b.msg && values_equal(&a.typ, &b.typ),
        _ => crate::value::repr(x) == crate::value::repr(y),
    }
}

pub fn expr_pos(e: &Expr) -> Pos {
    match e {
        Expr::Nil(p) | Expr::Bool(_, p) | Expr::Int(_, p) | Expr::Float(_, p) | Expr::Char(_, p)
        | Expr::Str(_, p) | Expr::Array(_, p) | Expr::Dict(_, p) | Expr::Call(_, _, p)
        | Expr::Index(_, _, p) | Expr::Member(_, _, p) | Expr::Unary(_, _, p)
        | Expr::Try(_, p) | Expr::If(_, _, _, p) | Expr::Func(_, p) | Expr::Cmd(_, p)
        | Expr::Self_(p, _) => *p,
        Expr::Var(_, p, _) => *p,
        Expr::Binary(_, _, _, _) => NOPOS,
    }
}

pub fn tty_out() -> bool { unsafe { isatty(1) == 1 } }
extern "C" { fn isatty(fd: i32) -> i32; }

impl Interp {
    pub fn new(file: &str, globals: Vec<SlotCell>) -> Self {
        Interp { file: file.to_string(), globals, modules: HashMap::new(), exit: None, rng: 0, args: Vec::new() }
    }

    pub fn run_program(&mut self, prog: &Block, kinds: &[SlotKind], std_val: Value) -> Value {
        let env = Env { slots: (0..kinds.len()).map(|_| mkcell(Value::Nil)).collect() };
        self.std_init(&env, std_val);
        let res = self.eval_block(prog, &env);
        match res { Flow::Val(v) | Flow::Try(v) | Flow::Ret(v) => v, Flow::Brk => Value::Nil }
    }

    fn std_init(&mut self, env: &Env, std_val: Value) {
        if let Some(s) = env.slots.first() { *s.borrow_mut() = std_val; }
        crate::stdlib::install(env);
    }

    pub fn run_module(&mut self, prog: &Block, kinds: &[SlotKind]) -> Result<Value, Panic> {
        let env = Env { slots: (0..kinds.len()).map(|_| mkcell(Value::Nil)).collect() };
        crate::stdlib::install(&env);
        match self.eval_block(prog, &env) {
            Flow::Val(v) | Flow::Try(v) | Flow::Ret(v) => Ok(v),
            Flow::Brk => Ok(Value::Nil),
        }
    }

    pub fn report_panic(&self, p: &Panic) {
        let c = crate::colors::Cols::new(tty_out());
        let mut s = String::new();
        s.push_str(&c.red("Panic"));
        s.push_str(" in ");
        s.push_str(&c.green(&self.file));
        s.push_str(": ");
        s.push_str(&p.msg);
        s.push('\n');
        let _ = std::io::stdout().flush();
        eprint!("{}", s);
    }

    pub fn eval_block(&mut self, b: &Block, env: &Env) -> Flow {
        let mut last = Flow::Val(Value::Nil);
        for st in &b.stmts {
            match self.eval_stmt(st, env) {
                Ok(Flow::Ret(v)) => { last = Flow::Ret(v); break; }
                Ok(Flow::Brk) => { last = Flow::Brk; break; }
                Ok(Flow::Try(v)) => { last = Flow::Try(v); break; }
                Ok(Flow::Val(v)) => { last = Flow::Val(v); }
                Err(p) => { self.report_panic(&p); return Flow::Val(Value::Nil); }
            }
        }
        last
    }

    fn eval_stmt(&mut self, st: &Stmt, env: &Env) -> Result<Flow, Panic> {
        match st {
            Stmt::Let(_, slot, e, _) => {
                let v = self.eval(e, env)?;
                *env.slots[*slot].borrow_mut() = v;
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Assign(t, v, _) => {
                let val = self.eval(v, env)?;
                self.assign_lvalue(t, val, env)?;
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Expr(e, _) => { let v = self.eval(e, env)?; Ok(Flow::Val(v)) }
            Stmt::If { cond, then, els, .. } => {
                let c = self.eval(cond, env)?;
                match c {
                    Value::Bool(true) => Ok(self.eval_block(then, env)),
                    Value::Bool(false) => {
                        if let Some(eb) = els { Ok(self.eval_block(eb, env)) } else { Ok(Flow::Val(Value::Nil)) }
                    }
                    _ => Err(panic_here(&self.file, crate::expr_pos(cond), format!("condition ({}) is not a boolean", crate::value::repr(&c)))),
                }
            }
            Stmt::While { cond, body, .. } => {
                loop {
                    let c = self.eval(cond, env)?;
                    match c {
                        Value::Bool(false) => break,
                        Value::Bool(true) => {
                            match self.eval_block(body, env) {
                                Flow::Brk => break,
                                Flow::Ret(v) => return Ok(Flow::Ret(v)),
                                Flow::Try(v) => return Ok(Flow::Try(v)),
                                _ => {}
                            }
                        }
                        _ => return Err(panic_here(&self.file, crate::expr_pos(cond), format!("condition ({}) is not a boolean", crate::value::repr(&c)))),
                    }
                }
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::For { slot, iter, body, .. } => {
                let f = self.eval(iter, env)?;
                let fun = match &f { Value::Func(x) => x.clone(), _ => return Err(panic_here(&self.file, crate::expr_pos(iter), format!("attempt to call ({}), which is not a function", crate::value::repr(&f)))) };
                loop {
                    let r = self.call_fn(&fun, vec![], None)?;
                    match r {
                        Value::Dict(d) => {
                            let (finished, val) = {
                                let bd = d.borrow();
                                let fin = match bd.get(b"finished") {
                                    Some(Value::Bool(b)) => *b,
                                    _ => return Err(panic_top(&self.file, "iteration has no 'finished' field".into())),
                                };
                                let v = bd.get(b"value").cloned().unwrap_or(Value::Nil);
                                (fin, v)
                            };
                            if finished { break; }
                            *env.slots[*slot].borrow_mut() = val;
                            match self.eval_block(body, env) {
                                Flow::Brk => break,
                                Flow::Ret(v) => return Ok(Flow::Ret(v)),
                                Flow::Try(v) => return Ok(Flow::Try(v)),
                                _ => {}
                            }
                        }
                        _ => return Err(panic_top(&self.file, "iteration has no 'finished' field".into())),
                    }
                }
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Return(e, _) => { let v = self.eval(e, env)?; Ok(Flow::Ret(v)) }
            Stmt::Break(_) => Ok(Flow::Brk),
            Stmt::Cmd(cb, _) => {
                let _ = self.run_block(cb, env, BlockKind::Plain)?;
                Ok(Flow::Val(Value::Nil))
            }
            Stmt::Func(_, slot, f, _) => {
                let fv = self.make_closure(f, env)?;
                *env.slots[*slot].borrow_mut() = fv;
                Ok(Flow::Val(Value::Nil))
            }
        }
    }

    // ---------------- expressions ----------------
    pub fn eval(&mut self, e: &Expr, env: &Env) -> Result<Value, Panic> {
        match e {
            Expr::Nil(_) => Ok(Value::Nil),
            Expr::Bool(b, _) => Ok(Value::Bool(*b)),
            Expr::Int(v, _) => Ok(Value::Int(*v)),
            Expr::Float(v, _) => Ok(Value::Float(*v)),
            Expr::Char(v, _) => Ok(Value::Char(*v)),
            Expr::Str(v, _) => Ok(Value::Str(v.clone())),
            Expr::Var(_, _, slot) => {
                if *slot == usize::MAX { return Err(panic_top(&self.file, "undeclared variable".into())); }
                Ok(env.slots[*slot].borrow().clone())
            }
            Expr::Self_(_, slot) => {
                if *slot == usize::MAX { return Err(panic_top(&self.file, "self keyword outside function".into())); }
                Ok(env.slots[*slot].borrow().clone())
            }
            Expr::Array(items, _) => {
                let mut out = Vec::new();
                for it in items { out.push(self.eval(it, env)?); }
                Ok(Value::Arr(Rc::new(RefCell::new(out))))
            }
            Expr::Dict(items, _) => {
                let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
                for (k, v) in items {
                    if let Expr::Var(name, _, _) = k { let vv = self.eval(v, env)?; m.insert(name.clone(), vv); }
                }
                Ok(Value::Dict(Rc::new(RefCell::new(m))))
            }
            Expr::Call(f, args, p) => {
                let fv = self.eval(f, env)?;
                let mut av = Vec::new();
                for a in args { av.push(self.eval(a, env)?); }
                match &fv {
                    Value::Func(x) => {
                        let th = match f.as_ref() {
                            Expr::Member(o, _, _) | Expr::Index(o, _, _) => Some(self.eval(o, env)?),
                            _ => None,
                        };
                        let th = match th { Some(t) => t, None => x.this.clone() };
                        Ok(self.call_fn(x, av, th)?)
                    }
                    _ => Err(panic_here(&self.file, *p, format!("attempt to call ({}), which is not a function", crate::value::repr(&fv)))),
                }
            }
            Expr::Index(o, i, _) => {
                let ov = self.eval(o, env)?;
                let iv = self.eval(i, env)?;
                self.index(&ov, &iv, crate::expr_pos(i))
            }
            Expr::Member(o, k, p) => {
                let ov = self.eval(o, env)?;
                self.index(&ov, &Value::Str(k.clone()), *p)
            }
            Expr::Unary(op, v, p) => {
                let x = self.eval(v, env)?;
                match op {
                    UnOp::Not => match x {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        _ => Err(type_err(&self.file, *p, &x, "bool")),
                    },
                    UnOp::Neg => match x {
                        Value::Int(i) => Ok(Value::Int(-i)),
                        Value::Float(f) => Ok(Value::Float(-f)),
                        _ => Err(type_err(&self.file, *p, &x, "int or float")),
                    },
                }
            }
            Expr::Binary(op, a, b, p) => {
                match op {
                    BinOp::And => {
                        let x = self.eval(a, env)?;
                        let xb = match x { Value::Bool(b) => b, _ => return Err(type_err(&self.file, crate::expr_pos(a), &x, "bool")) };
                        if !xb { return Ok(Value::Bool(false)); }
                        let y = self.eval(b, env)?;
                        match y {
                            Value::Bool(b2) => Ok(Value::Bool(b2)),
                            _ => Err(type_err(&self.file, crate::expr_pos(b), &y, "bool")),
                        }
                    }
                    BinOp::Or => {
                        let x = self.eval(a, env)?;
                        let xb = match x { Value::Bool(b) => b, _ => return Err(type_err(&self.file, crate::expr_pos(a), &x, "bool")) };
                        if xb { return Ok(Value::Bool(true)); }
                        let y = self.eval(b, env)?;
                        match y {
                            Value::Bool(b2) => Ok(Value::Bool(b2)),
                            _ => Err(type_err(&self.file, crate::expr_pos(b), &y, "bool")),
                        }
                    }
                    _ => {
                        let x = self.eval(a, env)?;
                        let y = self.eval(b, env)?;
                        crate::binop::eval(*op, &x, &y, *p, crate::expr_pos(a), crate::expr_pos(b), &self.file)
                    }
                }
            }
            Expr::Try(v, _) => {
                let x = self.eval(v, env)?;
                match x {
                    Value::Err(ev) => Ok(Value::Err(ev)),
                    other => Ok(other),
                }
            }
            Expr::If(cond, then, els, _) => {
                let c = self.eval(cond, env)?;
                match c {
                    Value::Bool(true) => self.eval_block(then, env).as_value(),
                    Value::Bool(false) => {
                        if let Some(eb) = els { self.eval_block(eb, env).as_value() } else { Ok(Value::Nil) }
                    }
                    _ => Err(panic_here(&self.file, crate::expr_pos(cond), format!("condition ({}) is not a boolean", crate::value::repr(&c)))),
                }
            }
            Expr::Func(f, _) => self.make_closure(f, env),
            Expr::Cmd(cb, _) => {
                match cb.kind {
                    BlockKind::Capture => self.run_block(cb, env, BlockKind::Capture),
                    BlockKind::Async => self.run_block(cb, env, BlockKind::Async),
                    BlockKind::Plain => self.run_block(cb, env, BlockKind::Plain),
                }
            }
        }
    }

    pub fn call_fn(&mut self, f: &Rc<FuncVal>, mut args: Vec<Value>, this: Option<Value>) -> Result<Value, Panic> {
        if let Some(n) = &f.native {
            let mut nn = crate::stdlib::rebox(n);
            if !f.variadic && args.len() != f.params.len() {
                return Err(panic_top(&self.file, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), f.params.len())));
            }
            let th = if this.is_some() { this.clone() } else { f.this.clone() };
            return nn(self, args, th);
        }
        if args.len() != f.params.len() {
            return Err(panic_top(&self.file, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), f.params.len())));
        }
        let mut slots: Vec<SlotCell> = Vec::with_capacity(f.kinds.len());
        for k in &f.kinds {
            match k {
                SlotKind::Auto => slots.push(mkcell(Value::Nil)),
                SlotKind::Self_ => slots.push(mkcell(this.clone().unwrap_or(Value::Nil))),
                SlotKind::Capture(ps) => {
                    let cell = f.captured.iter().find(|(idx, _)| *idx == *ps).map(|(_, c)| c.clone());
                    match cell { Some(c) => slots.push(c), None => slots.push(mkcell(Value::Nil)) }
                }
            }
        }
        for (j, a) in args.into_iter().enumerate() { *slots[j].borrow_mut() = a; }
        let env = Env { slots };
        match self.eval_block(&f.body, &env) {
            Flow::Val(v) | Flow::Ret(v) | Flow::Try(v) => Ok(v),
            Flow::Brk => Ok(Value::Nil),
        }
    }

    fn make_closure(&mut self, f: &FuncLit, env: &Env) -> Result<Value, Panic> {
        let mut captures = Vec::new();
        let mut captured = Vec::new();
        for (i, k) in f.kinds.iter().enumerate() {
            if let SlotKind::Capture(ps) = k {
                captures.push(i);
                captured.push((*ps, env.slots[*ps].clone()));
            }
        }
        Ok(Value::Func(Rc::new(FuncVal {
            name: String::new(), pos: f.pos, params: f.params.clone(), kinds: f.kinds.clone(),
            body: f.body.clone(), captures, captured, native: None, this: None, variadic: false,
        })))
    }

    pub fn index(&mut self, ov: &Value, iv: &Value, ipos: Pos) -> Result<Value, Panic> {
        let file = self.file.clone();
        match ov {
            Value::Dict(d) => {
                let k = match iv { Value::Str(s) => s.clone(), _ => return Err(type_err(&file, ipos, iv, "string")) };
                match d.borrow().get(&k) { Some(v) => Ok(v.clone()), None => Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))) }
            }
            Value::Arr(a) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(type_err(&file, ipos, iv, "int")) };
                let av = a.borrow();
                if i < 0 || (i as usize) >= av.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                Ok(av[i as usize].clone())
            }
            Value::Str(s) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(type_err(&file, ipos, iv, "int")) };
                if i < 0 || (i as usize) >= s.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                Ok(Value::Char(s[i as usize]))
            }
            Value::Err(_) => Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))),
            _ => Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected string, array, dict or error", crate::value::repr(ov)))),
        }
    }

    pub fn assign_lvalue(&mut self, t: &Expr, v: Value, env: &Env) -> Result<(), Panic> {
        let file = self.file.clone();
        match t {
            Expr::Var(_, _, slot) => { *env.slots[*slot].borrow_mut() = v; Ok(()) }
            Expr::Self_(_, slot) => { *env.slots[*slot].borrow_mut() = v; Ok(()) }
            Expr::Member(o, k, p) => {
                let ov = self.eval(o, env)?;
                self.set_index(&ov, &Value::Str(k.clone()), v, *p)
            }
            Expr::Index(o, i, p) => {
                let ov = self.eval(o, env)?;
                let iv = self.eval(i, env)?;
                self.set_index(&ov, &iv, v, *p)
            }
            _ => Err(panic_here(&file, NOPOS, "invalid assignment".into())),
        }
    }

    fn set_index(&mut self, ov: &Value, iv: &Value, v: Value, ipos: Pos) -> Result<(), Panic> {
        let file = self.file.clone();
        match ov {
            Value::Dict(d) => {
                let k = match iv { Value::Str(s) => s.clone(), _ => return Err(type_err(&file, ipos, iv, "string")) };
                d.borrow_mut().insert(k, v);
                Ok(())
            }
            Value::Arr(a) => {
                let i = match iv { Value::Int(i) => *i, _ => return Err(type_err(&file, ipos, iv, "int")) };
                let mut av = a.borrow_mut();
                if i < 0 || (i as usize) >= av.len() { return Err(panic_here(&file, ipos, format!("index ({}) out of bounds", crate::value::repr(iv)))); }
                av[i as usize] = v;
                Ok(())
            }
            Value::Err(_) => Ok(()),
            _ => Err(panic_here(&file, ipos, format!("value ({}) has unexpected type, expected array, dict or error", crate::value::repr(ov)))),
        }
    }

    // ------------- command block execution -------------
    pub fn run_block(&mut self, cb: &CmdBlock, env: &Env, kind: BlockKind) -> Result<Value, Panic> {
        let plan = crate::cmdexec::build_plan(cb, env)?;
        match kind {
            BlockKind::Async => {
                let job = Rc::new(JobVal { plan, joined: std::cell::Cell::new(false) });
                let joinf = crate::stdlib::mkf("<command>.join", 0, Box::new(crate::stdlib::job_join), None);
                let _ = joinf;
                Ok(Value::Job(job))
            }
            BlockKind::Capture => {
                let mut sout = Vec::new();
                let mut serr = Vec::new();
                let mut err: Option<Rc<ErrVal>> = None;
                for cmd in &plan.cmds {
                    let res = crate::cmdexec::run_pipeline(&cmd.segs, true);
                    if let Some(e) = &res.spawn_err {
                        let ed = self.err_dict(res.statuses.clone(), cmd.pos);
                        return Ok(Value::Err(Rc::new(ErrVal { msg: e.clone().into_bytes(), typ: ed })));
                    }
                    sout.extend_from_slice(&res.stdout);
                    serr.extend_from_slice(&res.stderr);
                    let fails: Vec<usize> = res.statuses.iter().enumerate().filter(|(_, s)| **s != 0).map(|(i, _)| i).collect();
                    if fails.is_empty() { continue; }
                    let inner: Vec<Value> = fails.iter().map(|i| self.cmd_err(res.statuses[*i], cmd.segs[*i].pos)).collect();
                    if inner.len() == 1 {
                        err = Some(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: Value::Err(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: inner[0].clone() }))) });
                    } else {
                        err = Some(Rc::new(ErrVal { msg: b"Some commands failed in the pipeline".to_vec(), typ: Value::Arr(Rc::new(RefCell::new(inner))) }));
                    }
                    break;
                }
                match err {
                    None => {
                        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
                        m.insert(b"stdout".to_vec(), Value::Str(sout));
                        m.insert(b"stderr".to_vec(), Value::Str(serr));
                        Ok(Value::Dict(Rc::new(RefCell::new(m))))
                    }
                    Some(ev) => {
                        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
                        m.insert(b"stdout".to_vec(), Value::Str(sout));
                        m.insert(b"stderr".to_vec(), Value::Str(serr));
                        m.insert(b"error".to_vec(), Value::Err(ev.clone()));
                        Ok(Value::Err(Rc::new(ErrVal { msg: ev.msg.clone(), typ: Value::Dict(Rc::new(RefCell::new(m))) })))
                    }
                }
            }
            BlockKind::Plain => {
                let mut err: Option<Value> = None;
                for cmd in &plan.cmds {
                    let res = crate::cmdexec::run_pipeline(&cmd.segs, false);
                    if let Some(e) = &res.spawn_err {
                        err = Some(Value::Err(Rc::new(ErrVal { msg: e.clone().into_bytes(), typ: self.err_dict(res.statuses.clone(), cmd.pos) })));
                        break;
                    }
                    let fails: Vec<usize> = res.statuses.iter().enumerate().filter(|(_, s)| **s != 0).map(|(i, _)| i).collect();
                    if fails.is_empty() { continue; }
                    if fails.len() == 1 {
                        err = Some(self.cmd_err(res.statuses[fails[0]], cmd.segs[fails[0]].pos));
                    } else {
                        let inner: Vec<Value> = fails.iter().map(|i| self.cmd_err(res.statuses[*i], cmd.segs[*i].pos)).collect();
                        err = Some(Value::Err(Rc::new(ErrVal { msg: b"Some commands failed in the pipeline".to_vec(), typ: Value::Arr(Rc::new(RefCell::new(inner))) })));
                    }
                    break;
                }
                Ok(err.unwrap_or(Value::Nil))
            }
        }
    }

    pub fn cmd_err(&self, status: i64, pos: Pos) -> Value {
        Value::Err(Rc::new(ErrVal { msg: b"command returned non-zero".to_vec(), typ: self.err_dict(vec![status], pos) }))
    }

    pub fn err_dict(&self, statuses: Vec<i64>, pos: Pos) -> Value {
        let mut m: HashMap<Vec<u8>, Value> = HashMap::new();
        m.insert(b"status".to_vec(), Value::Int(*statuses.last().unwrap_or(&0)));
        m.insert(b"pos".to_vec(), Value::Str(format!("{} (line {}, column {})", self.file, pos.line, pos.col).into_bytes()));
        Value::Dict(Rc::new(RefCell::new(m)))
    }

    pub fn module_compile(&mut self, name: &str, content: &[u8]) -> Result<(Block, Vec<SlotKind>), Panic> {
        let mut lx = crate::lexer::Lexer::new(content);
        let toks = lx.lex();
        let mut errs: Vec<String> = Vec::new();
        for e in lx.errors { errs.push(format!("{} (line {}, column {}) - {}", name, e.line, e.col, e.msg)); }
        let mut pr = crate::parser::Parser::new(toks);
        let (prog, kinds) = pr.parse_program();
        for e in pr.errors { errs.push(format!("{} (line {}, column {}) - {}", name, e.line, e.col, e.msg)); }
        if !errs.is_empty() {
            let _ = std::io::stdout().flush();
            for m in errs { eprintln!("Error: {}", m); }
            std::process::exit(2);
        }
        Ok((Block { stmts: prog }, kinds))
    }
}
